import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Молитва рівноапостольній Марії Магдалині, мироносиці","e":"Prayer to the Equal-to-the-Apostles Mary Magdalene, the Myrrh-Bearer","secs":[{"h":"Тропар, глас 1","ps":["Христу́, нас ра́ди от Ді́ви ро́ждшемуся, / честна́я Магдали́но Марі́є, послі́довала єси́, / Того́ оправда́нія і зако́ни храня́щи. / Ті́мже днесь всесвяту́ю твою́ па́м'ять пра́зднующе, / гріхо́в разріше́ніє // моли́твами твої́ми приє́млем."]},{"h":"Кондак, глас 3","ps":["Предстоя́щи, пресла́вная, у Креста́ Спа́сова со іни́ми мно́гими, / і Ма́тері Госпо́дні состра́ждущи, і сле́зи точа́щи, / сіє́ в похвалу́ приноша́ше глаго́лющи: / что сіє́ єсть стра́нноє чу́до? / Содержа́й всю твар, пострада́ти ізво́ли. // Сла́ва держа́ві Твоє́й."]},{"h":"Молитва перша","ps":["О свята́я мироно́сице і всехва́льная равноапо́стольная Христо́ва учени́це Магдали́но Марі́є! К тебі́, я́ко ві́рній і мо́щній о нас к Бо́гу хода́тайце, грі́шнії і недосто́йнії, ни́ні усе́рдно прибіга́єм і в сокруше́нії серде́ць на́ших мо́лимся. Ти в житії́ своє́м стра́шния ко́зні бісо́вськия іспита́ла єси́, но благода́тію Христо́вою я́вно тіх свободи́лася єси́, і нас моли́твами твої́ми от сі́ті бісо́вськия ізба́ви, да ви́ну во всем житії́ на́шем ді́лом, сло́вом, ми́слію і та́йними помишле́нії серде́ць на́ших ві́рно послу́жим єди́ному Свято́му Влади́ці Бо́гу, я́коже Тому́ обеща́лися єсьми́. Ти па́че всіх благ земни́х сладча́йшаго Го́спода Ісу́са возлюби́ла єси́ і Тому́ чрез все житіє́ до́брі послі́довала єси́, Боже́ственними уче́нії Єго́ і благода́тію не то́кмо свою́ ду́шу пита́ющи, но і мно́жество люде́й от тьми язи́чеськия ко Христа́ чу́дному сві́ту приводя́щи; то ві́дуще, про́сим тя: іспроси́ нам у Христа́ Бо́га благода́ть просвіща́ющую і освяща́ющую, да, є́ю осіня́ємі, преуспіва́єм во ві́рі і благоче́стії, в по́двизіх любве́ і самоотверже́нія, да нелі́ностно тщі́мся служи́ти бли́жнім в їх ну́ждах духо́вних і тіле́сних, па́м'ятующе примі́р твоєго́ человіколю́бія. Ти, свята́я Марі́є, бо́дренно благода́тію Бо́жиєю протекла́ єси́ житіє́ на землі́ і ми́рно отшла́ єси́ во оби́телі Небе́сния, моли́ Христа́ Спа́са, да моли́твами твої́ми сподо́бит нас непреткнове́нно соверши́ти стра́нствіє на́ше в сей юдо́лі пла́ча і в ми́рі і покая́нії сконча́ти живо́т наш, да та́ко і в свя́тости на землі́ пожи́вше, ві́чния блаже́нния жи́зні на Небесі́ сподо́бимся і та́мо с тобо́ю і всі́ми святи́ми вку́пі ви́ну восхва́лим Тро́йцю Неразді́льную, воспої́м Єди́но Божество́, Отця́ і Си́на і Ду́ха Всесвята́го, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, свята́я мироно́сице, равноапо́стольная Магдали́но Марі́є! Ти те́плою любо́вію своє́ю ко Христу́ Бо́гу попра́ла єси́ зли́я ко́зні вра́жия і обріла́ єси́ бесці́нний би́сер Христа́, і дости́гла єси́ Ца́рства Небе́снаго. Сего́ ра́ди к тебі́ припа́даю і умиле́нною душе́ю і сокруше́нним се́рдцем вопію́ ті, аз недосто́йний: при́зри с висоти́ Небе́сния на м'я, бори́маго гріхо́вними іскуше́нії, виждь, коль мно́гими гріхи́ і бі́дами на всяк день враг запина́єть м'я, іща́ моє́й поги́белі. Сла́вная і всехва́льная учени́це Христо́ва Марі́є! Умоли́ возлю́бленного тобо́ю і возлюби́вшаго тя Христа́ Бо́га, да пода́сть мі оставле́ніє мно́гих мої́х прегріше́ній, укріпи́ть м'я благода́тію Своє́ю тре́звенно і бо́дренно ше́ствовати путе́м святи́х за́повідей Єго́ і да соді́лаєть м'я благоуха́нний храм Ду́ха Свята́го, да та́ко в ми́рі непости́дно сконча́ю многотру́дноє житіє́ моє́ на землі́ і вселю́ся в сві́тлия і блаже́нния оби́телі рая́ Небе́снаго, іді́же ти со всі́ми святи́ми ви́ну ра́достно славосло́виши Єдиносу́щную Тро́йцю, Отця́ і Си́на і Ду́ха Всесвята́го. Амі́нь."]}],"notes":[]},{"u":"Молитва мученикам і сповідникам Гурію, Самону і Авіву","e":"Prayer to the Martyrs and Confessors Gurias, Samonas and Abibus","secs":[{"h":"Тропар, глас 5","ps":["Чудеса́ святи́х Твої́х му́ченик / сті́ну необори́мую нам дарова́вий, Христе́ Бо́же, / тіх моли́твами сові́ти язи́ков разори́, / Це́рков святу́ю укріпи́, // я́ко Єди́н Благ і Человіколю́бець."]},{"h":"Кондак, глас 2","ps":["С висоти́ му́дрії благода́ть приє́мше, / су́щим во іскуше́ніїх предстої́те, всехва́льнії. / Ті́мже отрокови́цю святі́ї от сме́рти го́ркия ізба́висте: // ви бо воі́стину єсте́ Єде́су сла́ва і ми́ру ра́дость."]},{"h":"Молитва","ps":["О святі́ї му́ченици і іспові́дниці Христо́ви Гу́ріє, Само́не і Ави́ве! Те́плії о нас хода́таї і моли́твенниці пред Бо́гом, во умиле́нії серде́ць на́ших, взира́я на пречи́стий ваш о́браз, смире́нно мо́лим вас: усли́шіте нас, грі́шних і недосто́йних рабо́в свої́х, су́щих в біда́х, ско́рбіх і напа́стіх, і призрі́в на́ша тя́жкая і безчи́сленная прегріше́нія, яві́те нам свою́ вели́кую ми́лость, воздви́гніте нас із глубини́ гріхо́вния, просвіті́те наш ум, см'ягчі́те зло́є і окая́нноє се́рдце, прекраті́те за́висть, вражду́ і раздо́ри, в нас живу́щиє. Осіні́те нас ми́ром, любо́вію і стра́хом Бо́жиїм, умолі́те милосе́рднаго Го́спода, да покри́єть мно́жество гріхо́в на́ших Свої́м неізрече́нним милосе́рдієм. Да соблюде́ть Це́рков Свою́ Святу́ю от неві́рія, єресе́й і раско́лов. Да пода́сть страні́ на́шей мир, благоде́нствіє, землі́ плодоро́діє; супру́гом любо́в і согла́сіє; ча́дам послуша́ніє; оби́димим терпі́ніє; оби́дящим страх Бо́жий; скорб'я́щим благоду́шіє; ра́дующимся воздержа́ніє. Всіх же нас да покри́єть Своє́ю всеси́льною десни́цею, і да ізба́вить от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, і напра́сния сме́рті. Да огради́ть нас ополче́нієм святи́х Свої́х а́нгелов, во є́же ізба́витися нам по ісхо́ді на́шем із житія́ сего́ от ко́зней лука́ваго і та́йних возду́шних мита́рств єго́, і неосужде́нними предста́ти Престо́лу Го́спода Сла́ви, іді́же ли́ци святи́х А́нгел со всі́ми святи́ми ви́ну сла́в'ять пресвято́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому праведному Олексію Мечеву","e":"Prayer to the Holy Righteous Alexis Mechev","secs":[{"h":"Тропар, глас 3","ps":["Я́ко чу́до Бо́жиє яви́лся єси́, / в гра́ді Московстем, о́тче Алексі́є, / не в пусти́ні бо, но посреді́ молви́ процві́л єси́, / в годи́ну лю́ту богоотступле́нія, / оба́че дре́внім уподо́бился єси́, / прови́дець сий, моли́твенник і ста́рець, / і стра́ждущим уті́шитель і врач, / сего́ ра́ди о Українській па́стві, / хода́тай ни́ні бу́ди непрело́жен, // моли́твенниче о душа́х на́ших."]},{"h":"Тропар на перенесення мощей, глас 4","ps":["Наста́ день но́ваго торжества́, / град Київ ра́дується, / і вся Українськая страна́ ликовству́єть / но́вими пі́ньми духо́вними, / днесь бо свяще́нноє торжество́ / в пренесе́ніє честни́х і многоціле́бних моще́й / пра́ведника і чудотво́рця Алексі́я, / я́ко бо світи́ло пресві́тлоє, / воссія нам благода́тними луча́ми, / потребля́я тьму неду́г і страсте́й / от пою́щих прилі́жно, / спаса́й нас моли́твами твої́ми // пра́ведне Алексі́є о́тче наш."]},{"h":"Тропар, глас 1","ps":["Помози́ в біда́х, уті́ши в ско́рбіх, / па́стирю до́брий, о́тче Алексі́є. / По́двигом бо ста́рчества ми́ру просія́вий, / ві́ру і любо́в Христо́ву во мра́ці беззако́нія іспові́дал єси́, / болі́знуя се́рдцем о всіх притека́ющих к тебі́ // І ни́ні за ни Бо́га моли́, любо́вію чту́щия тя."]},{"h":"Кондак, глас 2","ps":["Ве́лії труди́ любве́ і милосе́рдія под'я́л єси́, / пра́ведний ста́рче Алексі́є, / от свята́го па́стиря Кроншта́дтськаго благослове́ніє на по́мощ стра́ждущим прия́в, / бі́ди і ско́рби людські́я я́ко вери́ги на ра́мо своє́ возложи́. / Ми же ві́дуще тя моли́твенника дерзнове́нна ко Го́споду, со умиле́нієм зове́м ті: // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний о́тче Алексі́є, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]},{"h":"Молитва перша","ps":["О всечестни́й і преблаже́нний о́тче наш Алексі́є, ди́вний ста́рче Моско́вський і всея́ Це́ркве Українськия похвало́ і ра́дованіє! Ве́лію любо́в ко Го́споду імі́я, заві́ти Єва́нгельськия непрело́жно ісполня́я, ду́шу твою́ за па́ству полага́л єси́, се́рдцем ми́лующим болі́знуя о всіх, прося́щих твоєя́ по́мощі. Прийми́ ма́лоє сіє́ моле́ніє на́ше, і я́ко в земно́м житії́ твоє́м вся́ку слезу́ утоля́л і от вся́кия ско́рби ізбавля́л єси́, та́ко і ни́ні, милосе́рдний моли́твенниче і хода́таю наш, возьми́ тяготи́, болі́зні і ско́рби на́ша, іспо́лни стра́ждущая сердца́ ра́достію і умоли́ Человіколю́бця Бо́га о проще́нії прегріше́ній на́ших; да очи́стив ду́шу покая́нієм, к доброді́тельному житію́ обраті́мся. Єй, ста́рче Алексі́є, бу́ди і нам па́стир до́брий, на стезю́ спасе́нія наставля́ющий, да моли́твами твої́ми безпоро́чно про́йдем путь житія́ на́шего і обря́щем Оте́чество Небе́сноє, іді́же ти со а́нгели і всі́ми святи́ми предстої́ши Престо́лу Святи́я Тро́йці, сла́в'ящеє Безнача́льного Отця́ со Єдиноро́дним Єго́ Си́ном і Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["К тебі́, о пра́ведний о́тче Алексі́є, ми, грі́шнії і недостоїнії, притека́єм і со умиле́нієм взива́єм ті: при́зри ни́ні ми́лостивно с висоти́ святи́я своєя́ на Оте́чество на́ше і нас, тя прославля́ющих. Прия́вший в житії́ своє́м тяготи́ люде́й і се́рдцем, милующим понеси́й ско́рби їх, прийми́ в моли́твенноє твоє́ предста́тельство і нас, гріхи́ мно́гими обремене́нних і суєто́ю ми́ра сего́ утружденних. В тебі́, о ди́вний ста́рче, просла́вися Госпо́дь, яви́в тя тайнником ми́лости Бо́жієй. Тя призива́єм неотсту́пно: бу́ди врач душа́м і тілесе́м на́шим, унивающим - уті́шитель, малоду́шним дерзнове́ніє низпосли́, помраче́нних зло́бою всепроще́нію научи́, воздержа́нію спосо́бствуй. Воспламени́, благи́й ді́лателю виногра́да Христо́ва, хладниє се́рдця на́ша ре́вностію служе́нія твоєго́, научи́ моли́тві непреста́нной і деятельной любве́ с утесненієм себе́ ра́ди бла́га бли́жніх на́ших. Укріпи́ моли́твами твої́ми ча́да Це́ркві на́шея, да поживе́м в любве́ і ми́ре, а вні огра́ди церко́вния пребива́ющії да уразумі́ють Христо́ву І́стину і вку́пі с на́ми просла́в'ять Животворя́щую і Неразді́льную Тро́йцю і твоє́ ми́лостивноє предста́тельство во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іоасафу Білгородському","e":"Prayer to St Joasaph of Belgorod","secs":[{"h":"Тропар, глас 3","ps":["Святи́телю Христу́ Бо́гу возлю́бленне, / пра́вило ві́ри і о́браз милосе́рдія лю́дем бил єси́, / бді́нієм же, посто́м і моли́твою, / я́ко світи́льник пресві́тлий, просія́л єси́ / і просла́влен от Бо́га яви́лся єси́: / ті́лом у́бо в нетлі́нії почива́я, / ду́хом же Престо́лу Бо́жию предстоя́, / чудеса́ пресла́вная істоча́єши. / Моли́ Христа́ Бо́га, / да утверди́ть нас в Правосла́вії і благоче́стії // і спасе́ть душі́ на́ша."]},{"h":"Кондак, глас 8","ps":["Многоразли́чния по́двиги житія́ твоєго́ кто іспові́сть? / Многообра́зния ми́лости Бо́жия, тобо́ю явле́нния, кто ісчи́слить? / Дерзнове́ніє же твоє́ у Пречи́стия Богоро́диці і Всеще́драго Бо́га до́брі ві́дуще, / во умиле́нії серде́чнім зове́м ті: / не лиши́ і нас твоєя́ по́мощі і заступле́нія, // святи́телю Христо́в і чудотво́рче Іоаса́фе."]},{"h":"Молитва перша","ps":["О святи́телю Христо́в Іоаса́фе, чудотво́рче Білогра́дський! Ві́руєм грі́шнії і недосто́йнії, я́ко о́чі Госпо́дні на пра́ведних і у́ші Єго́ на моли́тву їх, і того́ ра́ди к моли́твам твої́м прибіга́єм і хода́тайства твоєго́ за нас про́сим, по глаго́лу апо́стольському упова́юще, я́ко люби́ твоєя́ ніколи́же отпа́даєть. Во грісі́х і болі́зніх на́ших льну куря́щемуся і тро́сти сокруше́нній уподо́бихомся, і, а́ще живе́м, ми́лостію Бо́га живе́м і за моли́тви пра́ведник Єго́. Приклони́ у́бо і ти, о́тче пра́ведне, се́рдце твоє́ к моле́нію на́шему, і предста́тельством твої́м даждь ро́ду христия́нському от Го́спода мир і благослове́ніє. Правосла́віє укріпи́, нападе́нія же лука́внующих і беззако́нних на це́рков Бо́жию отжени́. Умоли́ Отця́ небе́снаго ізба́витися нам от наше́ствія вра́жеськаго, от междоусо́бій же і см'яте́ній наро́дних, от губи́тельних пові́трій і смертоно́сния я́зви, от гла́да, огня́, пото́па і іни́х бід і обстоя́ній. Іспроси́ у Христа́ Бо́га душа́м на́шим крі́пость і тілесе́м на́шим потре́бноє здра́віє, болі́знем же ісціле́ніє: хроми́м хожде́ніє, сліпи́м прозрі́ніє, разсла́бленним утвержде́ніє, печа́льним утіше́ніє і от всіх скорбе́й ізбавле́ніє. Отпа́дшия же лози́ Христо́ви ві́тві па́ки с то́ю соєдини́, єя́же і сам прича́стник би́ти сподо́бился єси́, да та́ко просла́виться тобо́ю пречестно́є і великолі́поє і́м'я Бо́га на́шего, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва, що промовляється перед чесними мощами святителя","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче, святи́телю Іоаса́фе! От да́льних і бли́жніх градо́в і ве́сей соше́дшеся, во є́же на мі́сті по́двигов твої́х помоли́тися і многоцелелебния мо́щі твоя́ облобиза́ти, із глубини́ се́рдця взива́єм к тебі́: жезло́м бла́гости, я́коже па́стир до́брий, упаси́ заблу́дшия о́вці стада́ Христо́ва, во двори́ Госпо́дні сія́ всели́, огради́ нас от собла́зна, єресе́й і раско́лов, научи́ во стра́нствії су́щих го́рняя му́дрствовати: разсі́янний ум наш просвіти́ і на путь і́стини напра́ви, охладі́вшеє се́рдце согрі́й любо́вію ко бли́жнему і ре́вностію к ісполне́нію велі́ній Бо́жиїх, гріхо́м і нераді́нієм осла́бленную во́лю на́шу оживотвори́ благода́тію Ду́ха всесвята́го: да твоєму́ па́стирському гла́су послі́дующе, сохрани́м в чистоті́ і пра́вді душі́ на́ша, і та́ко, Бо́гу помога́ющу, небе́снаго ца́рствія дости́гнем, іді́же ку́пно с тобо́ю воспросла́вим пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Ду́ха Свята́го во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя, подячна","ps":["О вели́кий Святи́телю наш і чудотво́рче преди́вний Іоаса́фе, ско́рий помо́щниче к тебі́ припа́дающих! Ми́лостивно при́зри на нас недосто́йних, со слеза́ми умиле́нія зді моля́щихся і благодаре́ніє тебі́ по си́лі принося́щих. Благодари́м тя, уго́дниче Христо́в, я́ко усли́шал єси́ моле́нія нас недосто́йних і проси́мая нам оби́льно дарова́л єси́. Ві́ми і усти́ іспові́дуєм, я́ко воі́стину Христу́ те́плий о нас єси́ моли́твенник і, по да́нной ті благода́ті і да́ру, во спасе́ніє всім нам потре́бная да́руєши: боля́щия ісціля́єши, стра́ждущия утіша́єши, мир і отра́ду ско́рбним сердця́м ізлива́єши, пла́чущия ра́доватися твори́ти, печа́ль-ния ликова́ти содіва́єши: роди́телем ча́да воздравля́єши, супру́гом подру́жія от одра́ сме́ртнаго возставля́єши, враждующия умиротворя́єши, зави́стливия твори́ши ми́лостиви, і вся́кия непра́вди кара́єши, я́коже і в житії́ твоє́м пра́вди і милосе́рдія му́жественний ревни́тель бил єси́. Благодари́м тя, Святи́телю, за вели́кая твоя́ і нам явле́нная благодія́нія, і смире́нно мо́лимся тебі́ ми недосто́йнії: предста́тельствуй за нас у престо́ла Христо́ва, і помози́ нам па́м'ять при́сную твої́х благодія́ній і щедро́т на нас ізлія́нних храни́ти, да во смире́нії се́рдця про́чеє соверши́м житіє́, і небе́сноє да наслі́дуєм селе́ніє Боже́ственноє, моли́твами твої́ми, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта, про недугуючих і страждущих","ps":["О вели́кий уго́дниче Христо́в, святи́телю о́тче наш Іоаса́фе, ско́рий помо́щниче і ди́вний чудотво́рче! При́зри ми́лостивно на ни неду́гующия. Ві́ми, уго́дниче Христо́в, ві́ми, і усти́ і се́рдцем іспові́дуєм, я́ко по ді́лом на́шим біди́ постиго́ша нас. С разбо́йником благоразу́мним іспові́дуєм Го́сподеві, я́ко достойнная по ді́лом на́шим восприє́млем і зла́я сія́ я́коже раби́ неключи́мії терпи́м. Си́ми бо вре́менними муче́ньми Госпо́дь милосе́рдий сокруша́єть горди́ню і жестокови́йноє се́рдце на́ше, да ві́чния ізбіжи́м ка́зні, грі́шником угото́ванная: сіяхом бо сі́мена житія́ своєво́льнаго, і жнем те́рнія скорбе́й. Оба́че, немощні́ї су́ще, но в покая́ніє те́плоє прише́дше, о сем моли́тися дерза́єм, да гнів Госпо́день на ми́лость к нам преложи́ться, і тебі́, святи́телю Бо́жий і чудотво́рче, усе́рдно про́сим: проли́й те́плую моли́тву твою́ ко Христу́ Го́споду на́шему, єму́же днесь предстої́ши і мо́лишися о почита́ющих тя с любо́вію і смире́нним на твоє́ предста́тельство упова́нієм. Се бо в житії́ твоє́м, Святи́телю Христо́в, ні єди́наго же скорб'я́ща і ми́лости твоєя́ прося́ща, гріхи́ же своя́ іспові́дающа, ніколи́же презрі́л єси́. Умоли́ пра́веднаго судію́, да преложи́ть гнів пра́вди своєя́ на ми́лованіє на́ше. Благода́тію єго́ тебі́ да́нною, святи́телю милосе́рдий, уврачу́й на́ша не́мощі, болі́зней лю́тих тече́нія уста́ви, сме́рті отити́ повели́, і на покая́ніє си́лу нам да́руй. Ста́рость поддержи́, младе́нці воспита́й, ю́ность уцілому́дри, супру́жества в чистоті́ і смире́нії утверди́, нам же всім послуша́ніє трудолю́бноє і ми́рноє жи́тельство моли́твою твоє́ю да́руй, да терпі́нієм тече́м на предлежа́щий нам по́двиг житія́ сего́ временного, взира́юще на нача́льника ві́ри і соверши́теля Го́спода Ісу́са. Єму́же сла́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва в день прославлення святителя","ps":["Вели́кий і пра́зднственний день сей, день твоєго́ на землі́ прославле́нія, святи́телю о́тче наш Іоаса́фе, землі́ на́шея сла́во і ра́дованіє вели́коє, прийми́ сія́ смире́нная і те́плая моле́нія на́ша. Днесь зрим іспо́лнившийся глаго́л Госпо́день: прославляющия М'я просла́влю. Се бо во дні земна́го житія́ твоєго́ нічто́же іска́л єси́, то́чію же во́лю Бо́жию ісполня́ти і ча́да па́стви твоєя́ упра́вити во спасе́ніє, і того́ ра́ди мно́гія труди́, ско́рби, болі́зні, путеше́ствія под'ял єси́. По сконча́нії же твоє́м просла́ви тя милосе́рдий Госпо́дь, тілесі́ твоєму́ нетлі́ніє і си́ли ціле́бния дарова́вий; ті́мже то́ки ісціле́ній молящимся істочи́л єси́ і призива́ющим тя недугующим і скорб'я́щим мно́гажди являлся єси́, і утіше́ніє і цільбу́ ско́рую тім подава́я. Сего́ ра́ди, я́коже ізбра́нника Боже́ственния благода́ті тя ві́дущи, Це́рков Христо́ва просла́віте тя я́коже но́ваго чудотво́рця землі́ на́шея сподо́бися. Благослови́ у́бо і поми́луй, архієре́ю і́стиннаго Бо́га, лю́ди правосла́вния. Да́руй їм утіше́ніє се́рдця, отра́ду і мир і ра́дость при́сную о Го́споді. Сохрани́ в ми́рі держа́ву Українськую і лю́ди єя́ во і́стині утверди́, во́їном му́жество непоколеби́моє да́руй і вся лю́ди безпеча́льни сохрани́. Ізжени́ вся́кую крамолу́ і крамо́льних челові́к лука́вая разруши́ сові́тованія, па́че же тіх са́мих в покая́ніє приведи́. Па́стирем і архиреєм пода́ждь прему́дрость, чистоту́ і пра́ведноє житіє́, я́коже і сам си́ми украша́лся єси́. Младе́нцем воспита́ніє благо́є даждь, ю́ния научи́, боля́щим і скорб'я́щим здра́віє іспроси́. Су́щим во труді́х терпі́ніє і упова́ніє посли́, бога́тим смиренному́дріє і ко бли́жнім милосе́рдіє да́руй. Нам же всім ра́дость о Го́споді при́сную пода́ждь, да всі благода́рні тя ублажа́єм, глаго́люще та́ко: велича́єм тя, святи́телю о́тче Іоаса́фе, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва праведному Феодору (Ушакову) воїну, Синаксарському","e":"Prayer to the Righteous Warrior Theodore (Ushakov) of Sanaxar","secs":[{"h":"Тропар, глас 1","ps":["Держа́ві Українській архистрати́г непобіди́мий яви́лся єси́, / ага́ринськую зло́бу нівочто́же вміни́в і разори́в: / не сла́ви мирськи́я, ніже́ в бога́тства взиску́я, / но Бо́гу і бли́жнему послужи́л єси́, / моли́, свя́те Фео́доре, / во́їнству на́шему дарова́ти на враги́ одолі́ніє, / оте́честву во благоче́стії непоколеби́му преби́ти, / і синово́м Українським спасти́ся."]},{"h":"Кондак, глас 2","ps":["Архістрати́же Український, / служи́телю наро́да Бо́жіяго, / ни́щих і угнете́нних свободи́телю, / нечести́вих наказа́телю, / поле́зноє нам проси́ і ве́лію ми́лость, / я́ко спобо́рник наш пра́ведне боля́рине Фео́доре."]},{"h":"Молитва перша","ps":["О пресла́вний защи́тниче землі́ українськия і ві́ри Правосла́вния усе́рдний побо́рниче, непобіди́ме во́їне Фео́доре! Ніка́я благода́рственная словеса́, ніже́ ізя́щная вити́йства довлі́ють, во є́же просла́вити пра́ведноє і ди́вноє твоє́ житіє́, поне́же ізмла́да крі́пкую ві́ру во Христа́ і любо́в ко оте́честву стяжа́в, благопло́дноє прозябе́ніє честни́х роди́телей яви́лся єси́. Сего́ бо ра́ди, Бо́жию да́ру тезоімени́ть, страні́ своє́й в ско́рбния времена́ бра́ней про́тив іноплеме́нних показа́лся єси́. І́бо, пра́ведним воєво́дам подража́я, не число́м і уме́ним то́кмо, но па́че ві́рою враги́ побіжда́л єси́, си́лу благоче́стія і́стиннаго показу́я. Ті́мже любо́вію к тебі́ распаля́ємі, воспіва́єм мно́гія доброді́телі твоя́: ве́лію любо́в ко Го́споду і бли́жнім, зане́ тіх ра́ди живо́т полага́л єси́, чистоту́ ангелоподо́бную, та́ко вся воздержа́нієм удиви́л єси́, нестяжа́ніє і́стинноє, і́бо блага́я і кра́сная ми́ра сего́ презрі́л єси́. Єй, преблаже́нне Фео́доре, уго́дниче Бо́жий і благові́рний боля́рине царе́й правосла́вних, при́зри на убо́гоє моле́ніє на́ше, із гріхо́внаго плі́на к тебі́ возноси́моє. Приклони́ на ми́лость Го́спода на́шего Ісу́са Христа́, да не возда́сть по діла́м на́шим, но оба́че да́руєть гріхо́в оставле́ніє, ізба́вить от злих, находя́щих на ни, і пода́сть власте́м на́шем і наро́ду усе́рдноє попече́ніє, во́їнству му́жество во ра́тіх, наро́ду благоче́стіє тре́звенноє. І сподо́бит нас дости́гнути безм'ятежнаго приста́нища во Ца́рствії Небе́снім, іді́же со всі́ми святи́ми прославля́ти бу́дем всесвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Прини́кни, пра́ведне во́їне Фео́доре, с го́рніх селе́ній на притека́ющих к тебі́ і воньми́ моле́нію їх: умоли́ Го́спода Бо́га дарова́ти всім нам є́же ко спасе́нію на́шему ми про́сим от Него́, при святі́м твоє́м предста́тельстві. Ти вели́коє, возло́женноє на тя служе́ніє тща́тельно проходи́л єси́, і нас твоє́ю по́мощію пребива́ти коєго́ждо, в не́мже при́зван єсть, наста́ви. Ти, побіди́в супоста́тов мно́жества, і на нас ополча́ющихся всіх ви́димих і неви́димих враго́в низложи́. Умоли́ Го́спода Бо́га дарова́ти крі́пкий і ненаруши́мий мир і землі́ плодоно́сіє, па́стирем святи́ню, зако́нам пра́вду і си́лу, воєнача́льникам му́дрость і до́блесть непобіди́мую, градонача́льникам суд, фло́ту твоєму́ українському і всему́ во́їнству на́шему пре́данность ві́рі і Оте́честву і неодоли́моє му́жество, всім же правосла́вним христия́нам здра́віє і благоче́стіє. Сохраня́й страну́ на́шу українськую і оби́тель сію́ святу́ю от всіх наві́тов вра́жиїх, да сло́вом і ді́лом прославля́ється в них всесвято́є І́м'я Отця́, і Си́на, і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому благовірному Олегу Брянському","e":"Prayer to the Holy Right-believing Oleg of Bryansk","secs":[{"h":"Тропар, глас 8","ps":["От ю́ности возлюби́в Христа́ всім се́рдцем, преподо́бне, сла́ву земну́ю, я́ко преходя́щу, оста́вил єси́ і, ца́рство земно́є в нічто́же вміни́в, ли́ку і́нок ра́достно приче́лся єси́, і труди́ мно́гими град Брянск, а́ки со́лнце пресві́тло, озари́л єси́: тім бив Тро́йці украше́ніє, моли́, кня́же Оле́же, Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Уподо́бился єси́ плодоносней лі́торасли от ко́рене честна́го, Оле́же благоро́дне, і́стину возлюби́в і нетлі́нний Христо́в живо́т. Ті́мже моли́твою, бді́нієм і поще́нієм світи́льник вели́кий бив твої́м ученико́м, просвіти́, блаже́нне, оте́чество твоє́ і спаси́ душі́ на́ша."]},{"h":"Молитва перша","ps":["О преподо́бне о́тче, благові́рне кня́же Оле́же, уго́дниче Христо́в усе́рдний, моли́твенниче ко Го́споду те́плий, защи́тниче в біда́х і уті́шителю в печа́ліх неуста́нний! Воззри́, всеблаже́нне, ми́лостивно на град твой і виждь ча́да твоя́, смире́нно припа́дающая і служи́ти тебі́ хотя́щая. Не отве́ргни требующия твоєя́ по́мощі, но я́ко благода́тель і хода́тай моли́ при́сно Го́спода Бо́га і Спа́са на́шего Ісу́са Христа́, да благослови́ть страну́ Українськую, в ми́рі і благові́рії ю сохраня́я, гра́ди умножа́я, достоя́ніє Своє́ соблюда́я. Вознеси́, богоно́сне о́тче наш, сіє́ ма́лоє моле́ніє недосто́йних раб твої́х Влади́ці Христу́, да утверди́ть во святі́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і любве́, благоче́стіє непоколеби́мо, любому́дріє христопослі́довательно, да да́руєть па́стирем ре́вность попече́нія о спасе́нії люде́й, во є́же неверущия просвіти́ти, заблудшия наста́вити, отпадшия обрати́ти і привлещи́. Ізря́дніє же, да вся ча́да Це́ркві Правосла́вния чи́сти сохрани́ть от мирськи́х іскуше́ній, плотськи́х по́хотей, суєму́дрія, суєві́рій і навожденій вра́жеських. Єй, уго́дниче Бо́жий, не пре́зри нас, моля́щихся тебі́, но помози́ нам ско́рим предста́тельством твої́м, да вся́ких бід, напа́стей і скорбе́й в сей жи́зні вре́менній избіжа́вше, кончи́ну непости́дну обріте́м, і та́ко благоуго́дно на землі́ пожи́вше, жи́зні ра́йськия на Небесі́ сподо́бимся, іді́же вку́пі с тобо́ю просла́вим человіколю́біє і щедро́ти в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне о́тче, благові́рне кня́же Оле́же! Воззри́, преблаже́нне, ми́лостивно на дом (парафію) сей і лю́ди, в нем живу́щия, і не отве́ржи тре́бующих твоєя́ по́мощі, не пре́зри нас, моля́щихся тебі́, но помози́ нам (імена) ско́рим предста́тельством твої́м, да вся́ких бід, напа́стей і скорбе́й в сей жи́зні вре́менній избіжа́вше, кончи́ну непости́дну обря́щем, і та́ко на землі́ богоуго́дно пожи́вше, жи́зні ра́йськия на небесі́ сподо́бимся, іді́же вку́пі с тобо́ю просла́вим человіколю́біє і щедро́ти в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, благові́рне кня́же Оле́же, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва святій мучениці Фотинії Самарянці","e":"Prayer to the Holy Martyr Photini the Samaritan Woman","secs":[{"h":"Тропар, глас 4","ps":["А́гниця Твоя́, Ісу́се, Фотиніє зове́ть ве́ліїм гла́сом: Тебе́, Женише́ мой, люблю́, і, Тебі́ і́щущи, страда́льчествую, і сраспина́юся і спогребляюся Креще́нію Твоєму́, і стражду́ Тебе́ ра́ди, я́ко да ца́рствую в Тебі́, і умира́ю за Тя, да і живу́ с Тобо́ю: но, я́ко же́ртву непоро́чную прийми́ м'я, с любо́вію поже́ршуюся Тебі́. Тоя́ моли́твами, я́ко Ми́лостив, спаси́ душі́ на́ша."]},{"h":"Кондак, глас 2","ps":["Храм твой всечестни́й я́ко цільбу́ душе́вную обрі́тше, всі ві́рнії велегла́сно вопіє́м ті: ді́во му́ченице Фотиніє, великоімени́тая, Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, свята́я му́чениця Фотинія! Безмі́рно любо́вію ко Христу́ окриляєма, му́жество, терпі́ніє і си́лу ве́лію с находящимися с тобо́ю се́страми, синовями і просвіще́нними тобо́ю яви́ла єси́. Єва́нгеліє Христо́во с дерзнове́нієм пропові́дала, і яви́ся тебі́ і всім, с тобо́ю би́вшим, Христо́с, і всіх на предстоящия муки́ укріпи́л і уті́шил. В Рим прише́дши і безбоя́зненно Христа́ іспові́давши, в темни́цю заключе́на би́ша, і мно́гія муки́ претерпі́ша, в колодезь брошена, ду́шу свою́ Го́споду предала́ єси́. Усли́ши нас, свята́я Фотинія, духо́вною красото́ю воссіявшая і люде́й непреста́нно і неумолкаємо, в темни́ці і в городах, ві́рі во Христа́ поучавшая. Внемли́ нам, взира́я на нас грі́шних, і благода́тію Христо́вою ісціли́ боля́щих лихорадкою, да не окропи́ть їх дождь гріхо́вний, но в здра́вії душе́вном і тіле́сном жизнь свою́ неосла́бно в до́брих діла́х проведуть і просла́в'ять Влади́ку всіх, Отця́ щедро́т, Бо́га Ми́лостиваго, во все ві́ка. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпице Христо́ва Фотиніє, і чтим честно́є страда́ніє твоє́, є́же за Христа́ претерпі́ла єси́."]}],"notes":[]},{"u":"Молитва преподобному Севастіану Карагандинському","e":"Prayer to St Sebastian of Karaganda","secs":[{"h":"Тропар, глас 3","ps":["Тро́йці Святи́я служи́телю, земне а́нгеле і небе́сні челові́че, духо́внаго О́птинськаго ста́рчества преє́мниче, Христо́в священнотаї́нниче і іспові́дниче, Ду́ха Свята́го оби́тель всечестна́я, преподо́бне о́тче Севастія́не, досточтиме, іспроси́ ми́рові мир і душа́м на́шим ве́лію ми́лость."]},{"h":"Молитва","ps":["О, пречестна́я і свяще́нная главо́ благода́ті Свята́го Ду́ха іспо́лненная, Спа́сово со Отце́м обита́лище, ста́рцев О́птинських учениче́ і преє́мниче, гра́да Караганди світлі́йшеє украше́ніє, Казахстанськия страни́ богодарова́нний моли́твенниче, Це́ркві Українськия па́стирю богопросла́вленний, си́рим і вдови́цям засту́пниче, немощни́х врачу́ безме́здний, пра́вило ві́ри і благоче́стія, преподо́бних сожи́телю і му́чеников соприча́стниче, богоно́сне о́тче наш Севастія́не досточтиме! К тебі́ усе́рдно прибіга́я, моле́ніє те́плоє прино́сим: от сокро́вищници твоєя́ пода́ждь і на́шему убо́жеству; смире́нієм твої́м на́шу горди́ню низложи́; безстра́стієм на́ша стра́сті попали́; бо́дрствованієм лі́ності нави́к от нас отжени́; сле́зними то́ки на́ше нечу́вствіє пробуди́; бді́нієм от нераде́нія нас возста́ви; моли́твами і в нас пла́мень моли́тви возжги́; любо́вію нас братолюбни сотвори́; пода́ждь же нам дух кро́тости і смире́нія, дух чистоти́ і благоче́стія; от страсте́й многонедужія нас свободи́ і ко і́стинному покая́нію приведи́. Ти бо во умі́ твоє́м непреста́нно імі́л єси́ на Кресті́ Расп'явшагося за нас Си́на Бо́жия, Того́ сладча́йшеє І́м'я во умі́ і в се́рдці непреста́нно імі́ти і нас научи́, да любо́вію Тому́ пламені́я, стра́шний о́ний день су́дний сретити угото́вимся, і в Ца́рствіє Небе́сноє вни́ти с тобо́ю сподо́бимся, сла́вити і воспіва́ти Трієдиную держа́ву Бо́га на́шего: Отця́ і Си́на і Ду́ха Свята́го во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Нектарію Пентапольському","e":"Prayer to St Nectarius of Pentapolis","secs":[{"h":"Тропар, глас 4","ps":["Преподо́бничеськи пожи́в, я́ко му́дрий ієра́рх, / просла́вил єси́ Го́спода / доброді́тельним житіє́м, Некта́ріє преподо́бне. / Ті́мже, Уті́шителя просла́влен си́лою, / Боже́ственними мощми́ твої́ми, / де́мони отго́ниши і боля́щия ісціля́єши, // ві́рою приходя́щия ті."]},{"h":"Кондак, глас 2","ps":["Боже́ственний гром, труба́ духо́вная, ві́ри насади́телю і отсіка́телю єресе́й, Тро́йці уго́дниче, вели́кий святи́телю Некта́ріє, со А́нгели предстоя́ при́сно, моли́ непреста́нно о всіх нас."]},{"h":"Молитва перша","ps":["О, мироточи́вая главо́, святи́телю Некта́ріє, архієре́ю Бо́жий! Во времена́ вели́каго отступле́нія, не́честію мир плени́вшу, благоче́стієм просія́л єси́ і главу́ прего́рдаго Денни́ці, уязвля́ющаго нас, сокруши́л єси́. Сего́ ра́ди дарова́ ті Христо́с врачева́ти я́зви неісце́льни, за беззако́нія на́ша нас порази́вшия. Ві́руєм: возлюби́ тя Бог пра́веднаго, да тебе́ ра́ди нас, грі́шних, поми́луєть, от кля́тви разріши́ть, от неду́г ізба́вить, і по всей вселе́нній стра́шно і сла́вно бу́деть і́м'я Єго́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, святи́телю Некта́ріє, о́тче Богому́дрий! Прийми́, блюсти́телю ві́ри правосла́вния, іспові́даніє усте́н люде́й христоімени́тих, со́бранних днесь в хра́мі благода́тію Бо́жиєю, в тебі́ живу́щею. Вість бо дости́же до преді́л Українських, я́ко ти, ве́лій во святи́х уго́дниче Христо́в, во всіх конці́х вселе́нния призива́ющим і́м'я твоє́ явля́єшися і от ра́ковия болі́зні ісціле́ніє да́руєши. Сли́шахом об ієре́є, тебі́ тезоімени́том і храм во і́м'я твоє́ созида́вшем со скорбми́ ве́ліїми. Ра́ковою у́бо я́звою грудно́ю пораже́н бі, кро́ві на всяк день точа́щейся, і стражда́ше лю́ті, ді́ла же своєго́ свята́го не оставля́ше. Внеза́пу ти, святи́телю многоми́лостиво, с Небесе́ сшед, єму́ во хра́мі предста́л єси́ во ви́димом о́бразе. Он же непщу́я тя собра́та єди́на от сме́ртних би́ти, проша́ше моли́тв твої́х і рече́: «Боля́й єсьм вельми́, оба́че хощу́ святи́й олта́р назда́ти, да поне́ єди́ножди святу́ю Літургі́ю вку́пі с прихожа́ни совершу́; послі́жде і умре́ти гото́в єсьм, смерть бо м'я не страши́ть». Ти же, о́тче, безпло́тен сий, слеза́ми лице́ своє́ ороша́ше! І об'є́м страда́льця, лобиза́ше і глаго́ля: «Не тужи́, ча́до моє́, я́ко, болі́знію іспи́тан, здрав бу́деши. Всі у́бо о чудеси́ сем ві́дати і́муть». Он же, ісціле́н бив, а́біє разумі́, с кім бесі́доваше, тебі́ неви́диму би́вшу. О, вели́кий уго́дниче Христо́в Некта́ріє! Храм о́ний сверше́н єсть ни́ні, і чудеса́ твої́ а́ки мо́ре преізлива́ющеєся умно́жишася! Ми же позна́хом, я́ко моли́тві пра́ведника до́лжно поспешеству́ємой би́ти усе́рдієм на́шим к слу́жбі Бо́жієй і реши́мостью за Христа́ умира́ти, да здра́ві обря́щемся. Мо́лять тя, о́тче пра́ведний, боля́щая ча́да твоя́: да соверша́ється с на́ми во́ля Бо́жия, блага́я, уго́дная і соверше́нная, не хотя́щи сме́рті грі́шнику, но є́же обрати́тися і жи́ву би́ти єму́. Ти же, провозві́стниче во́лі Бо́жієй, ісціли́ ни благода́тним явле́нієм свої́м, да вели́к бу́деть Бог на Небесі́ і на землі́ во ві́ки віко́в! Амі́нь."]}],"notes":[]},{"u":"Молитва святим семи отрокам в Ефесі","e":"Prayer to the Holy Seven Youths of Ephesus","secs":[{"h":"Тропар, глас 8","ps":["Благоче́стія пропові́дники і воскресе́нія уме́рших ізобразители, Це́ркві столпи́ седьмочи́сленния, о́троки всеблаже́нния пі́сньми восхва́лим: ті́ї бо по мно́гих лі́тіх нетлі́нія, а́ки от сна воста́вше, всім возвісти́ша я́ві ме́ртвих воста́ніє."]},{"h":"Кондак, глас 4","ps":["Просла́вивий на землі́ святи́я Твоя́, пре́жде втора́го і стра́шнаго прише́ствія Твоєго́, Христе́. Пресла́вним воста́нієм отроко́в показа́л єси́ Воскресе́ніє неведящим є, нетлі́нна одія́нія і тілеса́ яви́в, і царя́ уві́рил єси́ вопи́ти: воі́стину єсть ме́ртвих воста́ніє."]},{"h":"Молитва","ps":["О, пречу́днії святі́ї седьмочи́сленнії о́троци, Єфе́са гра́да похвало́ і всея́ вселе́нния упова́ніє! Воззрі́те с висоти́ небе́сния сла́ви на нас, любо́вію па́м'ять ва́шу чту́щих, найпа́че же на младе́нці христия́нськия, ва́шему заступле́нію от роди́телей свої́х препоруче́нния: низведі́те на ни благослове́ніє Христа́ Бо́га, ре́кшаго: оста́віте діте́й приходить ко Мні: боля́щия у́бо в них ісцілі́те, скорб'я́щия уті́шіте; се́рдця їх в чистоті́ соблюді́те, кро́тостію іспо́лніте я, і в землі́ серде́ць їх зе́рно іспові́данія Бо́жия насаді́те і укріпі́те, во є́же от си́ли в си́лу їм возрасти́ти; і всіх нас, святі́й іко́ні ва́шей предстоя́щих, мо́щі же ва́ша с ві́рою лобиза́ющих і те́плі вам моля́щихся, сподо́біте Ца́рствіє Небе́сноє улучи́ти і немо́лчними гла́си ра́дованія та́мо прославля́ти великолі́поє і́м'я Пресвяти́я Тро́йці, Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["Бо́же вели́кий, хва́льний і непостижи́мий, і неісповіди́мий, созда́вий челові́ка руко́ю Твоє́ю, персть взем от землі́, і о́бразом Твої́м почти́вий єго́, Ісу́се Христе́, прежела́ємоє і́м'я, со Безнача́льним Твої́м Отце́м і с Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, яви́ся на рабі́ Твоє́м (ім’я), і посіти́ єго́ ду́шу і ті́ло, умоля́єм от пресла́вния Влади́чиці на́шея Богоро́диці і Присноді́ви Марі́ї, святи́х Небе́сних Сил Безпло́тних, і честна́го сла́внаго проро́ка, і Предте́чі і Крести́теля Іоа́нна, святи́х сла́вних і всехва́льних апо́столов, і́же во святи́х оте́ць на́ших, і вселе́нських учи́телей, Васи́лія Вели́каго, Григо́рія Богосло́ва, Іоа́нна Златоу́стаго, Афана́сія і Кири́лла, Никола́я і́же в Ми́ріх, Спиридо́на чудотво́рця, і всіх святи́х священнонача́льников, свята́го апо́стола первому́ченика і архідия́кона Стефа́на, святи́х сла́вних великому́чеников Гео́ргия Побідоно́сця, Дими́трія Мирото́чця, Фео́дора Стратила́та, і всіх святи́х му́чеников, преподо́бних і богоно́сних оте́ць на́ших Анто́нія, Євфи́мія, Са́вви Освяще́ннаго, Феодо́сія о́бщаго житія́ нача́льника, Ону́фрія, Арсе́нія, Афана́сія Афо́нськаго, і всіх преподо́бних, святи́х і ісціли́телей, безсре́бренников Косьми́ і Дамія́на, Ки́ра і Іоа́нна, Фалалея і Три́фона і про́чих, свята́го пра́веднаго Іоа́нна Кроншта́дтськаго, свята́го преподо́бнаго Іоа́нна Ри́льськаго, святи́я блаже́нния Ксе́нії Петербуржськой і всіх Твої́х святи́х. І даждь єму́ сон упокоє́нія, сон тіле́сний здра́вія і спасе́нія і живота́, і крі́пость душе́вную і тіле́сную, я́коже посіти́л єси́ іногда́ Авимеле́ха уго́дника Твоєго́ во хра́мі Агри́ппові, і дал єси́ єму́ сон утіше́нія, є́же не ви́діти паде́нія Ієрусали́мова, і сего́ успи́вий сном пита́тельним, і па́ки сего́ воскреси́вий во єди́ном мгнове́нії вре́мене, в сла́ву Твоєя́ бла́гости. Но і святи́я Твоя́ сла́вния седьм о́троки, іспові́дники і свиді́телі Твоєго́ явле́нія показа́вий, во дні Декия царя́ і отсту́пника, і сія́ успи́вий во верте́пі на літ сто і о́смдесят, я́ко младе́нці согріва́ємия в ложесна́х ма́тере своєя́, і ніка́коже претерпі́вшия тлі́нія, в похвалу́ і сла́ву человіколю́бія Твоєго́, і в показа́ніє, і ізвіще́ніє на́шего пакибитія́, і воскресе́нія всіх. Сам у́бо человіколю́бче Царю́, предста́ни і ни́ні наї́тієм","Свята́го Твоєго́ Ду́ха, і посіти́ раба́ Твоєго́ (ім’я), і да́руй єму́ здра́віє, крі́пость, і благомо́щіє, Твоє́ю бла́гостію, я́ко от Тебе́ єсть вся́ко дая́ніє бла́го, і всяк дар свершен. Ти бо єси́ врач душ і тіле́с на́ших, і Тебі́ сла́ву і благодаре́ніє і поклоне́ніє возсила́єм, со Безнача́льним Твої́м Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомучениці Анастасії Узорозрішительці","e":"Prayer to the Great Martyr Anastasia the Deliverer from Bonds","secs":[{"h":"Тропар, глас 4","ps":["Побідоно́снаго Воскресе́нія / істинноімени́тая нарече́на єси́, му́ченице Христо́ва, / побі́ди на враги́ поста́вила єси́ мук терпі́нієм, / Христа́ ра́ди, Жениха́ твоєго́, / Єго́же возлюби́ла єси́. / Того́ моли́ // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Во іскуше́ніїх і ско́рбіх су́щії, / к твоєму́ хра́му притека́юще, / приє́млють честна́я дарова́нія / от живу́щия в тебі́ Боже́ственния благода́ті, Анастасі́є: // ти бо при́сно ми́ру то́чиши ісціле́нія."]},{"h":"Молитва","ps":["О многострада́льная і прему́драя великому́ченице Христо́ва Анастасі́є! Ти душе́ю на Небесі́ у Престо́ла Госпо́дня предстої́ши, на землі́ же, да́нною тебі́ благода́тію, разли́чная соверша́єши ісціле́нія. При́зри у́бо ми́лостивно на нас (імена), прося́щия твоє́й по́мощі: простри́ ко Го́споду святи́я моли́тви твоя́ о нас, і іспроси́ нам оставле́ніє согріше́ній на́ших, неду́жним ісціле́ніє, скорб'я́щим і бе́дствующим ско́рую по́мощ; умоли́ Го́спода, да пода́сть всім нам христия́нськую кончи́ну і до́брий отві́т на Стра́шнім суді́ Своє́м, да сподо́бимся і ми ку́пно с тобо́ю сла́вити Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Кирилу, ігумену Білозерському","e":"Prayer to St Cyril, Abbot of Beloozero","secs":[{"h":"Тропар, глас 1","ps":["Я́ко крин в пусти́ні дави́дськи процві́л єси́, о́тче Кири́лле, / злостра́стія те́рніє іскореня́я, / і собра́л єси́ в ней учени́к мно́жество, / стра́хом Бо́жиїм і уче́нієм твої́м наставля́ємих, / ї́хже і до конця́ я́ко чадолюби́вий оте́ць / не оста́вил єси́ посіща́я, да всі вопіє́м: / сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 8","ps":["Я́ко преоби́дів тлі́нная і до́лу влеку́щая мудрова́нія, о́тче, / к Ви́шнему тече́нію ра́достно устреми́лся єси́, / і та́мо со святи́ми Пресвяті́й Тро́йце предстоя́, / моли́ от враг сохрани́тися ста́ду твоєму́, / я́ко да, свято́є твоє́ успе́ніє пра́зднующе, вопіє́м: // ра́дуйся, преблаже́нне Кири́лле, о́тче наш."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне і Богоно́сне о́тче Кири́лле! Припа́даєм к тебі́ с ві́рою і любо́вію, і про́сим тя, Небе́снаго засту́пника на́шего: яви́ ве́ліє милосе́рдіє твоє́ нам, смире́нним і грі́шним, і проле́й те́плия моли́тви твоя́ о нас ко Го́споду Бо́гу. Сво́йственно єсть тебі́ благосе́рдіє, свя́тче Бо́жий, і́бо, живу́щу ті на землі́, єди́но бисть у тебе́ попече́ніє, є́же спаса́ти от поги́белі ду́ші челові́чеськія, і вся твоя́ жизнь свята́я зерца́ло до́брих діл яви́ся, о ни́хже прославля́шеся в тебі́ Оте́ць Небе́сний. К Тому́ ве́ліє дерзнове́ніє стяжа́в, іспроси́ нам у бла́гости Єго́ ві́ру пра́вую, благоче́стіє нелицемі́рноє, покая́ніє і́стинноє, братолю́біє соверше́нноє і преуспія́ніє во всіх благи́х ді́ліх. Ісхода́тайствуй нам здра́віє душе́вноє і тіле́сноє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, ми́рноє і безм'яте́жноє житіє́, непости́дную христия́нськую кончи́ну і до́брий отві́т на стра́шнім Суді́ Христо́ві. Сохрани́ Це́рков святу́ю і держа́ву Українськую от бра́ней і нестроє́ній. Огради́ оби́тель твою́ честну́ю от вся́каго зла, і вся правові́рния лю́ди, к тебі́ приходя́щия і моще́м твої́м покланя́ющіяся, осіни́ Небе́сним твої́м благослове́нієм, і вся проше́нія їх во бла́го іспо́лни. Єй, о́тче, не пре́зри моли́тв на́ших, со умиле́нієм тебі́ возноси́мих, но бу́ди о нас те́плий предста́тель ко Го́споду, і сподо́би нас по́мощію твоє́ю спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим ве́лія щедро́ти і неізрече́нния ми́лости Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, і твоє́ оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва священномученику Кипріану і мучениці Юстині","e":"Prayer to the Hieromartyr Cyprian and the Martyr Justina","secs":[{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д: / сего́ ра́ди, сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Киприя́не, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 1","ps":["От худо́жества волше́бнаго обрати́вся, Богому́дре, / к позна́нію Боже́ственному, / показа́лся єси́ ми́ру врач мудрі́йший, / ісціле́нія да́руя че́ствующим тя, Киприя́не со Іусти́ною: / с не́юже моли́ся Человіколю́бцю Влади́ці // спасти́ ду́ші на́ша."]},{"h":"Молитва перша","ps":["О святи́й уго́дниче Бо́жий, священному́чениче Киприя́не, ско́рий помо́щниче і моли́твенниче о всіх к тебі́ прибіга́ющих. Прийми́ от нас недосто́йних хвале́ніє на́ше і іспроси́ нам у Го́спода Бо́га в не́мощіх укріпле́ніє, в болі́зніх ісціле́ніє, в печа́ліх утіше́ніє і всім вся поле́зная в жи́зні на́шей. Вознеси́ ко Го́споду благомо́щную твою́ моли́тву, да огради́ть нас от паде́ній на́ших гріхо́вних, да научи́ть нас і́стинному покая́нію, да ізба́вить нас от пліне́нія дия́волськаго і вся́каго ді́йствія духо́в нечи́стих, і ізба́вить от оби́дящих нас. Бу́ди нам крі́пкий побо́рник на вся враги́ ви́димия і неви́димия, во іскуше́нії пода́ждь нам терпі́ніє і в час кончи́ни на́шей яви́ нам заступле́ніє от істяза́телей на возду́шних мита́рствах на́ших, да води́мії тобо́ю, дости́гнем Го́рняго Ієрусали́ма і сподо́бимся в Небе́сном Ца́рствії со всі́ми святи́ми сла́вити і воспіва́ти Всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святі́ї священному́чениче Киприя́не і му́ченице Іусти́на! Внемлі́те смире́нному моле́нію на́шему. А́ще бо вре́менноє житіє́ ва́ше му́ченичеськи за Христа́ сконча́ли єсте́, но ду́хом от нас не отступа́єте єсте́, при́сно по за́повідем Госпо́днім ше́ствовати нас науча́юще і крест свой терпіли́во нести́ нам посо́бствующе. Се, дерзнове́ніє ко Христу́ Бо́гу і Пречи́стій Єго́ Ма́тері стяжа́ли єсте́. Ті́мже і ни́ні бу́діте моли́твенниці і хода́таї о нас, недосто́йних (імена). Бу́діте нам засту́пниці кре́пції, да заступле́нієм ва́шим сохраня́ємі невреди́ми от бісо́в, волхво́в і от челові́к злих пребу́дем, сла́в'яще Святу́ю Тро́йцю: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Мойсею Угрину, Печерському","e":"Prayer to St Moses the Hungarian of the Caves","secs":[{"h":"Тропар, глас 3","ps":["Друга́го тя Іо́сифа, / вели́кий чистоти́ і цілому́дрія рачи́телю, / всече́стне і равноа́нгельне Мойсе́є, / свяще́нними пі́сньми восхваля́юще, грі́шнії, / мо́лимтися прилі́жно: / моли́ Христа́ Бо́га, / я́ко да ісціли́ть вся на́ша стра́сті // і пода́сть ве́лію ми́лость."]},{"h":"Інший тропар, глас 3","ps":["Труди́ і по́двиги со страстьми́ по чистоті́ твоє́й ви́дя, свя́те, / кто не удиви́ться? / Глад бо, темни́цю і ра́ни приє́мля, / не порабо́тился єси́ сласте́м ля́ховиці, / но, я́ко цар, страстьми́ облада́яй, / ни́ні і тогда́ возпросла́вился єси́ от Всеви́дящаго челові́чеськая сердця́, / от Него́же во іскуше́ніїх всім посо́бствовати благода́ть приє́м, / посо́бствуй і нам, твою́ па́м'ять чту́щим, // Мойсе́є преподо́бне."]},{"h":"Кондак, глас 3","ps":["Во Ви́шніх єди́наго Бо́га іща́ / земна́я вся презрі́л єси́, / о тілесі́ своє́м неради́в, / на му́ки му́жеськи себі́ вдал єси́, / глад, жа́жду, у́зи, в темни́ці затворя́єм, до́блественно претерпі́л єси́, / біє́нія, кро́ве ізлія́ніє і удо́в отрі́заніє, / чи́стаго ра́ди ді́вства твоєго́, / му́жеськи поне́сл єси́. / І ни́ні с ді́вственними ли́ки предстоя́ Пресвяті́й Тро́йце, / от всіх іскуше́ній моли́ ізба́витися вопію́щим ті: // ра́дуйся, Мойсе́є, о́тче блаже́ннійший."]},{"h":"Молитва","ps":["О, пречу́дний і Богоно́сний о́тче Мойсе́є, ізря́дний уго́дниче Христо́в і вели́кий чудотво́рче, к тебі́ смире́нно припа́даєм і мо́лимся: даждь нам би́ти прича́стником любве́ твоєя́ ко Бо́гу і бли́жнему, помози́ нам твори́ти во́лю Госпо́дню в простоті́ се́рдця і смире́нії, за́повіді Госпо́дні соверша́ти непогріши́тельно, при́зри благоутро́бно на вся́кую ду́шу ві́рних твої́х чти́телей, ми́лості і по́мощі твоєя́ і́щущих. Єй, всеблаги́й уго́дниче Бо́жий, усли́ши нас, моля́щихся тебі́, і не пре́зри нас, тре́бующих твоєго́ заступле́нія і досто́йную піснь тебі́ принося́щих, тебі́ ублажа́єм, о́тче Мойсе́є, тя воспіва́єм, чистоти́ світи́льниче, прославля́юще ми́лостиваго Бо́га, во Святі́й Безнача́льній Тро́йці сла́вимаго Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іоанну Милостивому, Патріарху Александрійському","e":"Prayer to St John the Merciful, Patriarch of Alexandria","secs":[{"h":"Тропар, глас 8","ps":["В терпі́нії твоє́м стяжа́л єси́ мзду твою́, о́тче преподо́бне, / в моли́твах непреста́нно терпі́вий, / ни́щія возлюби́вий і сія́ удовли́вий, / но моли́ся Христу́ Бо́гу, Іоа́нне ми́лостиве, блаже́нне, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Бога́тство твоє́ расточи́л єси́ убо́гим, / і Небе́сноє бога́тство ни́ні восприя́л єси́, / Іоа́нне всему́дре: / сего́ ра́ди всі тя почита́єм, / соверша́юще па́м'ять твою́, // ми́лостині о тезоімені́те!"]},{"h":"Молитва","ps":["Святи́телю Бо́жий Іоа́нне, ми́лостивий защи́тниче си́рих і су́щих в напа́стіх! К тебі́ прибіга́єм і тебі́ мо́лимся, я́ко ско́рому покрови́телю всіх і́щущих от Бо́га утіше́нія в біда́х і ско́рбіх. Не преста́й, моля́ся ко Го́споду о всіх с ві́рою притека́ющих к тебі́! Ти, преіспо́лнен сий Христо́ви любві́ і бла́гости, яви́лся єси́ я́ко чу́дний черто́г доброді́телі милосе́рдія і стяжа́л єси́ себе́ і́м'я \"ми́лостивий\". Ти бил єси́ я́ко ріка́, непреста́нно теку́щая ще́дрими ми́лостьми і всіх жа́ждущих оби́льно напая́ющая. Ві́руєм, я́ко по переселенії от землі́ на не́бо, усугу́бися в тебі́ дар благода́ті сея́ і я́ко соді́лался єси́ неісчерпа́ємий сосу́д вся́кия благости́ні. Сотвори́ у́бо твої́м хода́тайством і заступле́нієм пред Бо́гом “вся́кия уті́хи”, да всі, прибіга́ющії к тебі́, обріта́ють мир і безм'яте́жіє: да́руй їм утіше́ніє в печа́ліх вре́менних і посо́біє в ну́ждах жите́йських, всели́ в них наде́жду ві́чнаго упокоє́нія во Ца́рствії Небе́снім. В житії́ твоє́м на землі́ ти бил єси́ приста́нище всім су́щим во вся́кой біді́ і ну́жді, оби́димим і недугующим, і ні єди́н от притека́вших к тебі́ і проси́вших у тебе́ ми́лости лише́н бисть твоєя́ благости́ні. То́жде і ни́ні, ца́рствуя со Христо́м на Небесі́, яви́ всім покланяющимся пред честно́ю твоє́ю іко́ною і молящимся о по́мощі і заступле́нії. Не то́чію сам ти твори́л єси́ ми́лость безпомо́щним, но і се́рдця други́х воздвига́л єси́ ко утіше́нію немощни́х і ко призрі́нію убо́гих. Подви́гни у́бо і ни́ні се́рдця ві́рних к заступле́нію си́рих, ко утіше́нію скорб'я́щих і успокоє́нію неіму́щих. Да не оскудіва́ють в них да́ри ми́лости, па́че же да всели́ться в них і в до́му сем, призріва́ющем стра́ждущих, мир і ра́дость о Ду́хі Свя́те, во сла́ву Го́спода і Спа́са на́шего Ісу́са Христа́, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва священномученику Власію, єпископу Севастійському","e":"Prayer to the Hieromartyr Blaise, Bishop of Sebaste","secs":[{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д, / сего́ ра́ди, сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Вла́сіє. / Моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Боже́ственноє прозябе́ніє, цвіт неув'яда́ємий, / лози́ Христо́ви розго́ многострада́льная, Богоно́се Вла́сіє, / ві́рою чту́щия па́м'ять твою́ весе́лія твоєго́ іспо́лни, // моля́ся непреста́нно о всіх нас."]},{"h":"Інший кондак, глас 8","ps":["Свяще́нія пома́занієм і муче́нія кро́вію украси́лся єси́, сла́вне Вла́сіє, / і сія́єши всю́ду, во Ви́шніх лику́я / і нас назира́я, в храм твой прише́дшия / і в нем тебі́ непреста́нно зову́щия: // всіх нас соблюди́."]},{"h":"Молитва перша","ps":["Преблаже́нне і приснопа́м'ятне священному́чениче Вла́сіє, ди́вний страда́льче і предста́телю наш те́плий, по отше́ствії твоє́м в жизнь ві́чную призива́ющим твоє́ свято́є і́м'я посо́бствовати, і во вся́ких проше́ніїх усли́шанним би́ти обіща́вий! Се ни́ні к тебі́ уго́днику Бо́жию, я́ко ко і́стинному хода́таю спасе́нія, притека́єм і смире́нно мо́лимся: предста́ни нам в по́мощ, у́зами гріхо́в свя́занних, подви́гнися на всемо́щниі твоя́ к Бо́гу моли́тви і помоли́ся о нас грі́шних: тя бо недосто́йнії, призива́ти на заступле́ніє дерза́єм, і жела́єм от всіх гріхо́в на́ших тобо́ю свобожде́ніє получи́ти. О свя́тче Бо́жий Вла́сіє! В сокруше́нії і смире́нії се́рдця на́шего пред тобо́ю припа́даєм і мо́лимся: осія́й нас, омраче́нних наві́ти вра́жіїми, сві́том благода́ті сви́ше, да в нем ходя́ще, не преткне́м о ка́мень ног на́ших. Тя, я́ко сосу́д в честь ізбра́нний і іспо́лненний благода́ті Бо́жия, мо́лим: сподо́би нас грі́шних от ісполне́нія твоєго́ жела́ємоє прия́ти, і ісціли́ на́ша душе́вния і тіле́сния я́зви, гріхо́м же на́шим проще́ніє і душе́вному і тіле́сному на́шему здра́вію і спасе́нію поле́зноє у Го́спода іспроси́, да всегда́ прославля́єм Отця́ і Си́на і Свята́го Ду́ха, і твоє́ ми́лостивоє предста́тельство о душа́х і тілесі́х на́ших, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий і сла́вний страстоте́рпче, помо́щниче наш і те́плий засту́пниче всім с ві́рою притека́ющим к тебі́, святи́й священному́чениче Вла́сіє! При́зри от го́рнія сла́ви ми́лостивим о́ком твої́м на предстоя́щия лю́ди і уми́льно тебі́ моля́щіяся, простри́ те́плия моли́тви твоя́ ко Го́споду Бо́гу на́шему, іспроси́ у Него́ проще́нія согріше́ній на́ших, но є́же ізба́витися нам от всегуби́тельной я́зви, тру́са, пото́па, огня́, меча́ і ві́чния ка́зні, ісхода́тайствуй пред Престо́лом Го́спода Вседержи́теля немощни́м тілесе́м на́шим оставле́нія согріше́ній, всім же чту́щим честну́ю па́м'ять твою́, укрепле́нія на діла́ блага́я, не пре́зри нас недосто́йних, моля́щихся тебі́ пред честно́ю іко́ною твоє́ю і прося́щих твоєя́ по́мощі і заступле́нія, іспроси́ нам вся я́же ко спасе́нію на́шему поле́зная, да богоуго́дная Влади́ці на́шему Ісу́су Христу́ зді творя́ще, сподо́бимся моли́твами твої́ми наслі́довати Ца́рствіє Небе́сноє, іді́же вку́пі с тобо́ю просла́вим Єди́наго в Тро́йці сла́вимаго Бо́га Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученику Авраамію Болгарському, Володимирському чудотворцю","e":"Prayer to the Martyr Abraham of Bulgaria, Wonderworker of Vladimir","secs":[{"h":"Тропар, глас 4","ps":["Днесь, благові́рнії лю́діє, соше́дшеся, / восхва́лим до́бляго сего́ му́ченика і страда́льця Авраа́мія, / сей бо, укріпля́єм си́лою Бо́жиєю, / ду́шу свою́ положи́ за Христа́, / мно́го пострада́в от злові́рних болга́р. / Сего́ ра́ди от Го́спода віне́ць прия́т / і ни́ні предстої́ть Єму́ / і мо́литься о гра́ді сем // і о всіх нас, чту́щих па́м'ять єго́."]},{"h":"Кондак, глас 8","ps":["Я́ко многоці́нноє сокро́вище, / принесе́но бисть от Болга́рськия страни́ во град Влади́мир / пречестно́є ті́ло твоє́, му́чениче Авраа́міє, / і́мже подає́ши всім чту́щим пресла́вную па́м'ять твою́ оби́ліє ісціле́ній, / предстоя́ на Небесі́ Христу́ Бо́гу // і моля́ Єго́ о спасе́нії душ на́ших."]},{"h":"Інший кондак, глас 3","ps":["Укріпи́вся, сла́вне, любо́вію Госпо́днею / і Того́ честни́й Крест на ра́мо взем, і́го Госпо́днє, / посрами́л єси́ дия́воля кова́рствія / і пострада́л єси́ да́же до сме́рти, / і сего́ ра́ди, досточу́дне, яви́ся страда́лець вели́к, Авраа́міє, / і ору́жником храбротаї́нник // і уча́стник Бо́жия благода́ті."]},{"h":"Молитва","ps":["Святи́й му́чениче Авраа́міє, до́блій во́їне Христа́ Царя́ Небе́снаго, в ско́рбіх і напа́стіх пресла́вний наш помо́щниче і защи́тниче! Нічто́ же возмо́же отлучи́ти тя от любве́ ко Го́споду Ісу́су, ні ле́стния обіща́нія благ вре́менних, ні преще́нія, ні му́ки от злих враго́в святі́йшия Христо́ви ві́ри; ти, я́ко лев, ізше́л єси́ на брань проти́ву волко́в ми́сленних, духо́в зло́би, подви́гших на тя, ра́ди до́браго твоєго́ іспові́данія, єдиноплеме́нний тебі́ наро́д болга́рський, і, я́ко о́гненная стріла́, тіх порази́л єси́ си́лою благода́ті Свята́го Ду́ха, і крі́пкия, я́ко смерть, любве́ твоєя́ к Бо́гу. А́ще і пролія́л єси́ кров твою́ за Христа́ Бо́га на́шего, погуби́во вре́менную жизнь, оба́че безсме́ртною душе́ю, я́ко оре́л, воспари́л єси́ в го́рнія оби́телі Отця́ на́шего, наслі́довав там ві́чную жизнь, сла́ву і блаже́нство неізрече́нноє, і оста́вив нам нетлі́нния оста́нки твоя́, я́ко крин многоці́нний і благоуха́нний. Ві́руєм, страстоте́рпче святи́й, я́ко предстоя́ со а́нгели і всі́ми святи́ми Престо́лу сла́ви Триіпоста́снаго Бо́га, усе́рдния і богоприя́тния возно́сиши моли́тви не то́кмо о нас і о гра́ді на́шем, но і о всей святі́й Христо́вой Це́ркві і о правосла́внім оте́честві Українськім. Ві́руєм, пресла́вний чудотво́рче, я́ко ти, си́лою всемогу́щаго Го́спода Ісу́са Христа́, чрез святи́я мо́щі твоя́, істоча́єши оби́льния да́ри благода́тния по́мощі во спасе́ніє всім с ві́рою к тебі́ притека́ющим, найпа́че же іспра́шиваєши і кончи́ну с покая́нієм тебі́ чту́щим, і благосе́рдно помога́єши немощни́м младе́нцем, да всі от ма́ла до вели́ка єдиноду́шно прославля́єм неісповіди́моє вели́чіє бла́гости Бо́жієй. Тім же ві́рою і любо́вію ко святи́м моще́м твої́м припа́дающе і благогові́йно о́ния лобиза́юще, умоля́єм тя, до́брий на Небесі́ наш моли́твенниче і засту́пниче, помога́й нам грі́шним і смире́нним, твої́ми моли́твами во всіх ско́рбіх, ну́ждах і обстоя́ніїх на́ших, сохраня́й нас і град сей от вся́каго зла і вся́кия напа́сти, найпа́че же споспі́шествуй ві́чному спасе́нію на́шему і всіх прося́щих от тебе́ по́мощі і заступле́нія. Єй, смире́нно мо́лим тя, уго́дниче Бо́жий, моли́ Христа́ Бо́га на́шего, да дасть Он мир і тишину́ всім правосла́вним христия́ном і да отврати́ть от нас вся́кий гнів, на ни дви́жимий, да ізба́вить нас от сіте́й вра́жиїх, томле́нія во у́зах гріха́ і муче́ній а́дських, і да сподо́бит нас недосто́йних одесну́ю Себе́ ста́ти на суді́ Своє́м пра́ведном і вни́ти во ві́чний поко́й святи́х Єго́, іді́же пра́зднующих глас непреста́нний і неізрече́нная сла́дость зря́щих добро́ту лиця́ Єго́; і та́ко возмо́жем с тобо́ю і всі́ми святи́ми безконе́чно прославля́ти Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную. Амі́нь."]}],"notes":[]},{"u":"Молитва мученикам Косьмі й Даміану, безсрібникам і чудотворцям Римським","e":"Prayer to the Martyrs Cosmas and Damian, Unmercenary Healers and Wonderworkers of Rome","secs":[{"h":"Тропар, глас 8","ps":["Святі́ї безсре́бреници і чудотво́рці Косьмо́ і Дамія́не, / посіті́те не́мощі на́ша: // ту́не прия́сте, ту́не даді́те нам."]},{"h":"Кондак, глас 2","ps":["Благода́ть приі́мше ісціле́ній, / простира́єте здра́віє су́щим в ну́ждах, вра́чеве, / чудотво́рці пресла́внії, / но ва́шим посіще́нієм ра́тников де́рзости низложі́те, // мир ісціля́юще чудеси́."]},{"h":"Молитва","ps":["К вам, святі́ї безсре́бреници і чудотво́рці Космо́ і Дамія́не, я́ко к ско́рим помо́щником і те́плим моли́твенником о спасе́нії на́шем, ми, недосто́йнії, прекло́ньше колі́на, прибіга́єм і, припа́дающе, усе́рдно вопіє́м: не пре́зріте моле́нія нас, грі́шних, немощни́х, во мно́гая беззако́нія впа́дших і по вся дні і часи́ согріша́ющих. Умолі́те Го́спода, да проба́вить нам, недосто́йним рабо́м Свої́м, вели́кия і бога́тия Своя́ ми́лости; ізба́віте нас от вся́кия ско́рби і болі́зні, ви бо прия́ли єсте́ от Го́спода і Спа́са на́шего Ісу́са Христа́ неоску́дную благода́ть ісціле́ній, ра́ди тве́рдия ві́ри, безме́зднаго врачева́нія і му́ченичеськия кончи́ни ва́шея. Усли́шіте нас, моля́щихся, і благоприя́тним хода́тайством ва́шим іспросі́те у Христа́ Бо́га правосла́вним лю́дем на враги́ побі́ду і одолі́ніє. Па́ки, припа́дающе, прилі́жно мо́лим: іспросі́те нам от Го́спода вся благополе́зная, я́же в животі́ на́шем вре́меннім, найпа́че же ко спасе́нію ві́чному служа́щая, да сподо́бимся моли́твами ва́шими улучи́ти кончи́ну христия́нськую, безболі́зненну, непости́дну, ми́рну, і да ізба́вимся от ко́зней дия́вольських і ві́чния му́ки, безконе́чнаго же і блаже́ннаго Ца́рствія Небе́снаго наслі́дници бу́дем. Єй, уго́дниці Бо́жії, не преста́йте моля́щеся за ни, с ві́рою к вам притека́ющия. А́ще бо по мно́жеству гріхо́в на́ших і ні́сми досто́йни милосе́рдія ва́шего, оба́че ви, ві́рнії подража́теліє человіколю́бія Бо́жия су́ще, сотворі́те, да принесе́м плоди́ досто́йни покая́нія і во ві́чний поко́й дости́гнем, хва́ляще і благослов'я́ще ди́внаго во святи́х Свої́х Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́, і Пречи́стую Ма́тер Єго́, і ва́ше те́плоє заступле́ніє, всегда́, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому великомученику Никиті","e":"Prayer to the Holy Great Martyr Nicetas","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Ники́та / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Крест Христо́в, я́ко ні́коє ору́жіє усе́рдно восприї́м, / і к боре́нію враго́в прите́кл єси́, / і за Христа́ пострада́в, / посліди́ огне́м свяще́нную твою́ ду́шу Го́споду пре́дал єси́: / отону́дуже і даро́в ісціле́нія / от Него́ сподо́бился єси́ прия́ти, / великому́чениче Ники́то. / Моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Пре́лести посі́к держа́ву стоя́нієм твої́м, / і побі́ди приї́м віне́ць во страда́льчествіх твої́х, / со А́нгели сла́вне ра́дуєшися, / Ники́то тезоімені́те, // с ни́ми Христа́ Бо́га моля́ непреста́нно о всіх нас."]},{"h":"Молитва перша","ps":["О вели́кий страстоте́рпче Христо́в і чудотво́рче великому́чениче Ники́то! Припа́дающе к свято́му і чудотво́рному о́бразу твоєму́, по́двиги же і чудеса́ твоя́ і мно́гоє сострада́ніє твоє́ к лю́дем прославля́юще, мо́лим тя прилі́жно: яви́ нам смире́нним і грі́шним свято́є і многомо́щноє твоє́ заступле́ніє, се бо гріх ра́ди на́ших не і́мами свобо́ди чад Бо́жиїх, є́же о потре́бах на́ших Го́спода і Влади́ку на́шего дерзнове́нно проси́ти, но тебі́ моли́твенника к Нему́ благоприя́тнаго предлага́єм і о твоє́м предста́тельстві взива́єм, іспроси́ нам у Го́спода благопотре́бния да́ри душа́м і тілесе́м на́шим, ві́ру пра́вую, спасе́нія наде́жду несомні́нную, любо́в же ко всім нелицемі́рную, во іскуше́ніїх му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, душ і тіле́с здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, жите́йських потре́б дово́льство, ми́рноє і благоче́стноє на землі́ житіє́, христия́нськую житія́ кончи́ну і до́брий отві́т на стра́шнім суди́щі Христо́вом. Єще́ же, о страстоте́рпче Христо́в, у Царя́ Небе́снаго іспроси́ страні́ на́шей Українській мир, здра́віє і спасе́ніє, і на враги́ побі́ду і одолі́ніє, благоустроє́ніє, тишину́ і благоде́нствіє. Христолюби́вому во́їнству бу́ди сора́тай і помо́щник на враги́ і всім лю́дем правосла́вним яви́ твоє́ свято́є заступле́ніє: боля́щия ісціли́, скорб'я́щия уті́ши, бе́дствующим помози́. Єй, уго́дниче Бо́жий і му́чениче долготерпіли́вий! Не забу́ди святу́ю оби́тель твою́ і вся живу́щия в ней і подвиза́ющіяся і́нокини же і мирськи́я, но поспі́ши їм в смире́нії і терпі́нії носи́ти і́го Христо́во і от вся́ких бід і іскуше́ній ми́лостивне ізба́ви. Всіх у́бо нас приведи́ в ти́хоє приста́нище спасе́нія і наслі́дники сподо́би би́ти пресві́тлаго Ца́рствія Христо́ва святи́ми твої́ми моли́твами, да сла́вим і поє́м вели́кия щедро́ти Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, і твоє́ свято́є заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий Христо́в страстоте́рпче Ники́то! Усли́ши моли́тву нас, грі́шних, і ізба́ви нас (імена) от вся́кия печа́лі і находя́щия напа́сти, от внеза́пния сме́рти і от вся́каго зла: в час же разлуче́нія душі́ от ті́ла отжени́, страстоте́рпче, вся́кую лука́вую мисль і лука́вия бі́си, я́ко да при́йметь ду́ші на́ша с ми́ром в мі́сто сві́тло Христо́с Госпо́дь Бог наш, я́ко от Него́ очище́ніє гріхо́в, і Той єсть спасе́ніє душ на́ших, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мучениці Людмилі, княгині Чеській","e":"Prayer to the Martyr Ludmila, Princess of Bohemia","secs":[{"h":"Тропар, глас 4","ps":["Оста́вльша тьму ідолослуже́нія / і с горя́чей любо́вію прия́в світ Правосла́вния ві́ри Христо́ви, / яви́ся ти, свята́я Людми́ло, я́ко звізда́ у́тренняя, / і сві́том свя́тости твоєя́ // і́стинний день Богопочита́нія в Че́стей землі́ нача́в."]},{"h":"Кондак, глас 2","ps":["Храм Твой всечестни́й, / я́ко цільбу́ душе́вную обрі́тше всі ві́рнії, / велегла́сно вопіє́м ті, / ді́во му́ченице Людми́ло, великоімени́тая: // Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, свята́я уго́днице Христо́ва, му́ченице княги́не Людмило, первоуго́днице Чешськия страни́ і сто́льнаго гра́да Пра́ги украше́ніє, те́плая о нас пред Бо́гом моли́твеннице! Се ми, многогрі́шнії, смире́нно припа́дающе, мо́лим тя: не попусти́ нам поги́бнути в ти́ні гріхо́в на́ших, но вознеси́ о нас моле́ніє ко Го́споду, да поми́луєть нас і да́руєть нам покая́ніє. О, преблага́я ма́ти Людмило! Не забу́ди посіща́ти чад твої́х, а́ще бо і преста́вилася єси́ от нас в Небе́сния оби́телі, вку́пі со внуко́м твої́м, святи́м му́чеником В'ячеславом. Ті́мже, свята́я прама́ти єго́, іспроси́ і нам, грі́шним, Бо́жиє благослове́ніє на ча́да на́ша і на всіх нас, да і ми, многогрі́шнії, возблагодари́м Го́спода за подая́ніє Єго́ благода́ті і ку́пно с тобо́ю да просла́вим Отця́ і Си́на і Свята́го Ду́ха і твоє́ вели́коє заступле́ніє о нас во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобним Кирилу і Марії, батькам преподобного Сергія Радонезького","e":"Prayer to Sts Cyril and Maria, parents of St Sergius of Radonezh","secs":[{"h":"Тропар, глас 3","ps":["Блаже́нств Христо́вих прича́стници, / честна́го супру́жества і попече́нія о ча́діх до́брий о́бразе, / пра́веднії Кири́лле і Марі́є, / плод благоче́стія, Се́ргия преподо́бнаго, нам яви́вшії, / с ни́мже усе́рдно молі́те Го́спода / низпосла́ти нам дух любве́ і смиренному́дрія, / да в ми́рі і єдиноми́слії // просла́вим Тро́йцю Єдиносу́щную."]},{"h":"Кондак, глас 4","ps":["Днесь, ві́рнії, соше́дшеся, / восхва́лим дво́їцю блаже́нную, благові́рнаго Кири́лла і Марі́ю добронра́вную, / ті́ї бо мо́ляться вку́пі со возлю́бленним си́ном свої́м преподо́бним Се́ргиєм / ко Єди́ному во Святі́й Тро́йці Бо́гу / оте́чество на́ше в правові́рії утверди́ти, / до́ми ми́ром огради́ти, / ю́ния от напа́стей і собла́знов ізба́вити, / ста́рость укріпи́ти // і спасти́ ду́ші на́ша."]},{"h":"Молитва","ps":["О раби́ Бо́жії, преподо́бнії Кири́лле і Марі́є! А́ще і сконча́ли єсте́ вре́менную жизнь свою́ ті́лом, но ду́хом не отступа́єте от нас, руково́дствуєте же ни ко Христу́ Бо́гу, наставля́єте ше́ствовати по за́повідем Госпо́днім і носи́ти крест свой і послі́довати Влади́ці на́шему. Ви, преподо́бнії, вку́пі с преподо́бним і Богоно́сним отце́м на́шим Се́ргиєм, ва́шим возлю́бленним си́ном, іме́єте дерзнове́ніє ко Христу́ Бо́гу на́шему і ко Святі́й Єго́ Богома́тері. Бу́діте моли́твенниці і хода́таї о нас, недосто́йних, жи́тельствующих во святі́й оби́телі ва́шей, єй же ви і нача́льниці. Бу́діте помо́щници і засту́пниці Бо́гом собра́нній дружи́ні сей, да жи́тельствующії на мі́сті сем і приходя́щії с ві́рою, ва́шими моли́твами сохраня́ємі, невреди́ми от бісо́в і от челові́к злих пребу́дем, сла́в'яще Святу́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святій рівноапостольній княгині Ользі, у святому хрещенні Олені","e":"Prayer to the Holy Equal-to-the-Apostles Princess Olga, in Holy Baptism Helena","secs":[{"h":"Тропар, глас 1","ps":["Крила́ми богоразу́мія впери́вши твой ум, / возлеті́ла єси́ преви́ше ви́димая тва́рі, / взиска́вши Бо́га і Творця́ вся́чеських, / і, Того́ обрі́тши, па́ки рожде́ніє Креще́нієм прия́ла єси́, / дре́ва живо́тнаго наслажда́ющися, нетлі́нна во ві́ки пребива́єши, // О́льго присносла́вная."]},{"h":"Кондак, глас 4","ps":["Воспоє́м днесь Благоді́теля всіх Бо́га, / просла́вльшаго в Україні О́льгу Богому́друю: / да моли́твами єя́ / пода́сть душа́м на́шим // гріхо́в оставле́ніє."]},{"h":"Молитва перша","ps":["О свята́я равноапо́стольная вели́кая княги́не О́льго, первоуго́днице Українськая, те́плая о нас пред Бо́гом хода́тайце і моли́твеннице! К тебі́ прибіга́єм с ві́рою і мо́лимся с любо́вію: бу́ди нам во всем ко бла́гу помо́щниця і споспі́шниця і, я́коже во вре́менній жи́зні тща́лася єси́ просвіти́ти пра́отці на́ша сві́том святи́я ві́ри і наста́вити я твори́ти во́лю Госпо́дню, та́ко і ни́ні, в Небе́сній пребива́єши сві́тлости, благоприя́тними твої́ми к Бо́гу моли́твами вспомоществу́й нам в просвіще́ніі ума́ і се́рдця на́шего сві́том Єва́нгелія Христо́ва, да преспіва́єм во ві́рі, благоче́стії і любві́ Христо́ві. В нищеті́ і ско́рби су́щия уті́ши, бе́дствующим пода́ждь ру́ку по́мощі, оби́димия і напа́ствуємия заступи́, заблу́дшия от пра́вия ві́ри і єресьми́ осліпле́нния вразуми́ і іспроси́ нам у Всеще́драго Бо́га вся блага́я і поле́зная жи́зні вре́менній і ві́чній, да та́ко благоуго́дні зді пожи́вше, сподо́бимся наслі́дія благ ві́чних в безконе́чном Ца́рствії Христа́ Бо́га на́шего, Єму́же со Отце́м і Святи́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кая уго́дниця Бо́жия, богоізбра́нная і богопросла́вленная, равноапо́стольная вели́кая княги́не О́льго! Ти отри́нула єси́ злові́ріє і нече́стіє язи́чеськоє, уві́ровала єси́ во Єди́ного І́стиннаго Тріїпоста́сного Бо́га, і восприя́ла єси́ свято́є Креще́ніє, і положи́ла єси́ нача́ло просвіще́нію землі́ Українськия сві́том ві́ри і благоче́стія. Ти єси́ духо́вная родонача́льниця на́ша, ти по Христе́ Спаси́телі на́шем пе́рвая вино́вниця просвіще́нія і спасе́нія ро́да на́шего. Ти єси́ те́плая моли́твенниця і хода́тайця о оте́честві Всеукраїнськім, во́їнстві і всіх лю́діх. Сего́ ра́ди смире́нно мо́лим тя: при́зри на не́мощі на́ша і умоли́ Премилосе́рдаго Царя́ Небе́снаго, да не прогні́вається на ни зіло́, я́ко по не́мощем на́шим по вся дні согріша́єм, да не погуби́ть нас со беззако́ньми на́шими, но да поми́луєть і спасе́ть нас по ми́лості Своє́й, да всади́ть в сердця́ на́ша спаси́тельний страх Свой, да просвіти́ть Своє́ю благода́тію ум наш, во є́же разумі́ти нам путі́ Госпо́дні, оста́вити стезі́ нече́стія і заблужде́ній, тща́тися же во стезя́х спасе́нія і і́стини, неукло́ннаго ісполне́нія за́повідей Бо́жиїх і уста́вов Святи́я Це́ркве. Моли́, блаже́нная О́льго, Человіколю́бця Бо́га, да проба́вить нам вели́кую ми́лость Свою́, да ізба́вить нас от наше́ствія іноплеме́нних, от вну́тренних нестроє́ній, м'яте́жей і раздо́ров, от гла́да, смертоно́сних болі́зней і от вся́каго зла, да пода́сть нам благорастворе́ніє возду́ха і плодоно́сіє землі́, да сохрани́ть страну́ на́шу от всіх ко́зней і наві́т вра́жиїх, да соблюде́ть в судія́х і прави́теліх пра́вду і ми́лость, да дасть па́стирем ре́вность о спасе́нії пасо́мих, всім же лю́дем споспіше́ніє, о є́же усе́рдно слу́жби своя́ ісправля́ти, любо́в ме́жду собо́ю і єдиноми́сліє імі́ти, да на бла́го оте́чества і Святи́я Це́ркве ві́рне подвиза́тися, да воссія́єть світ спаси́тельния ві́ри в страні́ на́шей во всіх конці́х єя́, да обратя́ться к ві́рі неві́рующіі, да упраздня́ться вся є́ресі і раско́ли. Да, та́ко пожи́вши в ми́рі на землі́, сподо́бимся с тобо́ю ві́чнаго блаже́нства на Небесі́, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я равноапо́стольная княги́не О́льго, / я́ко зарю́ у́треннюю в землі́ на́шей возсія́вшую / і світ ві́ри Правосла́вния // наро́ду своєму́ предвозвести́вшую."]}],"notes":[]},{"u":"Молитва священномученику Харалампію","e":"Prayer to the Hieromartyr Haralambos","secs":[{"h":"Тропар, глас 4","ps":["Я́ко столп ізбра́нний Це́ркве Христо́вой / і світи́льник присносве́тлий всея́ вселе́нния, / прему́дре показа́ся, Харала́мпіє, / возсія́ в ми́рі муче́нієм, / разруши́ і́дольськоє мракобе́сіє, блаже́нне, / сего́ ра́ди яви́ся предста́тель Христу́, // моли́ся спасти́ся нам."]},{"h":"Кондак, глас 8","ps":["Подо́бствовав благода́тію свяще́нства, сла́вне, / Це́рков сві́тло укра́сил єси́ Боже́ственним страда́нієм, / є́же за Христа́ прия́л єси́ до́блественно, ра́дуяся, Харала́мпіє, / честни́й світи́льниче всеми́рний, осіява́яй конці́, // я́ко непобіди́мий."]},{"h":"Молитва перша","ps":["О свяще́ннійшая главо́, па́стирю до́брий слове́сних ове́ць Христо́вих, священному́ченниче Христо́в Харала́мпіє, вели́кий о нас засту́пниче в ско́рбіх і біда́х і во всіх ну́ждах! Усли́ши нас, грі́шних і недосто́йних раб твої́х, моля́щихся тебі́, да твої́ми всеси́льними моли́твами Всеблаги́й Госпо́дь ізба́вить ни от вся́каго зла́го обстоя́нія, прости́ть вся согріше́нія, во́льная і нево́льная, сподо́бит ни про́чая лі́та жи́зні на́шея сконча́ти в соблюде́нії за́повідей Єго́ і покая́нії. Іспроси́, уго́дниче Бо́жий, да пребу́деть благослове́ніє Царя́ Небе́снаго над благослове́нною Їм Україною. Ти бо прия́л єси́ єще́ в житії́ своє́м от Го́спода си́лу всім притека́ющим к тебі́ с мольбо́ю подава́ти потре́бноє, ті́мже і ста́рці, і во́зрастнії, і ді́ти прийма́ху ісціле́нія ра́ди хода́тайства твоєго́, уго́дниче, пред Престо́лом Го́спода. Єгда́ на ме́чноє тя усіче́ніє осуди́ша, сли́шал єси́ превожделі́нний і сладча́йший глас Го́спода, глаго́лющ к тебі́ сицева́я: прийди́, Харала́мпіє, дру́же Мой, мно́гая му́ки ра́ди і́мене Моєго́ претерпі́вий, проси́ у Мене́, чесо́ хо́щеши, і дам ті. Ти же, вели́кий світи́льниче, рекл єси́ Єму́ усти́ свої́ми: Го́споди, а́ще уго́дно Тебе́ єсть, молю́ Тя, даждь сла́ву і́мені Твоєму́, іді́же положени́ бу́дуть моя́ мо́щі і па́м'ять моя́ і́мать почита́тися, да не бу́деть на мі́сті том глад і мор іли́ тлетво́рний возду́х, погубля́ющ плоди́, но да бу́деть па́че на мі́стіх тіх мир, тілесе́м здра́віє і душа́м спасе́ніє, ізоби́ліє же пшени́ци і вина́, і ското́в умноже́ніє на потре́бу челові́ком. І та́ко по проше́нію твоєму́ прия́л єси́ от Го́спода ве́лію благода́ть. На твоя́ моле́нія, на тя, священному́чениче Христо́в Харала́мпіє, упова́єм, получи́ти ве́лію ми́лость от Го́спода в безконе́чний вік. Амі́нь."]},{"h":"Молитва друга","ps":["О пречу́дний священному́чениче Харала́мпіє, страстоте́рпче непреодолі́нний, свяще́нниче Бо́жий, о всем ми́рі хода́тайствуяй! При́зри на моле́ніє нас почита́ющих святу́ю па́м'ять твою́. Іспроси́ нам у Го́спода Бо́га проще́ніє гріхо́в на́ших, да не до конця́ прогні́вається на нас Госпо́дь: согріши́хом бо і недосто́йни яви́хомся милосе́рдія Бо́жия. Моли́ о нас Го́спода Бо́га, да низпосле́ть мир на гра́ди і ве́сі на́ша, да ізба́вить нас от наше́ствія іноплеме́нников, междоусо́бния бра́ні і вся́ких раздо́ров і нестроє́ній! Утверди́, священному́чениче, ві́ру і благоче́стіє во всіх ча́дах правосла́вния христия́нськия це́ркві, і да ізба́вить нас Госпо́дь Бог от єресе́й, раско́лов і вся́каго суєві́рія. О милосе́рдний му́чениче! Моли́ся за ни ко Го́споду, да сохрани́ть нас от гла́да і вся́ких болі́зней, і да пода́сть нам ізоби́ліє плодо́в земни́х, ското́в умноже́ніє на потре́бу челові́ком і вся нам поле́зная: найпа́че же да сподо́бимся, моли́твами твої́ми, Небе́снаго Ца́рствія Христа́ Бо́га на́шего, Єму́же честь і поклоне́ніє подоба́єть, со безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому преподобному Роману Солодкоспівцю","e":"Prayer to St Romanos the Melodist","secs":[{"h":"Тропар, глас 8","ps":["В тебі́, о́тче, ізві́стно спасе́ся є́же по о́бразу: / приї́м бо крест, послі́довал єси́ Христу́ / і, ді́йствуя, учи́л єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́ ве́щі безсме́ртній. // Ті́мже і со А́нгели сра́дується, преподо́бне Рома́не, дух твой."]},{"h":"Інший тропар, глас 3","ps":["От ю́ности житію́ равноа́нгельному ревну́я, / ві́ру, смиренному́дріє і терпі́ніє стяжа́в, / преподо́бне Рома́не Сладкопе́вче, / оби́тель Свята́го Ду́ха бил єси́, / та́же ізбра́нник Бо́жия Ма́тере яви́лся єси́, / і от Нея́ ми́лостивно сподо́бися да́ра сла́вити Бо́га. / Сего́ ра́ди моли́ся о нас, недосто́йних учениці́х твої́х, // да воспоє́м с тобо́ю сладкогла́сно сла́ву нас ра́ди Воплоти́вшемуся Преві́чному Бо́гу."]},{"h":"Кондак, глас 8","ps":["Боже́ственними доброді́тельми ду́ха / ізмла́да украси́вся, Рома́не прему́дре, / Це́ркві Христо́ві пречестно́є украше́ніє бил єси́: / пі́нієм бо прекра́сним украси́в ю, блаже́нне. / Тім мо́лим тя: пода́ждь жела́ющим Боже́ственнаго дарова́нія твоєго́, / я́ко да вопіє́м ті: // ра́дуйся, о́тче преблаже́нне, красото́ церко́вная."]},{"h":"Молитва","ps":["О, преблаже́нне о́тче наш, Рома́не Сладкопе́вче! При́зри от го́рнія сла́ви на нас, смире́нних і немощни́х, твоєя́ по́мощі і утіше́нія прося́щих. Прини́кни к нам благосе́рдієм твої́м і помози́ за́повіді Госпо́дні непоро́чно сохраня́ти, ві́ру правосла́вную крі́пко содержа́ти, покая́ніє во грісі́х на́ших усе́рдно Бо́гу приноси́ти. Научи́ нас, уневі́стившихся Христу́, рабо́тати Єму́ со стра́хом і ра́доватися с тре́петом. Ізба́ви нас от печа́лі і уни́нія, отжени́ от нас го́рдость і славолю́біє, да воспоє́м сла́ву Бо́жию, да восхо́щем то́кмо сла́ви Небе́сния. О, святи́й о́тче, всели́ в нас любо́в нелицемі́рную к бли́жнім, послуша́ніє безро́потноє нача́льником і страх Бо́жий в сердця́ на́ша. Да́руй позна́ти сла́дость отрече́нія во́лі своєя́, ве́рой кре́пкой во благо́є Промишле́ніє Бо́жиє о спасе́нії челові́ка освяти́ ду́ші на́ша. Низпосли́ нам благослове́ніє от Го́спода, да понесе́м благо́є і́го Христо́во в долготерпі́нії до конця́ дній на́ших, да сподо́бимся с му́дрими ді́вами вни́ти во бра́чний черто́г Жениха́ своєго́ Небе́снаго і ку́пно со А́нгелами воспіва́ти сла́ву вели́чія Єго́, Отця́, і Си́на, і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Рома́не, і чтем святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Молитва преподобному Олексію, чоловіку Божому","e":"Prayer to St Alexis, the Man of God","secs":[{"h":"Тропар, глас 4","ps":["Возви́сився на доброді́тель і ум очи́стив, / к жела́нному і кра́йнему дости́гл єси́, / безстра́стієм же украси́в житіє́ твоє́ / і поще́ніє ізря́дноє восприї́м со́вістію чи́стою, / в моли́твах, я́ко безпло́тен, пребива́я, / возсія́л єси́, я́ко со́лнце, в ми́рі, // преблаже́нне Алексі́є."]},{"h":"Інший тропар, глас 4","ps":["Я́ко чистоти́ світи́льник пресві́тел показа́ся, / ди́вний Алексі́є, / і́бо тлі́нний черто́г / на нетлі́нноє Бо́жиє Ца́рствіє преміни́в, / я́ко цілому́дрія ді́латель преізря́ден. / Сего́ ра́ди предстої́ши Го́сподеві, всіх Царю́. // Єго́же моли́, дарова́ти нам мир і ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Дом роди́телей твої́х я́ко чужд імі́в, / водвори́лся єси́ в нем нищеобра́зно / і, по преставле́нії віне́ць приє́м сла́ви, / ди́вен на землі́ яви́лся єси́, Алексі́є, челові́че Бо́жий, // А́нгелом і челові́ком ра́дованіє."]},{"h":"Молитва перша","ps":["О вели́кий Христо́в уго́дниче, святи́й челові́че Бо́жий Алексі́є, душе́ю на Небесі́ Престо́лу Госпо́дню предстоя́й, на землі́ же да́нною ті сви́ше благода́тію разли́чная соверша́яй чудеса́! При́зри ми́лостивно на предстоя́щия святі́й іко́ні твоє́й лю́ди, умиле́нно моля́щієся і прося́щиє от тебе́ по́мощі і заступле́нія. Простри́ моли́твенно ко Го́споду Бо́гу честні́ї ру́ці твої́ і іспроси́ нам от Него́ оставле́ніє согріше́ній на́ших во́льних і нево́льних, в неду́зіх стра́ждущим ісціле́ніє, напа́ствуємим заступле́ніє, скорб'я́щим утіше́ніє, бе́дствующим ско́рую по́мощ, всім же чту́щим тя ми́рную і христия́нськую живота́ кончи́ну і до́брий отві́т на стра́шнім Суді́ Христо́ві. Єй, свя́тче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя по Бо́зі і Богоро́дице возлага́єм, но бу́ди нам помо́щник і покрови́тель во спасе́ніє, да твої́ми моли́твами получи́вше благода́ть і ми́лость от Го́спода, просла́вим человіколю́біє Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, і твоє́ свято́є заступле́ніє ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О Христо́в уго́дниче, святи́й челові́че Бо́жий Алексі́є! При́зри ми́лостивно на нас, раб Бо́жиїх (імена), і простри́ моли́твенно ко Го́споду Бо́гу честні́ї ру́ці твої́, і іспроси́ нам от Него́ оставле́ніє согріше́ній на́ших во́льних і нево́льних, ми́рную і христия́нськую житія́ кончи́ну і до́брий отві́т на Стра́шнім суді́ Христо́ві. Єй, уго́дниче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя, по Бо́зі і Богоро́дице, возлага́єм; но бу́ди нам помо́щник і покрови́тель во спасе́ніє; да твої́ми моли́твами получи́вше благода́ть і ми́лость от Го́спода, просла́вим человіколю́біє Отця́ і Си́на і Свята́го Ду́ха і твоє́ свято́є заступле́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва священномученику Антипі, єпископу Пергама Асійського","e":"Prayer to the Hieromartyr Antipas, Bishop of Pergamum in Asia","secs":[{"h":"Тропар, глас 4","ps":["І́дольськия ле́сти упраздни́л єси́, Анти́по, / і, дия́вольськую попра́в си́лу, / пред богобо́рці дерзнове́нно Христа́ іспові́дал єси́. / Ті́мже со А́нгельськими чи́ни во Ви́шніх водворя́яся, / Влади́ці всіх славосло́віє принося́, / і о нас моле́бноє благодаре́ніє предлага́єши, / благода́ть цільби́ да́руя. / Сего́ ра́ди тя чтим, / священному́чениче Анти́по, / моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Апо́столов сопресто́льник і святи́телей украше́ніє / бил єси́, блаже́нне, / му́ченичеськи просла́вився, / возсія́л єси́, я́коже со́лнце, всіх просвіща́я, / Анти́по свяще́нне, / разруши́л єси́ безбо́жия нощ глубо́кую. / Сего́ ра́ди тя почита́єм, / я́ко Боже́ственнаго су́ща священному́ченика // і ціле́б пода́теля."]},{"h":"Молитва перша","ps":["О пресла́вний священному́чениче Анти́по і ско́рий помо́щниче христия́ном в болі́зніх! Ві́рую от всея́ душі́ і помишле́нія, я́ко даде́ся тебі́ от Го́спода дар боля́щия ісціля́ти, неду́гующия врачева́ти і разсла́бленния укріпля́ти. Сего́ ра́ди к тебі́, я́ко благода́тному врачу́ болі́зней, аз, немощни́й, прибіга́ю і, твой досточти́мий о́браз с благогові́нієм лобиза́я, молю́ся: твої́м предста́тельством у Царя́ Небе́снаго іспроси́ мні, боля́щему, ісціле́ніє от удруча́ющия м'я зубни́я болі́зні, а́ще бо і недосто́їн єсьм тебі́, благостнійшаго отця́ і при́снаго засту́пника моєго́, но ти, бив подража́тель человіколю́бія Бо́жия, сотвори́ м'я досто́йна твоєго́ заступле́нія чрез моє́ обраще́ніє от злих діл к благо́му житію́, уврачу́й оби́льно дарова́нною тебі́ благода́тію я́зви і стру́пи душі́ і ті́ла моєго́, да́руй мі здра́віє і спасе́ніє і во всем благо́є поспіше́ніє, да, та́ко ти́хоє і безмо́лвноє житіє́ пожи́во во вся́ком благоче́стії і чистоті́, сподо́блюся со всі́ми святи́ми сла́вити всесвято́є і́м'я Отця́, і Си́на, і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["Архієре́ю Бо́жий, священному́чениче Христо́в, Анти́по преблаже́нне, і́же апо́столом сопресто́льник, і святи́телем сла́ва, ти єси́, архієре́ю, церко́вноє світи́ло і утвержде́ніє ві́ри, пред проти́вними богобо́рці дерзнове́нно Христа́ іспові́дал єси́, і прине́слся єси́ я́ко кади́ло благово́нно, і я́ко а́гнець незло́бив і му́ченик пра́веден, во вол мі́дян разжже́н вве́ржен, святи́телю, і моли́тви благода́рственния в нем Бо́гу і Отцю́ возсила́я, я́ко со́лнце возсія́л єси́, і муче́нієм свої́м томи́теля велія́ра до конця́ сокруши́. Сего́ ра́ди Христо́с тя просла́ви на Небесі́, і на землі́ всю вселе́нную осіява́єши да́нною ті благода́тію, стра́ждущим от неутеши́мия зубни́я болі́зні цільби́ подає́ши, непреста́нно призива́ющим тя с ві́рою. І ни́ні, усли́ши м'я, грі́шнаго і недосто́йнаго раба́ Твоєго́ (ім’я), в час сей с ві́рою призива́ющаго тя, я́ко і моле́бноє пі́ніє приноси́ти хода́тая і моле́бника к Бо́гу тя предлага́ю."]},{"h":"Молитва третя","ps":["Архієре́ю Бо́жий, священному́чениче Анти́по, усли́ши м'я, грі́шнаго раба́ твоєго́ (ім’я), в час сей, в о́ньже тебі́ моле́ніє приношу́, і помоли́ся о мні грі́шнім ко Го́споду Бо́гу об отпуще́нії гріхо́в мої́х, і нестерпи́мия і неутеши́мая зубни́я болі́зні ізба́ви м'я моли́твами, свя́те, твої́ми."]}],"notes":[]},{"u":"Молитва святим мученицям Євдокії, Дарії, Дарії і Марії","e":"Prayer to the Holy Martyrs Eudocia, Daria, Daria and Maria","secs":[{"h":"Тропар, глас 4","ps":["Ца́рствія ра́ди Небе́снаго / мир і вся я́же в ми́рі оста́вили єсте́, / тісноту́ соверше́ннаго послуша́нія возлюби́вша, / ди́вния подви́жници і Христа́ ра́ди му́ченици / в годи́ну лю́тих іспита́ній в землі́ Ніжегоро́дстей процве́тшия, / блаже́нния ма́тері на́ша Євдокі́є, Да́ріє, Да́ріє і Марі́є, // молі́теся о спасе́нії душ на́ших."]},{"h":"Кондак, глас 6","ps":["Житіє́м пра́ведним / к досто́йному прия́тію му́ченичества себі́ угото́виша, / тридне́вная ізбіє́нія і смерть претерпі́ли єсте́, / неві́сти Христо́ви преди́вния, / блаже́нния Євдокі́є, Да́ріє, іна́я Да́ріє і Марі́є. / Ни́ні, мно́гими чудеси́ і ісціле́нії просія́вша, / молі́теся прилі́жно, // да спасе́ть Госпо́дь ду́ші на́ша."]},{"h":"Молитва","ps":["О ди́вния подви́жници і засту́пниці на́ша, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, дре́вніх му́ченик подража́тельници і́стинния, в тісноті́ послуша́нія без разсужде́нія, бді́ніїх многотру́дних і по́сте ізнури́тельнем пожи́вшия! Ни́ні к вам прибіга́єм і, к моще́м ва́шим припа́дающе, мо́лимся: о страстоте́рпиці святи́я, незло́бивия а́гници, своє́ю кро́вію Христа́ ра́ди обагре́нния і жесто́кими преда́телі ві́ри тридне́вно му́чимия і закла́нния! О прозорли́виці, мно́гія ду́ші от поги́белі ві́чния ісхи́тившия і о страда́ніїх пре́жде кончи́ни от Го́спода ізвіще́нния! О цели́тельници і чудотво́риці не то́кмо в землі́ Ніжегоро́дстей, но і по всей землі́ Українській прославля́ємия! Не оста́віте нас во грісі́х і беззако́ніїх поги́бнути, но помозі́те в покая́нії і́стиннім житіє́ на́ше сконча́ти і досто́йними яви́тися сла́вити Святу́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / святи́я му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Молитва святим мученикам Адріану і Наталії","e":"Prayer to the Holy Martyrs Adrian and Natalia","secs":[{"h":"Тропар, глас 4","ps":["Му́ченици Твої́, Го́споди, / во страда́ніїх свої́х вінці́ прия́ша нетлі́нния от Тебе́, Бо́га на́шего: / іму́ще бо крі́пость Твою́, / мучи́телей низложи́ша, / сокруши́ша і де́монов немощни́я де́рзости. / Тіх моли́твами // спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Му́ченик возсія́ Боже́ственная па́м'ять / і земни́я озари́ вся конці́ сві́тло, с весе́лієм зову́щих: // Ти єси́ му́чеников, Христе́, ра́дованіє."]},{"h":"Інший кондак, глас 4","ps":["Жени́ Богому́дрия Боже́ственная словеса́ в се́рдці положи́в, / Адрія́не, му́чениче Христо́в, к муче́нієм усе́рдно устреми́лся єси́, // с супру́гою віне́ць приє́м."]},{"h":"Молитва перша","ps":["О свяще́нная дво́їце, святі́ї му́ченици Христо́ві, Адрія́не і Ната́ліє, блаже́ннії супру́зі і до́блії страда́льці! Усли́шіте нас, моля́щихся вам со слеза́ми, і низпослі́те на ни вся благопотре́бная душа́м і тілесе́м на́шим, і молі́те Христа́ Бо́га, да поми́луєть нас і сотвори́ть с на́ми по ми́лості Своє́й, да не поги́бнем во грісі́х на́ших. Єй, святі́ї му́ченици, приймі́те глас моле́нія на́шего і ізба́віте ни моли́твами ва́шими от гла́да, губи́тельства, тру́са, пото́па, огня́, гра́да, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от напра́сния сме́рти і от всіх бід, печа́лей і болі́зней, да ви́ну, ва́шими моли́твами і предста́тельством укрепля́ємії, просла́вим Го́спода Ісу́са Христа́, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святі́ї му́ченици Адрія́не і Ната́ліє! Усли́шіте нас, раб Бо́жиїх (імена), в час сей к вам моля́щихся: помолі́теся о нас Влади́ці Христу́ Бо́гу, мно́го бо дерзнове́ніє к Нему́ стяжа́ли єсте́, і́скреннії моле́бници о нас су́ще. Умолі́те Го́спода отпусти́ти на́ша гріхи́ і Небе́снаго Ца́рствія сподо́бити нас, да ку́пно с ва́ми просла́вим великолі́поє і́м'я Пресвяти́я Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведній Софії, княжні Слуцькій","e":"Prayer to the Righteous Sophia, Princess of Sluck","secs":[{"h":"Тропар, глас 5","ps":["Свята́я пра́ведная ма́ти на́ша Софі́є, / нетлі́нієм моще́й і чуде́с сія́нієм почти́ тя Бог; / поминающеє твоє́ пра́ведноє житіє́. Тя мо́лим: // іспроси́ тілесе́м на́шим здра́віє і душа́м спасе́ніє."]},{"h":"Кондак, глас 4","ps":["Придіте, всі українськії жени́, / святу́ю Софі́ю восхва́лим, / уподобившуюся му́дрим ді́вам, / єле́й благода́ті Ду́ха Свята́го стяжа́вшую; / ті́мже умудри́ ю Госпо́дь подвиза́тися во утвержде́нії святи́я Правосла́вния ві́ри / і соблюда́ти Це́рков Єго́ непози́блему от єресе́й і раско́лов, / сего́ ра́ди благода́рні воспоє́м єй: / Ра́дуйся, гра́да Слуцька // і всея́ землі́ на́шея ра́досте і утвержде́ніє."]},{"h":"Молитва","ps":["О свята́я пра́ведная ма́ти на́ша, блаже́нная княги́не Софі́є, прийми́ с любо́вію приноше́ніє ві́ри, наде́жди і любве́ на́шея і вознеси́ ко Го́споду, і я́ко в житії́ била́ єси́ помо́щниця і засту́пниця всім правосла́вним Христия́ном землі́ твоєя́, та́ко і ни́ні укріпи́ нас тве́рдо і непоколеби́мо до сме́рти стоя́ти за ві́ру правосла́вную, согрі́й се́рдця на́ша любо́вію ко Го́споду і Пречи́стій Єго́ Ма́тері. Умоли́ Христа́ Бо́га на́шего, да сохрани́ть Це́рков Свою́ святу́ю от раско́лов і єресе́й, да утверди́ть в ней дух пра́вия ві́ри і благоче́стія, дух ві́дінія і любве́, дух ми́ра і ра́дости ві́чния, да всі ду́хом і і́стиною покланя́ються Єму́, да укріпи́ть ві́рних в благоче́стії і свя́тості, да обрати́ть отпа́дших от Правосла́вния Це́ркві во свята́я ні́дра єя́.","О, свята́я ма́ти, гра́да Слуцька похвало́ і ра́досте, умоли́ Го́спода, да ізба́вить град твой і вся гра́ди і ве́сі Бі́лия, Ма́лия і Вели́кия Русі́ от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні, от смертоно́сния я́зви, да ниспо́слеть прави́телем на́шим усе́рдіє, прозорли́вость, му́дрость і ві́рность, да управля́ють і су́дять по во́лі Єго́, да храня́ть установления Святи́я Це́ркве. Іспроси́ всім с ві́рою притекающим к ра́ці святи́х моще́й твої́х ми́рноє житіє́, тишину́, просвіще́ніє умо́в і серде́ць, соблюди́ їх от ко́зней вра́жиїх, от собла́знов ми́ра, во злі лежа́щаго, і от вся́кия ско́рби і ну́жди, обрати́ нас к покая́нію і ісправле́нію, да́руй заблудшим і́стини позна́ніє, недугующим ісціле́ніє. Сохрани́ нас благода́тними твої́ми моли́твами от всіх враго́во ви́димих і неви́димих і огради́ от вся́каго зла, да просла́вим во вся дні жи́зні на́шея Отця́ і Си́на і Свята́го Ду́ха і твоє́ заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я пра́ведная ма́ти на́ша Софі́є, / і чтем святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва преподобним Олександрі, Марфі та Олені Дівеєвським","e":"Prayer to Sts Alexandra, Martha and Helen of Diveyevo","secs":[{"h":"Тропар, глас 4","ps":["Яви́лися єсте́ землі́ Українськия украше́ніє, нача́льниці оби́телі Дивеєвськия преподо́бния ма́тері на́ша Алекса́ндро, Ма́рфо і Єле́но, благослове́ніє Цари́ці Небе́сния ісполнившия і дерзнове́ніє ко Го́споду стяжавшия, молі́те у престо́ла Пресвяти́я Тро́йці о спасе́нії душ на́ших."]},{"h":"Кондак, глас 8","ps":["Дивеєвськия світи́льници всесві́тлия, преподо́бния ма́тері на́ша Алекса́ндро, Ма́рфо і Єле́но, в поще́нії, бді́нії, моли́тві і труді́х до́брі подвиза́лися єсте́ і по сме́рті нас освещаєте чуде́с істоченьми і ісціля́єте неду́гующих душі́; молі́те Христа́ Бо́га гріхо́в оставле́ніє дарова́ти любо́вію чту́щим святу́ю па́м'ять ва́шу."]},{"h":"Молитва","ps":["О, преподо́бния ма́тері на́ша, Алекса́ндро, Ма́рфо і Єле́но, а́ще і сконча́ли єсте́ жизнь свою́ ті́лом, но ду́хом не отступа́єте от нас, руководствуєте і наставля́єте ше́ствовати по за́повідем Госпо́днім і носи́ти крест свой і послі́довати Влади́ці Христу́ Бо́гу на́шему. Ви, преподо́бния, вку́пі с преподо́бним і богоно́сним отце́м на́шим Серафи́мом, Саро́вським чудотво́рцем, імеєте дерзнове́ніє ко Пресвяті́й Тро́йце і Пречи́стій Ді́ві Марі́ї. Бу́діте моли́твенниці о нас недосто́йних, жи́тельствующих во святі́й оби́телі сей, єй же ви і нача́льниці. Бу́діте помо́щници і засту́пниці всім приходящим с ві́рою і ко святи́м моща́м ва́шим припадающим, да, ва́шими моли́твами сохраня́ємі, невреди́ми от вся́каго зла пребу́дем, сла́в'яще Святу́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм вас, преподо́бния ма́тері на́ша Алекса́ндро, Ма́рфо і Єле́но, і чтим святу́ю па́м'ять ва́шу, ви бо мо́лите о нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва Соборові Дівеєвських святих","e":"Prayer to the Synaxis of the Saints of Diveyevo","secs":[{"h":"Тропар, глас 5","ps":["Днесь церко́вная расширяються ні́дра, / приє́млющи бога́тство Бо́жия благода́ті / і ра́дується Пресвяти́я Богоро́диці ізбра́нная оби́тель, / па́м'ять соверша́юще многоімени́таго ли́ка святи́х, / в Небе́снім Дивеєве торжеству́ющих // і моля́щихся о душа́х на́ших."]},{"h":"Кондак, глас 8","ps":["Тро́йці сосу́ди яви́стеся честни́м ва́шим житіє́м / і Пресвяти́я Богоро́диці послу́шници, / всі святі́ї в землі́ Дивеєвстей просія́вшії, // пом'яні́те нас у Престо́ла Бо́жия во Ца́рствії Небе́снім."]},{"h":"Молитва","ps":["О, всечестни́й собо́ре святи́х, в землі́ Дивеєвстей просія́вших, по́лче Боже́ственний, по́двиги свої́ми в Ца́рськоє побідоно́сноє ополче́ніє возше́дий! О святі́ї, любо́вію ко Пречи́стій Ді́ві Марі́ї і Уделу Єя́ Четве́ртому совокупленнії, ізбра́нници Цари́ці Небе́сния і при́снії Єя́ послу́шници! Се ни́ні в день о́бщаго ва́шего торжества́ прино́сим вам сіє́ хвале́бноє пі́ніє.","Прославля́єм твоя́ вели́кия чудеса́, преподо́бне о́тче наш Серафи́ме, люби́миче і собесі́дниче Влади́чиці на́шея Пресвяти́я Богоро́диці і всім прибегающим к тебі́ скоропослу́шний помо́щниче! Сохрани́ нас от пре́лестей ми́ра сего́ лука́ваго, да отве́ргшеся себе́ і взе́мше крест свой, послі́дуєм Христу́, распина́юще плоть свою́ со страстьми́ і похотьми́, нося́щи тяготи́ друг дру́га.","Ублажа́єм ва́ше свято́є житіє́, преподо́бния Алекса́ндро, Ма́рфо і Єле́но, нача́льниці оби́телі Дивеєвськия, ка́мень ві́ри во основа́ніє єя́ положившия, терпі́нієм і му́жеством до конця́ врага́ низложившия і нас от ко́зней єго́ ізбавляющия. Молі́теся да дух ва́шея любве́ ко Го́споду і ре́вность о угожде́нії Єму́ не оскудіва́єть в нас.","Восхваля́єм ва́шу богоподража́тельную любо́в, блаже́нния Христа́ ра́ди юро́дивия ма́тері на́ша Пелагі́є, Параске́во і Марі́є, і́бо посрами́ли єсте́ прему́дрость ві́ка сего́, вознося́щуюся на ра́зум Бо́жий. Помозі́те нам спаси́тельним бу́йством Креста́ Христо́ва утверди́вшеся, го́рняя при́сно, а не земна́я помишля́ти.","Велича́єм ва́ші великії по́двиги, новому́ченици і іспові́дниці пресла́внії Серафи́ме, Михаї́ле, Іа́кове, Пелагі́є, Ма́рфо і Матро́но, Євдокі́є, Да́ріє, Да́ріє і Марі́є. Споспішеству́йте нам ві́ру правосла́вную тве́рдо содержа́ти, да спаси́тельноє сі́м'я, ва́ми всі́янноє, не ізсуше́но бу́деть зно́єм неві́рія, но плод ізоби́льний да принесе́ть.","О, святі́ї сро́дниці на́ші! Не оста́віте ча́да ва́ша духо́вная, да в бу́дущем ві́ці усли́шим от вас блаже́нний глас ко Го́споду: се ми, і ді́ти, я́же дал єси́ нам, Го́споди! І, ра́дующеся, ку́пно с ва́ми просла́вим Бо́га, в Тро́йці покланя́ємаго, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / всі святі́ї землі́ Дивеєвськия, / і чтим святу́ю па́м'ять ва́шу, / ви бо мо́лите за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва святому мученику Леоніду і мученицям Харієссі, Ніці, Галині, Каліссі, Нунехії, Василіссі, Феодорі, Ірині та іже з ними постраждалим","e":"Prayer to the Holy Martyr Leonidas and the Martyrs Chariessa, Nike, Galina, Kalisa, Nunekhia, Basilissa, Theodora, Irene and those who suffered with them","secs":[{"h":"Тропар мученикам, глас 4","ps":["Му́ченици Твої́, Го́споди, / во страда́ніїх свої́х вінці́ прия́ша нетлі́нния от Тебе́, Бо́га на́шего, / іму́ще бо крі́пость Твою́, / мучи́телей низложи́ша, / сокруши́ша і де́монов немощни́я де́рзости. / Тіх моли́твами // спаси́ ду́ші на́ша."]},{"h":"Кондак мученикам, глас 2","ps":["Світи́льници сві́тлії я́вльшеся, боже́ственнії му́ченици, / твар всю сві́тлостію чуде́с озаря́єте, / неду́ги разріша́юще і глубо́кую тьму всегда́ отгоня́юще, // Христу́ Бо́гу моля́щеся непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпці святі́ї, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]},{"h":"Молитва","ps":["О святі́ї му́ченици! Прострі́те благоприя́тния моли́тви ва́ша ко Го́споду і Созда́телю на́шему і умолі́те Єго́ бла́гость дарова́ти нам (імена) вся к ві́чному спасе́нію потре́бная, та́же і к житію́ сему́ вре́менному ну́жная: ві́руєм бо несомні́нно, я́ко вся возмо́жна вам, я́ко і́стинним Єго́ уго́дником. Єй, чудотво́рці святі́ї! Не посраміте́ упова́нія на́шего, но моли́твами ва́шими сотворі́те нас наслі́дники би́ти Ца́рствія Христо́ва, да прославля́єм человіколю́біє в Тро́йці сла́вимаго і покланя́ємаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, і ва́ше свято́є заступле́ніє, во ві́ки віко́в."]}],"notes":[]},{"u":"Молитва святій мучениці Фомаїді Єгипетській","e":"Prayer to the Holy Martyr Thomais of Egypt","secs":[{"h":"Тропар, глас 4","ps":["А́гниця Твоя́, Ісу́се, Фомаї́да, зове́ть ве́ліїм гла́сом: Тебе́, Женише́ мой, люблю́, і Тебі́ і́щущи страда́льчествую і сраспина́юся, і спогреба́юся Креще́нію Твоєму́, і стражду́ Тебе́ ра́ди, я́ко да ца́рствую в Тебі́, і умира́ю за Тя, да і живу́ с Тобо́ю; но я́ко же́ртву непоро́чную прийми́ м'я, с любо́вію поже́ршуюся Тебі́. Тоя́ моли́твами, я́ко Ми́лостив, спаси́ душі́ на́ша."]},{"h":"Кондак, глас 2","ps":["Храм твой всечестни́й я́ко цільбу́ душе́вную обрі́тше, всі ві́рнії велегла́сно вопіє́м ті: ді́во му́ченице, Фомаї́до великоімени́тая, Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, всехва́льная му́ченице Фомаї́до! За чистоту́ супру́жества да́же до кро́ве подвиза́вшися і цілому́дрія ра́ди ду́шу свою́ положи́вши, досто́йна пред Го́сподем обріла́ся єси́, во є́же в ли́ці преподо́бних дів почте́нній тебі́ би́ти. Усли́ши нас моля́щихся тебі́, і я́коже дре́вле бори́мії от пло́ті ціли́тельницю тя імі́яху, по дарова́нной тебі́ от Бо́га благода́ті, си́це і ни́ні прибегающим ко предста́тельству твоєму́ пода́ждь отра́ду і свобожде́ніє от плотські́я бра́ні, і цілому́дренноє житіє́ і незазо́рноє в супру́жестві і ді́встві пребива́ніє твої́ми богоприя́тними моли́твами всім ісхода́тайствовати потщи́ся, я́ко да тілеса́ на́ша храм живу́щаго в нас Свята́го Ду́ха бу́дуть. О, преізбра́нная в жена́х і ві́рная рабо́ Христо́ва! Помози́ нам, да не поги́бнем со страстьми́ і похотьми́ на́шими, но да упра́вимся умо́м на́шим і укріпі́мся се́рдцем на́шим во вся́ком благоче́стії і чистоті́, сла́в'яще твою́ по́мощ і предста́тельство, благода́ть же і ми́лость Трієди́наго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Євфимію, архієпископу Новгородському","e":"Prayer to St Euthymius, Archbishop of Novgorod","secs":[{"h":"Тропар, глас 4","ps":["Ізбра́н бив Бо́гові от ю́ности, / святи́телю Євфи́міє, / і сего́ ра́ди архієре́йства са́ном почте́н бив, / упа́сл єси́ лю́ди, і́же тебе́ Бо́гом вруче́нния; / ті́мже і по преставле́нії чуде́с дарова́нія от Го́спода прия́л єси́ / ісціля́ти разли́чния неду́ги. / Того́ моли́ о нас, / соверша́ющих честну́ю па́м'ять твою́, // да тебі́ всі непреста́нно ублажа́єм."]},{"h":"Кондак, глас 8","ps":["Я́ко архієре́єм сопресто́льник / і святи́телем ізря́дний побо́рник бил єси́, святи́телю Євфи́міє, / не преста́й сохраня́я оте́чество твоє́, / град же і лю́ди, і́же тебе́ ві́рою почита́ющия / і честни́м моще́м твої́м покланя́ющіяся, / да велегла́сно тебі́ всі вопіє́м: // ра́дуйся, святи́телю Богому́дре."]},{"h":"Молитва","ps":["О́тче святи́телю Євфи́міє! Ти от ю́ности твоєя́ Христа́ возлюби́л єси́, і благода́тію Єго́ укріпля́єм, вся плотська́я мудрова́нія умертви́л єси́, чи́стим же житіє́м і кро́тким нра́вом Го́сподеві угоди́л єси́, і по благода́ті Єго́ на престо́лі святи́тельства бил єси́, і яви́лся єси́, па́стві Христо́ві Вели́каго Нова́гра́да па́стир ізря́ден, полага́я ду́шу твою́ о ста́ді твоє́м. Ті́мже і по сме́рті твоє́й просла́ви тя Пастиренача́льник Христо́с подая́нієм чуде́с, от тебе́ істека́ющих, подая́ нам тебе́ о́браз доброді́тельнаго житія́ і те́плаго моли́твенника. Ті́мже і аз грі́шний і уни́лий, припа́дая к моще́м твої́м, молю́ся тебі́ усе́рдно: уго́дниче Христо́в, даждь мі ру́ку по́мощі, воздви́гни м'я моли́твами твої́ми із глубини́ гріхо́вния. Се бо волна́ми страсте́й плотськи́х і уни́нія, і іни́ми тьмочи́сленними жите́йськими треволне́нії обурева́юся і погиба́ю. Бу́ди у́бо мні, многогрі́шному, те́плий ко Христу́ предста́тель і моли́твенник, да і аз, от потопле́нія гріхо́внаго ізба́влен, ко приста́нищу непоро́чнаго житія́ благода́тію Христо́вою дости́гну, і чи́стим житіє́м просла́влю Спаси́теля моєго́, Кро́вію Своє́ю мене́ іскупи́вшаго, і, та́ко житіє́ сконча́в, получу́ живо́т ві́чний во Ца́рствії Небе́снім, іді́же сла́виться пречестно́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Павлу Таганрозькому","e":"Prayer to the Righteous Paul of Taganrog","secs":[{"h":"Тропар, глас 4","ps":["Взиску́я Оте́чества Небе́снаго, / дом роди́телей твої́х оста́вил єси́ / і, тлі́нная бога́тства ми́ра презрі́в, / воздержа́нієм і труди́ моли́тву у́мную стяжа́л єси́. / Ті́мже, мно́гими чудеси́ і зна́меньми от Го́спода просла́вився, / с ві́рою приходя́щим к тебі́ во вся́ціх напа́стіх помога́єши: / пра́ведне о́тче Па́вле, / моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Си́лу Бо́жию в не́мощі стяжа́л єси́ / і боже́ственния благода́ті сосу́д ізбра́нний яви́лся єси́, / ті́мже от Небесного Врача́ дар ісціле́нія приї́м, / неду́ги на́ша тіле́сния і душе́вния врачу́єши, / пра́ведне о́тче Па́вле, моли́ Христа́ Бо́га / спасти́ град і лю́ди, тя почита́ющия."]},{"h":"Молитва","ps":["О, вели́кий уго́дниче Бо́жий і чудотво́рче, о́тче Па́вле! Ти, на висоту́ доброді́телей возше́д, я́ко пресві́тлая звізда́, житіє́м твої́м возсія́л єси́ і, стра́нничеськоє жи́тельство ізбра́в, ми́ра сего́ кра́сная ні во что́же вміни́л єси́. Ті́мже Всепра́ведний Судія́ мно́гими чудеси́ тя просла́ви, ду́шу же твою́ святу́ю в небе́сния оби́телі всели́, іді́же, любве́ Бо́жия наслажда́яся, на́ша ну́жди зри́ши і проше́нія сли́шиши. Сего́ ра́ди бу́ди нам в неду́зіх ціли́тель, по мо́рю пла́вающим ко́рмчий, і утопа́ющим благонаде́жноє ізбавле́ніє. О, Па́влі блаже́нне, іспроси́ всем, во вся́цій ну́жді су́щим, і ко твоєму́ засту́пленію прибега́ющим, вся́кий дар коєму́ждо благопотре́бен: ві́ри і любве́ преспі́яніє, благоче́стія умноже́ніє, ми́ра утвержде́ніє, больни́м ісціле́ніє, печа́льним утіше́ніє, бе́дствующим по́мощ, оби́димим заступле́ніє. І сподо́би ни, уго́дниче Бо́жий, моли́твами твої́ми благоче́стно житіє́ земно́є сконча́ти, Небе́сноє Ца́рствіє і живо́т ві́чний унаслі́дити со всі́ми святи́ми во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому мученику Мамонту Кесарійському","e":"Prayer to the Holy Martyr Mamas of Caesarea","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Ма́мант / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами // спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Жезло́м, свя́те, от Бо́га тебе́ да́нним, / лю́ди твоя́ упаси́ на па́житіх живоно́сних, / зві́ри же неви́димия і неукроти́мия / сокруши́ под но́ги тя пою́щих, / я́ко всі, і́же в біда́х, // предста́теля тя те́пла, Ма́манте, і́муть."]}],"notes":[]},{"u":"Молитва преподобному Паїсію Святогорцю","e":"Prayer to St Paisios the Athonite","secs":[{"h":"Тропар, глас 5","ps":["Боже́ственния любве́ огнь приє́мий, / превосходя́щим по́двигом вда́лся єси́ весь Бо́гові, / і утіше́ніє мно́гим лю́дем бил єси́, / словеси́ боже́ственними наказу́яй, / моли́твами чудотворя́й, / Паї́сіє Богоно́се, / і ни́ні мо́лишися непреста́нно // о всем ми́рі, преподо́бне."]},{"h":"Кондак, глас 8","ps":["А́нгельськи на землі́ пожи́вий, / любо́вію просія́л єси́, преподо́бне Паї́сіє, / мона́хов вели́коє утвержде́ніє, / ві́рних к житію́ свято́му вождь, / вселе́нния же утіше́ніє сладча́йшеє показа́лся єси́, / сего́ ра́ди зове́м ті: // ра́дуйся, о́тче всеми́рний."]},{"h":"Молитва","ps":["О святи́й преподо́бний і богоно́сний о́тче наш Паї́сіє, возлю́бленний наш покрови́телю і богому́дрий наста́вниче, лі́ствицею доброді́телей от землі́ в Небе́сноє Ца́рство восше́дий і благода́ть прия́вий во є́же хода́тайствовати о нас пред Престо́лом Всеми́лостиваго Го́спода на́шего. Мо́лим тя отврати́ти ни от путі́ гріхо́внаго і научи́ти ни Го́сподеві соверше́нни плоди́ покая́нія і обновле́нія во Христі́ душ на́ших приноси́ти.","Ти, святи́й о́тче, во дні житія́ земна́го мно́зі тя́жки болі́зні і неду́ги неісці́льния уврачева́вий і душі́ гріхми́ і скорбми́ стра́ждущих ісціли́вий, ни́ні предстоя́ Бо́гу, Того́ милосе́рдіє к нам приклони́, да твоєго́ предста́тельства ра́ди любо́вію чту́щих святу́ю па́м'ять твою́ ісціли́ть, да́руєть крі́пость во іскуше́ніїх, му́жество в борбі́ с ду́хом зло́би, і́щущим ві́чній поги́белі на́шей, да да́руєть нам проще́ніє всіх на́ших гріхо́в, ї́хже от ю́ности на́шея да́же до настоя́щаго дне по́мислом, сло́вом і ді́лом соверши́хом, да научи́ть ни, я́же нам подоба́єть твори́ти, я́ко да ви́ну Єму́ і бли́жнім с любо́вію і смире́нієм послу́жим.","Єй, о́тче святи́й, наста́ви нас, во о́браз житія́ твоєго́, і́же любве́ і милосе́рдія іспо́лнено бисть, уз гріхо́внаго жи́тельства разріши́вшеся, к Небе́сним Черто́гам взи́ти, іді́же да восхва́лим Всемилосе́рднаго Триіпоста́снаго Го́спода на́шего во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому мученику Олександру Римському","e":"Prayer to the Holy Martyr Alexander of Rome","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Алекса́ндре, / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами / спаси́ душі́ на́ша."]},{"h":"Молитва","ps":["О, святи́й му́чениче Алекса́ндре! Мо́лим тя ми, немощниє, унилиє, скорб'ями мучимиє, бу́рею іскуше́ній і собла́знов смущаємиє, ду́хом ослабеваємиє, до́брих діл не іму́щиє, помози́ нам свергнуть с себ'я́ бре́м'я нераде́нія і лі́ності, даби́ бо́дро приступить к по́двигам трудолю́бія і пребить тве́рдими в стремле́нії і ді́ланії духо́вном для снисканія себі́ спасе́нія. Усли́ши мольбу́ на́шу, святи́й Алекса́ндре, о боля́щих, страдающих тіле́сними і душе́вними неду́гами, ісціли́, являясь на по́мощ нам, чту́щим святу́ю па́м'ять твою́, і́бо ти пред кончи́ною своє́ю моли́лся о почита́ющих па́м'ять твою́, да ізба́влени бу́дуть от вся́кия болі́зні. Яви́ заботу твою́ о нас, от болі́зней сохрани́ і от лю́тих неду́гов ісціли́, да всі́ми просла́виться пресвято́є і́м'я Бо́жиє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О пресла́вний уго́дниче і му́чениче Христо́в, до́блій во́їне Царя́ Небе́снаго, Алекса́ндре блаже́нне, ми́лостиваго Бо́га подража́телю, і́же Христа́ на землі́ дерзнове́нно іспові́дав і многообра́зния муки́ Єго́ ра́ди претерпі́в, неув'яда́ємий прия́л єси́ віне́ць на небесі́: ни́ні же вку́пі с мате́рією твоє́ю Пименією, предстоя́ у Престо́ла Сла́ви Бо́жия, моли́ о нас человіколю́бноє благоутро́біє Бо́жиє, да сотвори́ть с на́ми по неізрече́нній Своє́й бла́гости, во є́же не поги́бнути нам во грісі́х на́ших. Єй, му́чениче святи́й, ві́ми бо, я́ко і́маши мно́гоє дерзнове́ніє ко Го́споду є́же моли́тися о всіх притека́ющих к Тебі́ с ві́рою.","Вознеси́ моли́тву те́плую Це́ркве Зижди́телю о ми́рі всего́ ми́ра, благостоя́нії Святи́х Бо́жиїх Церкве́й і соєдине́нії всіх ві́рних чад Це́ркви Христо́ви, в чистоті́ і честні́м жи́тельстві пребива́ющих, і о є́же ізба́вити па́ству правосла́вную от тя́жких бур жите́йських і всіх наві́тов ду́ха зло́би поднебе́сния. Диха́нієм же Всесвята́го Ду́ха да ум'ягчаться се́рдця сино́в противле́нія, раздирающих хито́н єди́нства Це́ркві Христо́вой, си́лою Боже́ственнаго ми́ра і любві́ во ісціле́ніє кровоточащей ра́ни Єго́ во вселе́нній, і во спасе́ніє всіх живу́щих на землі́.","Нам же, ві́рний дру́же Христо́в, бу́ди у́бо Засту́пник і Покрови́тель во вся дні житія́ на́шего, избавля́я нас от враго́во ви́димих і неви́димих, па́че же по ісхо́ді на́шем защити́ от лука́вих духо́в, і на Стра́шнім Суді́ Христо́ві не забу́ди нас убо́гих те́плим хода́тайством твої́м, да спаса́ємих часть улучи́вше, просла́вим Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Сампсону Странноприймцю","e":"Prayer to St Sampson the Hospitable","secs":[{"h":"Тропар, глас 8","ps":["В терпі́нії твоє́м стяжа́л єси́ мзду твою́, о́тче преподо́бне, / в моли́твах непреста́нно терпі́вий, / ни́щія возлюби́вий і сія́ удовли́вий, / но моли́ся Христу́ Бо́гу, Сампсо́не ми́лостиве блаже́нне, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко врача́ всеїзря́дна і моли́твенника благоприя́тна, / к ра́ці твоє́й Боже́ственній притека́юще, Сампсо́не Богому́дре преподо́бне, / соше́дшеся любо́вію, псалми́ і пі́сньми ра́дующеся, Христа́ прославля́єм, // такову́ю тебі́ благода́ть подава́юща ісціле́ній."]},{"h":"Молитва перша","ps":["О те́плий моли́твенниче, бла́гостний о́тче, преподо́бне Сампсо́не! Моли́ Бо́га о мні, грі́шнім, і низпосли́ от Всеблага́го Влади́ки по́мощ мі і ізбавле́ніє, привре́менна бо єсть жизнь моя́ і іспо́лнена труда́, скорбе́й і болі́зней. Укріпи́ се́рдце моє́, да возмогу́ понести́ тяготу́ мою́, і не попусти́, да превозмо́гуть іскуше́нія мно́гая моя́ ма́лия си́ли, но споспі́шествуй мні заступле́нієм твої́м і посреді́ обстоя́ній і бід упра́ви путь мой в Ца́рство Небе́сноє, да сла́влю просла́вльшагося в тебі́ Го́спода во ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О, предста́телю наш пред Го́сподем і те́плий моли́твенниче, преподо́бне о́тче Сампсо́не! Зри́ши с Небесе́, я́ко погиба́єм во обстоя́ніїх і ско́рбіх: прилага́ється бо посреді́ нас неві́ріє ко отсту́пству і разділе́нію, оскудіва́єть люби́, умножа́ються же беззако́нія і собла́зни, болі́зні і ско́рби мно́жества бездо́мних, гла́дних і си́рих. Отку́ду, о́тче, при́ймем си́ли, да устро́їм проти́ву собла́знов ми́ра, сохрани́м в сердця́х на́ших любо́в і ві́ру Христо́ву і упова́ніє правосла́вних і приложи́м попече́ніє о больни́х і бі́дних, а́ще не ти засту́пиши нас твої́м предста́тельством те́плим, прося́ нам по́мощі от Бо́га в не́мощіх на́ших? Сохрани́ у́бо моли́твами твої́ми благомо́щіє Христолюби́ваго наро́да на́шего, крі́пость страни́ Українськия, мир і безм'яте́жіє Святи́я Це́ркве, всіх же нас огради́ і сохрани́ непоколеби́ми посреді́ неві́рних, понося́щих ві́ру на́шу хули́телей, огради́ от собла́знов, возбуди́ сердца́ іму́щих к ми́лованію ни́щих, согрі́янію хла́дних, напита́нію а́лчущих і призрі́нію бездо́мних, утоли́ умноже́ніє скорбе́й і болі́зней, гла́да і про́чих уязвля́ющих ни бід, да́руй осла́бу стра́ждущим младе́нцям, ниспошли́ от Го́спода укріпле́ніє, утіше́ніє і отра́ду жена́м, в му́ках діторожде́нія су́щим, і всім, в тя́жких рабо́тах, в больни́цях, заточе́ніїх і темни́цях унива́ющим, да всі просла́вим в Тро́йці сла́вимаго Бо́га Отця́, і Си́на, і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Петру, царевичу Ординському, Ростовському","e":"Prayer to St Peter, Tsarevich of the Horde, of Rostov","secs":[{"h":"Тропар, глас 8","ps":["Оте́чества своєго́, блаже́нне Пе́тре, удали́вся, / і богоме́рзькую ві́ру отню́д возненави́дів, / от тьми во світ прише́л єси́, / і всели́лся єси́ во сла́вний і многонаро́дний град Росто́в, / в не́мже житіє́ че́стно пожи́в, / це́рков во і́м'я святи́х апо́стол Петра́ і Па́вла воздви́гл єси́ Христо́вою благода́тію, / і сію́ чу́дними іко́нами, я́ко неві́сту украси́в, / святи́теля же, і кня́зя, і вся лю́ди житіє́м свої́м удиви́л єси́, / ті́мже і по сме́рті твоє́й Христо́с да́ром чуде́с обогати́ тя. / Помина́й нас чту́щих пресві́тлую па́м'ять твою́, преподо́бне о́тче Пе́тре, // і моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́ся ве́ліє со́лнце Христо́вой Це́ркві, / просвіща́я уче́нія світлостьми́, всече́стне, / я́ко черпа́лом злати́м, / от кла́дязя неіско́паннаго чуде́с поче́рпл єси́, / от істо́чника неістощи́маго, / на па́м'ять успе́нія твоєго́ прише́дшим, всеблаже́нне Пе́тре, // ни́ні всім подава́єши гріхо́в проще́ніє, сла́во преподо́бним."]},{"h":"Молитва перша","ps":["О преподо́бне Пе́тре царе́виче, Росто́вський чудотво́рче! Я́коже із мра́ка язи́чеськаго во світ Єва́нгельськаго уче́нія Госпо́дь тя призва́, та́ко умоли́ Єго́, да і нас по неізрече́нній Своє́й бла́гості і человіколю́бію і́зметь всеси́льною Своє́ю десни́цею із тьми гріхо́вния, і осія́єть сердця́ на́ша к ді́ланію Єго́ Боже́ственних за́повідей. Я́коже ти ізбі́г м'яте́жа мирськи́х волне́ній, во ангелоподо́бноє безпеча́льноє житіє́ сподо́бился єси́ дости́гнути, та́ко сподо́би і нам грі́шним мо́ря сего́, вла́ємаго страстьми́, пучи́ну безм'яте́жно препли́ти, імі́я тя, о́тче, ко́рмчаго о Го́споді на́шем, і дости́гнути чи́стим покая́нієм ко приста́нищу спасе́нія ві́чнаго. І я́коже імі́л єси́ споспі́шников тебі́ верхо́вних апо́столов Петра́ і Па́вла в созида́нії оби́телі, та́ко подви́гни їх умилосе́рдитися і о нас недосто́йних, і дарова́ти нам от сугу́бия апо́стольськія бла́гости дерзнове́ніє ко Христу́ Бо́гу. Ві́руєм бо, я́ко а́ще мо́щі твоя́ святи́я і сокрове́нни в землі́, но ти ца́рствуєши со ізбра́нними Бо́жиїми на Небесі́: ісхода́тайствуй у́бо, да і нам грі́шним моли́твами твої́ми отве́рзеться двер Ца́рствія Небе́снаго в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне о́тче Пе́тре царе́виче, душе́ю на Небесі́ Престо́лу Бо́жию предстої́ши і Тро́їчния сла́ви наслажда́єшися, ті́лом же на землі́ в Боже́ственном хра́мі сем почива́яй, і да́нною ті сви́ше благода́тію разли́чная істоча́яй чудеса́, при́зри ми́лостивим о́ком на предстоя́щия честні́й твоє́й ра́ці лю́ди і прося́щия уми́льно твоєя́ по́мощі; се бо ми безмі́рними согріше́нії пра́ведний гнів Бо́жий на ся наведо́хом і вся́кия ми́лости недосто́йни сотвори́хомся; тім же не смі́юще вознести́ очеса́ на́ша к висоті́ небе́сній, ніже́ вознести́ моле́бний глас ко Го́споду, се́рдцем сокруше́нним і смире́нним ду́хом тебі́ в хода́тайство і на по́мощ призива́єм, іспроси́ у Го́спода Це́ркві благостоя́ніє, возду́ха благорастворе́ніє, землі́ плодоно́сіє; ізба́ви всіх, ві́рою несомні́нною к Бо́гу приходя́щих і к ра́ці моще́й твої́х прибіга́ющих, от вся́ких бід душе́вних і тіле́сних; бу́ди печа́льним уті́шитель, неду́гующим врач, напа́ствуємим помо́щник, вдови́цям засту́пник, си́рим защи́тник, младе́нцям пита́тель, стра́нствующим путево́ждь, ста́рим укріпле́ніє, пла́вающим ко́рмчий; ісхода́тайствуй всім, твоєя́ по́мощі тре́бующим, вся, я́же ко спасе́нію поле́зная, я́ко да твої́ми моли́твами наставля́ємі, путь маловре́меннаго житія́ бе́збідні соверши́м, улучи́м на Небесі́ ві́чний поко́й і просла́вим всіх благи́х Да́теля, в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в, амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Феодору Студиту","e":"Prayer to St Theodore the Studite","secs":[{"h":"Тропар, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / вселе́нния світи́льниче, / мона́шествующих Богодухнове́нноє удобре́ніє, / Фео́доре прему́дре, / уче́ньми твої́ми вся просвіти́л єси́, / цівни́це духо́вная, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["По́стничеськоє і равноа́нгельноє житіє́ твоє́ / страда́льчеськими уясни́л єси́ по́двиги / і А́нгелом совсе́льник, Богоблаже́нне, яви́лся єси́, Фео́доре. / С ни́ми Христу́ Бо́гу моля́ся // не преста́й о всіх нас."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Фео́доре! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу! Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́; не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас недосто́йних у Престо́ла Вседержи́теля, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со А́нгельськими во́їнствами, со Безпло́тними ли́ки, с Небе́сними си́лами, у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́в, возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Бо́гу на́шему Ісу́су Христу́; Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О, святи́й Фео́доре, іспові́дник Правосла́вія, зако́на Бо́жия ревни́тель, наста́вник пра́вой ві́ри, помози́ нам і при́зри на нас, с ві́рою і усе́рдієм прибіга́ющих к тебі́! От царе́й іконобо́рцев за почита́ніє святи́х іко́н око́ви, ізгна́ніє, заточе́ніє претерпі́л ти, преподо́бний, і мно́жество тя́жких ран і же́стоких ударов, от ї́хже і болі́знь нестерпи́мую получи́л.","Великий і дивний Феодоре, що до кінця в скорботах витримав, і нам, що вражаємося напастями й хвилюваннями життєвими, подай міцність душевну й тілесну для боротьби з бідами та для подолання пристрастей і підступів ворожих.","Молися за нас до Милосердного Господа, вірний рабе Божий, Феодоре, щоб визволив Він нас від ожорсточення й холодності серцевої та дарував нам лагідність, безгнівність, незлобивість, смирення й любов. Бачачи допомогу Твою, прославимо ми Господа і Спаса нашого Ісуса Христа, і тебе, благодійника нашого, віддячимо, з благоговінням шануючи пам’ять твою.","О, всехвальний, преподобний Феодоре, що вченням і піснями своїми Церкву Божу напоїв і звеселив, і нас, осліплених умом від спокус і марноти світу цього, просвіти пізнанням істини й визволи від блукань і сумнівів, щоб не уподібнюватися нам віку цьому.","О, уго́дниче Христо́в, Фео́доре, получи́вший от Бо́га благода́ть ісціле́нія неду́гующих, а найпа́че стра́ждущих желудком, уврачу́й і нас, одержи́мих разли́чними неду́гами і ісціли́ боля́щих желудком і пода́й нам здра́віє, бо́дрость і мир душе́вний. Не отри́ни нас, притека́ющих к тебі́, но заступи́ і помози́ нам. Предста́тельствуй за нас пред Спаси́телем на́шим, внемли́ мольба́м на́шим і іспо́лни проше́нія на́ші, да тобо́ю укріпля́єми, в труда́х і до́брих діла́х соверши́м ми тече́ніє жи́зні на́шей і сподо́бимся войти в Ца́рствіє Небе́сноє, Да вместе с тобо́ю восхва́лим і просла́вим Го́спода і Спа́са на́шего Ісу́са Христа́, со Безнача́льним Єго́ Отце́м і с Пресвяти́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святим дев’яти мученикам Кизицьким","e":"Prayer to the Holy Nine Martyrs of Cyzicus","secs":[{"h":"Тропар, глас 8","ps":["Святі́ї дев'яточи́сленнії му́ченици, / от разли́чних градо́во во єди́н лик совокупи́вшеся ма́нієм Боже́ственним, / му́жественно за Христа́ пострада́сте, / неви́димаго врага́ побіди́сте, / злові́рния кня́зі і мучи́телі посрами́сте ва́шим терпі́нієм, / огне́м же любве́ Бо́жия разжиза́ємі, / веще́ственно вас огнь му́чащий в хлад преложи́сте, / ті́мже даде́ся вам от Христа́ Бо́га благода́ть / тряса́вичную ісціля́ти болі́знь, / от нея́же і многови́дних страсте́й, // ми́лостивно спаса́йте і нас предста́тельством ва́шим, мо́лимся."]},{"h":"Кондак, глас 2","ps":["Тве́рдий і всесві́тлий лик му́ченик дев'яти́, / Трисо́лнечнаго Божества́ іспові́дниці, / на суди́щі Тому́ нача́льно взива́ху: / кров і ду́ші на́ша с тілеси́, / я́ко непоро́чную же́ртву, прино́сим Тебі́, Влади́ко, // в ли́ціх Небе́сних Твої́х сопричти́, я́ко Бог Ми́лостивий."]},{"h":"Молитва перша","ps":["§(зі служби, складеної святителем Димитрієм, митрополитом Ростовським, чудотворцем)","О всехва́льнії святі́ї му́ченици, до́блественнії раби́ Христо́ви, Феогни́де, Ру́фе, Антипа́тре, Феостихе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє і Филимо́не, і́же Христа́ ра́ди от разли́чних стран собра́стеся і Того́ соверше́нна Бо́га і Челові́ка дерзнове́нно в Ки́зиці пропові́дасте; принужда́єми би́вше куми́ром поклони́тися, і́доли попра́сте і кня́зя посрами́сте, разли́чних томле́ній і о́гненних преще́ній не убоя́стеся, і по разли́чнім страда́нії о́стрієм меча́ посі́чени би́сте, і пролія́сте за Христа́ кров свою́, я́ко во́ду, і то́ю, я́ко багряни́цею, Це́рков Христо́ву, я́ко неві́сту, украси́сте; ті́мже і ни́ні, увенчаннії неув'яда́ємим вінце́м безсме́ртния сла́ви, при́сно в неізглаго́ланній ра́дости с ли́ки а́нгельськими в небе́сних селе́ніїх водворя́єтеся, Боже́ственним сві́том облиста́ємі і зрі́нієм Єго́ добро́ти неізрече́нния наслажда́ющеся. Сего́ ра́ди і ми, смире́ннії, к вам притека́єм і, уми́льно на святи́й ваш о́браз взира́юще, мо́лим: ви мо́лите за ни Христа́ Бо́га, я́ко дерзнове́ніє к Нему́ іму́щії, да ва́шими святи́ми моли́твами вся́каго неду́га душе́внаго і тіле́снаго ізба́вимся. Вам бо от Бо́га даде́ся враче́бний дар от вся́ких скорбе́й с ві́рою к вам припадающия ціли́ти, я́коже і о́наго сла́внаго му́жа от тряса́вичния болі́зні уврачева́сте, да і ми, ві́рнії, то́жде получи́вше, почита́єм вас, святі́ї му́ченици, толи́ка дарова́нія іму́щих от Христа́ Бо́га, Єму́же і сла́ва ку́пно со Отце́м і Ду́хом Святи́м всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́ції уго́дниці Бо́жії, святі́ї му́ченици Христо́ви: Феогни́де, Ру́фе, Антипа́тре, Феостихе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє і Филимо́не! Ви Царя́ Христа́ ві́рнії слуги́ би́сте і по́двигом до́брим подвиза́стеся, претерпі́вше за Него́ муки́; ті́мже, по нело́жному Єго́ глаго́лу: іді́же єсьм Аз, ту і слуга́ Мой бу́деть, і ви ни́ні со А́нгели предстоїте́ Влади́ці Христу́ і с висоти́ небе́сния сла́ви призира́єті ми́лостивно на храм ваш і на моляющихся в нем.","Умолі́те у́бо Го́спода Сил Це́рков Єго́ Святу́ю і правосла́вноє Оте́чество на́ше сохрани́ти от напа́стей і бід, от всіх враг ви́димих і неви́димих, низложи́ти пре́лесть неві́рія і безбо́жия і ста́до Христо́во ізба́вити от волко́в, губ'я́щих є, глаго́лющих лука́воє до́броє, і до́броє лука́воє, полага́ющих тьму світ, і світ тьму; от шата́нія умо́в, я́ко трость, ві́тром коле́блемих, і от гріхо́внаго душ разслабле́нія.","Богодарова́нную благода́ть чуде́с ва́ших, му́ченици Христо́ви дев'яточи́сленнії, прострі́те ко всім нам, ві́рою к вам прибегающим, і вся на́ша неду́ги душе́вния і тіле́сния уврачу́йте, і вся проше́нія на́ша во бла́го іспо́лніте.","Єй, страстоте́рпці святі́ї, мо́лите за ни Го́спода, да низпосле́ть нам Боже́ственную благода́ть і дар Свята́го Ду́ха, всегда́ не́мощная врачу́ющаго і оскудіва́ющая восполняющаго, во єжи соді́ловати нам спасе́ніє своє́, заступле́нієм Христа́ Спа́са на́шего, і ізба́витися нам от сі́ті вра́жия і гріхо́в, і поми́ловатися душа́м на́шим, да і ми ку́пно с ва́ми і всі́ми святи́ми просла́вим Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь"]}],"notes":[]},{"u":"Молитва святителю Никиті, затворнику Печерському, єпископу Новгородському","e":"Prayer to St Nikita the Recluse of the Caves, Bishop of Novgorod","secs":[{"h":"Тропар, глас 2","ps":["Небе́снаго простра́нства жела́я, / от ю́ности в ті́сні мі́сті затвори́лся єси́, / в не́мже прельще́н бив от врага́, / па́ки смире́нієм і послуша́нієм побіди́л єси́ преле́стника крі́пці, Ники́то, / і ни́ні, предстоя́ Христо́ві, // моли́ спасти́ся всім нам."]},{"h":"Інший тропар, глас 4","ps":["Наслади́вся, Богому́дре, воздержа́нія / і жела́ніє пло́ті твоєя́ обузда́в, / на престо́лі святи́тельства сел єси́, / і я́ко звізда́ многосві́тлая, просвіща́я ві́рних сердця́ / заря́ми чуде́с твої́х, / о́тче наш, святи́телю Ники́то, / і ни́ні моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 1","ps":["Побіди́во вра́жия ле́сти до́блі / і сві́тло доброді́тельми просія́в, / святи́тельства оде́ждою обле́клся єси́, пресла́вне Ники́то, / в не́мже сві́том житія́ твоєго́ і чудеси́ сія́я па́че со́лнця, / мно́гих просвіти́в, приве́л єси́ Христо́ві, // Єго́же моли́ о нас, пою́щих тя."]},{"h":"Інший кондак, глас 6","ps":["Архієре́йства са́ном почти́вся / і чи́сті Чисті́йшему предстоя́, / прилі́жно моле́ніє за лю́ди твоя́ приноси́л єси́, / я́ко і дождь моли́твою свел єси́, / овогда́ же і гра́да запале́нія угаси́л єси́. / І ни́ні, святи́телю Ники́то, / моли́ Христа́ Бо́га, / спасти́ лю́ди твоя́ моля́щіяся, / да всі вопіє́м ті: // ра́дуйся, святи́телю, о́тче преди́вний."]},{"h":"Молитва","ps":["О, архієре́ю Бо́жий, святи́телю Ники́то! Усли́ши нас грі́шних, днесь во свяще́нний храм сей сте́кшихся, і честно́му о́бразу твоєму́ поклоня́ющихся, і ко свяще́нній твоє́й ра́ці припа́дающих, і умиле́нно вопію́щих: я́коже си́дя на престо́лі святи́тельства во Вели́ком Но́вегра́ді сем, і єди́ною належа́щу бездо́ждію, дождь моли́твами свел єси́, і па́ки гра́ду сему́ о́гненним пла́менем обстої́му, моли́твою пла́мень о́гненний угаси́л єси́. І ни́ні мо́лим тя, о святи́телю Христо́в Ники́то: моли́ся ко Го́споду, є́же ізба́вити Вели́кий Но́вград сей і вся гра́ди і страни́ христия́нскиє от тру́са, пото́па, гла́да, огня́, гра́да, меча́ і от всіх враго́во ви́димих к неви́димих, я́ко да ізря́дних ра́ди моли́тв твої́х спаса́ємі, сла́вим Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ ми́лостивноє предста́тельство, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва безсрібникам Косьмі й Даміану, чудотворцям Асійським","e":"Prayer to the Unmercenary Healers Cosmas and Damian, Wonderworkers of Asia","secs":[{"h":"Тропар, глас 8","ps":["Святі́ї безсре́бреници і чудотво́рці, Космо́ і Дамія́не, / посіті́те не́мощі на́ша: // ту́не прия́сте, ту́не даді́те нам."]},{"h":"Кондак, глас 2","ps":["Благода́ть приі́мше ісціле́ній, / простира́єте здра́віє су́щим в ну́ждах, / вра́чеве, чудотво́рці пресла́внії, / но ва́шим посіще́нієм ра́тников де́рзости низложі́те, // мир ісціля́юще чудеси́."]},{"h":"Молитва","ps":["Чудотво́рці сла́внії, вра́чеве безме́зднії, Космо́ і Дамія́не! Ви от ю́ности Христа́ Бо́га возлюби́вше і Того́ повелі́нія всім се́рдцем соблюда́ющи, а́ще і вда́сте себі́ уче́нію враче́бному, но доброді́тельнаго ра́ди житія́ і чистоти́ душе́вния, си́лою Христа́ Бо́га, не врачева́нія то́кмо іску́сство, но па́че неоску́дную благода́ть ісціле́нія вся́ких неду́гов от Бо́га прия́ли єсте́. Отоню́дуже любо́вію і милосе́рдієм к неду́гующим подвиза́ємі, не то́кмо лю́дем, но і ското́м ісціле́нія болі́зней подава́єте, неісче́тним мно́жеством чуде́с ва́ших весь мир наполня́єте, і не тіле́сния то́кмо неду́ги ісціля́єте, но і ві́рою Христо́вою ду́ші просвіща́єте, в терпі́нії болі́зней укріпля́єте, в тя́жких неду́зіх о ісправле́нії житія́ вразумля́єте і ко Христу́ покая́нієм привлека́єте. Тім же ни́ні і нас, припа́дающих к вам пред честно́ю іко́ною ва́шею, ско́ро усли́шіте, ю́ния ді́ти, ва́шей по́мощі во уче́нії кни́жном прося́щия, ва́шими моли́твами наста́віте, да ва́шему житію́ ревну́юще, не земно́є то́чію науче́ніє приобря́щуть, но па́че во благоче́стії і пра́вой ві́рі ви́ну да преуспі́ють. На одрі́ болі́зні лежа́щим, челові́чеськая по́мощі отча́янним, к вам же те́плі с ві́рою і усе́рдною моли́твою прибега́ющим, ісціле́ніє болі́зней ва́шим ми́лостивим, чудоді́йственним посіще́нієм да́руйте. Мно́гажди в болі́зні впа́дающия і от лю́тих неду́гов в уни́ніє, малоду́шіє і ропта́ніє прише́дшия, да́нною вам от Бо́га благода́тію в терпі́нії утверді́те, і наста́віте, да уразумі́ють во́лю о них Бо́жию святу́ю і благу́ю і са́мі себе́ і живо́т свой во́лі Христа́ Бо́га предаю́ть. В неду́зіх су́щих, о ісправле́нії же житія́ не радя́щих, во грісі́х не раска́ївающихся, се́рдцем ожесточе́нних сокруші́те во спасе́ніє і к покая́нію призові́те, да не́мощни су́ще ті́лом, здра́ві пребу́дуть душе́ю, і прича́стници соді́лаються Бо́жия спаси́тельния благода́ті. Бра́тію свята́го хра́ма сего́, ва́шему свято́му заступле́нію от Бо́га вруче́нную, і всіх к вам усе́рдно прибіга́ющих невреди́ми сохрані́те от долгонеду́жія, от болі́зней лю́тих і неісці́льних, от разслабле́нія ті́ла, от іступле́нія ума́, от смертоно́сной я́зви, от внеза́пний сме́рти, і всемо́щним хода́тайством ва́шим к Бо́гу соблюді́те в пра́вой ві́рі тве́рдих, во благоче́стії преспіва́ющих, в до́брих ді́лах усе́рдних, в моли́тві к Бо́гу приле́жних, да с ва́ми вку́пі сподо́б'яться в бу́дущем ві́ці при́сно воспіва́ти і сла́вити всесвято́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Давиду Гареджійському","e":"Prayer to St David of Gareja","secs":[{"h":"Тропар, глас 4","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, і бил єси́ світи́льник вселе́нній, сія́я чудеси́, Дави́де о́тче наш, моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["От сирі́йських істо́чников возше́л єси́, звіздо́ пресві́тлая, і пусти́ню Гареджійськую сія́нієм Ду́ха озари́л єси́; я́ко прише́ствієм свої́м і́ночеський рай соді́лал єси́, проізрасти́во в пусти́ні слове́сний вертогра́д. Сего́ ра́ди не оставля́й храни́ти єго́, Дави́де возлю́бленний."]},{"h":"Молитва","ps":["О, всесві́тлі, богохва́льне а́вва Дави́де, свя́тче Бо́жий! Ти си́лою блага́го Законоположи́теля яви́лся єси́ нам, ко́знями лука́ваго свя́занним і обурева́ємим, я́ко наста́вник в покая́нії і помо́щник в моли́тві. Того́ ра́ди дано́ тебі́ мно́го даро́в благода́ті і чудотворе́нія, разріше́нія гріхо́в на́ших і прегріше́ній оставле́ніє, болі́зней ісціле́ніє і дия́вольських наві́тов отгна́ніє. Ті́мже твоє́ю оте́чеською ми́лостію в богоца́рственном разумі́нії, многотру́дними моли́твами і моле́ньми твої́ми, найпа́че же непреста́нним твої́м заступле́нієм о нас, да возста́вить Госпо́дь Бог ни, во гріх впа́дшия, си́лою Своє́ю непобіди́мою на вся́каго ви́димаго і неви́димаго врага́, да́би благодаря́ще соверша́я святу́ю па́м'ять твою́, жела́нієм возжела́ли ми покланя́тися Преві́чному Бо́гу в Тро́йці Єди́ному, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Афанасію Сяндемському","e":"Prayer to St Athanasius of Syandema","secs":[{"h":"Тропар, глас 8","ps":["В тебі́, о́тче, ізві́стно спасе́ся є́же по о́бразу: / приї́м бо Крест, послі́довал єси́ Христу́, / і ді́я учи́л єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́, ве́щі безсме́ртній, // ті́мже і со А́нгели сра́дується, преподо́бне Афана́сіє, дух твой."]},{"h":"Кондак, глас 2","ps":["Чистото́ю душе́вною боже́ственне вооружи́вся, / і непреста́нния моли́тви я́ко копіє́ вручи́в крі́пко, / пробо́л єси́ бісо́вськая ополче́нія, / Афана́сіє, о́тче наш, // моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О преподо́бне і богоно́сне о́тче наш Афана́сіє, а́нгеле земни́й і челові́че небе́сний, ізря́дний уго́дниче Христо́в і Влади́чиці на́шей Богоро́диці до́брий чти́телю, всім же с ві́рою і любо́вію к тебі́ притекающим ізві́стний засту́пниче! Іспроси́ нам вся к житію́ сему́ вре́менному потре́бная і к ві́чному на́шему спасе́нію поле́зная. Посо́бствуй предста́тельством твої́м, уго́дниче Бо́жий, да в ми́рі глубо́ці пребу́деть свята́я Це́рков Христо́ва і государство Українськоє во вся́ком благоче́стії і благостроє́нії да сохрани́ться. Си́це же і всім нам, чудотво́рче святи́й, бу́ди ско́рий во вся́кой ско́рби і обстоя́нії помо́щник, найпа́че же в час кончи́ни на́шея яви́ся нам, засту́пник благосе́рдний, да не пре́дани бу́дем на мита́рствах возду́шних вла́сті злобного мироде́ржця, но да сподо́бимся непреткнове́ннаго восхо́да в Ца́рствіє Небе́сноє. Єй, о́тче, моли́твенниче наш при́сний, просія́вий заре́ю благода́ті Бо́жия, украше́ніє сий мі́ста сего́! Не преста́ни моля́ся, да ніколи́же благода́ть Бо́жия і покро́в Богома́тері от мі́ста сего́ не отсту́пить, но да сподо́бимся вку́пі с тобо́ю і со всі́ми святи́ми в селе́ніях ра́йських сла́вити вели́чіє, Благода́ть і ми́лость єдиного в Тро́йці Бо́га, Отця́, Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Афана́сіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Молитва преподобному Віталію Александрійському","e":"Prayer to St Vitalis of Alexandria","secs":[{"h":"Тропар, глас 8","ps":["В тебі́, о́тче, ізві́стно спасе́ся є́же по о́бразу приї́м бо крест послі́довал єси́ Христу́, і ді́я учи́л єси́ презира́ти у́бо плоть, прехо́дить бо: приліжа́ти же о душі́, ве́щі безсме́ртній: тім же і со А́нгели сра́дується, преподо́бне Виталіє, дух твой."]},{"h":"Кондак, глас 2","ps":["Чистото́ю душе́вною Боже́ственно вооружи́вся, і непристанния моли́тви я́ко копіє́ вручи́в крі́пко, пробо́л єси́ бісо́вськая ополче́нія Виталіє, моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Виталіє, не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х і благоприя́тних моли́твах к Бо́гу: пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя: помина́й нас недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши, не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий а́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами, у престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться, ві́дуще у́бо тя воі́стину і по сме́рті жива́ су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния муки́ да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Виталіє, і чтем святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Молитва мучениці Валентині Кесарійській","e":"Prayer to the Martyr Valentina of Caesarea","secs":[{"h":"Тропар, глас 4","ps":["А́гниця Твоя́, Ісу́се, Валенти́на зове́ть ве́ліїм гла́сом: Тебе́, Женише́ мой, люблю́, і, Тебі́ і́щущи, страда́льчествую, і сраспина́юся, і спогреба́юся Креще́нію Твоєму́, і стражду́ Тебе́ ра́ди, я́ко да ца́рствую в Тебі́, і умира́ю за Тя, да і живу́ с Тобо́ю, но я́ко же́ртву непоро́чную, прийми́ м'я, с любо́вію поже́ршуюся Тебі́. Тоя́ моли́твами, я́ко Ми́лостив, спаси́ душі́ на́ша."]},{"h":"Кондак, глас 2","ps":["Храм Твой всечестни́й я́ко цільбу́ душе́вную обрі́тше, всі ві́рнії велегла́сно вопіє́м ті, ді́во му́ченице Валентино, великоімени́тая, Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О, многострада́льная і прему́драя му́ченице Христо́ва Валентино! Ни́ні почита́юще святу́ю па́м'ять твою́, к тебі́ ми, грі́шнії і недосто́йнії, усе́рдно прибіга́єм і во умиле́нії серде́ць на́ших мо́лимся. Ти па́че всіх благ земни́х Сладча́йшаго Го́спода на́шего Ісу́са Христа́ возлюби́ла єси́ і Тому́ чрез все житіє́ ві́рно послі́довала єси́, Боже́ственною благода́тію ду́шу свою́ пита́ющи. Іспроси́ у́бо і нам у Христа́ Бо́га благода́ть просвіща́ющую нас, да є́ю осіня́ємії, во ві́рі і благоче́стії, в по́двизіх же цілому́дрія і любві́ преуспіва́ти бу́дем і Христу́ в бли́жніх Єго́ служи́ти нелі́ностно потщі́мся. Моли́ у́бо Спа́са на́шего да сподо́бит і нас стра́нствіє на́ше земно́є во вре́менем сем ві́ці непреткнове́нно соверши́ти, і в ми́рі і покая́нії житіє́ на́ше сконча́ти, да та́ко на землі́ пожи́вше, ві́чния і блаже́нния жи́зні на небесі́ сподо́бимся і та́мо с тобо́ю і со всі́ми святи́ми вку́пі восхва́лим Тро́йцю Єдиносу́щную і Неразді́льную, і воспоє́м Єди́но Божество́, Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірному князю Ігорю Чернігівському і Київському","e":"Prayer to the Right-believing Prince Igor of Chernihiv and Kyiv","secs":[{"h":"Тропар, глас 4","ps":["Наста́ днесь всечестна́я па́м'ять страстоте́рпця благові́рнаго кня́зя І́горя, / созива́ющая лю́ди в пречестни́й храм Спа́сов, / іді́же ра́достно соше́дшеся благочести́вих мно́жество / моли́твенно пра́зднують святу́ю па́м'ять твою́, / і с ві́рою взива́ють ті: / моли́ся, свя́те, страні́ Українській, гра́ду Черні́гову і всім правосла́вним христия́ном // в ми́рі і благоде́нствії спасти́ся."]},{"h":"Інший тропар, глас 4","ps":["Просвіти́вся Боже́ственним креще́нієм, / Ду́ха Свята́го світлостьми́ озаря́єм, / Єва́нгеліє Христо́во в се́рдці твоє́ восприя́л єси́ / ді́лом сло́во Си́на Бо́жия ісполня́я, благові́рний кня́же І́горе, / моли́ Всеблага́го Спаси́теля на́шего дарова́ти нам мир, і ми́лость, // і спасе́ніє душ на́ших, чту́щих честну́ю па́м'ять твою́."]},{"h":"Кондак, глас 6","ps":["Ізміни́л єси́ земна́го княже́нія сла́ву / во і́ночества о́браз смире́нний / і страда́льчеськи земно́є житіє́ сконча́в, / ни́ні на Небесі́х ра́дуєшися, / усе́рдні моля́ся // о чту́щих тя, І́горе, страда́льцев похвало́."]},{"h":"Інший кондак, глас 6","ps":["Кня́жеськую діяде́му обагри́л єси́ кро́вію твоє́ю, / Богому́дре страстоте́рпче І́горе, / за скиптр крест в ру́ку приї́м, яви́лся єси́ побідоно́сець / і же́ртву непоро́чну Влади́ці прине́сл єси́ себе́. / Я́ко бо а́гнець незло́бив от раб убіє́н бил єси́, / і ни́ні ра́дуяся предстої́ши Святі́й Тро́йці, // моли́ся спасти́ся душа́м на́шим."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, страстоте́рпче благові́рний, кня́же І́горе! Ти із мла́да Бо́га возлюби́л єси́, мудрова́нія плотська́я, честь і сла́ву кня́жеськую ні во что же вміни́л єси́ і мона́шеськаго о́браза, єще́ ю́ний лі́ти, дости́гл єси́, к Бо́гу єди́ному все́ю душе́ю твоє́ю приліпи́лся єси́, і благо́є і́го Христо́во на ся взем, путе́м спаси́тельним неукло́нно ше́ствовал єси́ да́же до сме́рти му́ченичеськия. Сего́ ра́ди вінча́ тя Госпо́дь, блаже́нне І́горе, вінце́м сла́ви і прия́т в Своя́ Небе́сния селе́нія, іді́же ти ни́ні, неізрече́нния сла́ви і ра́дости наслажда́ющеся в невече́рнім дні Ца́рствія Христо́ва, с ли́ки святи́х страстоте́рпцев і всіх святи́х Бо́га о нас умоля́єши. Мо́лимся тебі́, свя́тче Бо́жий, припа́дая к честно́му о́бразу твоєму́: моли́ся о нас грі́шних і непотре́бних, іспроси́ моли́твами твої́ми ми́ра держа́ві на́шей, гра́ду сему́ (і свято́му хра́му сему́) благода́ті і ми́лости. Це́рков святу́ю огради́ моли́твами твої́ми от єресе́й і раско́лов, па́стирем єя́ іспроси́ ре́вность і благоче́стіє, всім же нам любо́в нелицемі́рную і терпі́ніє да́руй, гріхо́в на́ших проще́ніє, болі́зней і вся́ких неду́гов ісціле́ніє. Покри́й і сохрани́ всіх нас от вся́ких бід, скорбе́й і напа́стей, да, благодаря́ще, просла́вим Святу́ю Живонача́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й благові́рний вели́кий кня́же І́горе, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва мученику Іоанну Новому, Яніньському","e":"Prayer to the Martyr John the New of Ioannina","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Іоа́нн, во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: імі́яй бо крі́пость Твою́, мучи́телей низложи́, сокруши́ і де́монов немощни́я де́рзости. Того́ моли́твами спаси́ душі́ на́ша."]},{"h":"Молитва","ps":["Святи́й му́чениче Іоа́нне! При́зри с небесного черто́га на тре́бующих твоєя́ по́мощі і не отве́ргни проше́ній на́ших, но, я́ко при́сний благоді́тель і хода́тай наш, моли́ Христа́ Бо́га, да человіколюби́в і многоми́лостив сий, сохрани́ть нас от вся́каго лю́таго обстоя́нія: от тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусобний бра́ні. Да не осу́дить нас, грі́шних, по беззако́ніям на́шим, і да не во зло обрати́м блага́я, да́руємая нам от Всеще́драго Бо́га, но во сла́ву свята́го і́мене Єго́ і в прославле́ніє крі́пкаго твоєго́ заступле́нія. Да моли́твами твої́ми дасть нам Госпо́дь мир помисло́в, воздержа́ніє от па́губних страсте́й і от вся́кия скве́рни і да укріпи́ть во всем ми́рі Свою́ Єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков, ю́же стяжа́л єсть честно́ю Своє́ю Кро́вію. Моли́ прилі́жно, святи́й му́чениче, да благослови́ть Христо́с Бог держа́ву Українськую, да утверди́ть во Святі́й Своє́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да всі у́ди єя́, чи́стії от суєму́дрія і суєві́рія, ду́хом і і́стиною покланя́ються Єму́ і усе́рдно пеку́ться о соблюде́нії за́повідей Єго́, да ми всі в ми́рі і благоче́стії поживе́м в настоя́щем ві́ці і дости́гнем блаже́нния ві́чния жи́зні на небесі́, благода́тію Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь"]},{"h":"Інша молитва","ps":["О святи́й уго́дниче Бо́жий, му́чениче Іоа́нне! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтем святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всемилостивому́ Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і по́мощі нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Симеону Верхотурському","e":"Prayer to the Righteous Simeon of Verkhoturye","secs":[{"h":"Тропар на прославлення, глас 4","ps":["Мирська́го м'яте́жа бі́гая, все жела́ніє обрати́л єси́ к Бо́гу, / да во виді́нія восхо́д обря́щеши го́ре, / отню́дуже не уклони́вся в лука́вствія се́рдця, / но очи́стив ду́шу і ті́ло, / прия́л єси́ благода́ть точи́ти цільби́ ві́рним і неві́рним, / притека́ющим к тебі́, пра́ведний Симео́не. / Ті́мже, по да́нному ті да́ру, / іспроси́ у Христа́ Бо́га ісціле́ніє нам, боля́щим душе́вними страстьми́, // і моли́ спасти́ ду́ші на́ша."]},{"h":"Інший тропар на перенесення мощей, глас 4","ps":["Днесь ра́дується сла́вная страна́ Сиби́р, / обрі́т святи́я мо́щі твоя́ внутр себі́. / Архієре́є, свяще́нници і весь сонм людськи́й / духо́вні веселя́щеся, вопіє́м ті: / о Богому́дре Симео́не! / Ізба́ви нас, і́же к тебі́ прибіга́ющих, от всіх бід, / прося́ пода́тися всім по коєго́ждо проше́нію, / і ізба́витися страні́ сей і гра́ду / от о́гненнаго запале́нія і пога́нськаго наше́ствія / і междоусо́бния бра́ні і от вся́каго зла. / Ті́мже і ми всі чтем ни́ні честни́х і многоціле́бних моще́й твої́х пренесе́ніє, / но́вий ціле́бниче, і вопіє́м: // сла́ва Даю́щему тобо́ю всім ісціле́ніє!"]},{"h":"Кондак на прославлення, глас 2","ps":["Ми́ра су́єтнаго отве́рглся єси́, / да бла́га ві́чния жи́зні наслі́диши, / возлюби́в незло́біє і чистоту́ душі́ і ті́ла. / Сниска́л єси́, є́же возлюби́л, / свиді́тельствують бо о сем гроб і нетлі́ніє моще́й твої́х, / і благода́ть чудотворе́нія найпа́че. / То́чиши бо цільби́ всім притекаю́щим к тебі́ і непросвіще́нним, / Симео́не блаже́нне, // чудотво́рче преди́вний."]},{"h":"Інший кондак на перенесення мощей, глас 4","ps":["Наста́ днесь всечестна́я па́м'ять но́ваго ціле́бника / пра́веднаго Симео́на, / созива́єть же лю́ди в пречестни́й храм свята́го Бо́жия архієре́я Никола́я, / іді́же ра́достно соше́дшеся благочести́вих мно́жества, / ве́село пра́зднують пренесе́ніє честни́х і многоціле́бних моще́й твої́х пра́здник. / Ти бо яви́лся єси́ гра́ду на́шему, і всей Сиби́ри врачевство́ безме́здноє, / подава́я ісціле́ніє с ві́рою приходя́щим к тебі́, Симео́не всеблаже́нне. / Но я́ко імі́яй дерзнове́ніє ко Влади́ці Христу́, / Того́ моли́ спасти́ град і лю́ди, моля́щіяся тебі́, / па́че же хода́тай бу́ди ко Го́споду / во дні наше́ствія печа́лі рабо́м твої́м, да зове́м ті: // ра́дуйся, Сиби́рстій страні́ похвало́ і утвержде́ніє гра́ду на́шему."]},{"h":"Молитва","ps":["О святи́й і пра́ведний Симео́не, чи́стою душе́ю твоє́ю в Небе́сних оби́теліх в ли́ці святи́х водворя́яйся, на землі́ же с на́ми неотсту́пно пребива́яй! По да́нній ті благода́ті от Го́спода моли́тися о нас, ми́лостивно при́зри на нас многогрі́шних, а́ще і недосто́йні, оба́че с ві́рою і упова́нієм к тебі́ притека́ющих, і іспроси́ нам от Бо́га проще́ніє согріше́ній на́ших, в ня́же впада́єм мно́жицею во вся дні житія́ на́шего. І я́коже пре́жде о́вим у́бо, от о́чния зі́льния болі́зні ні ма́ло зрі́ти могу́щим ісціле́ніє оче́с, о́вим же близ сме́рти би́вшим от лю́тих неду́гов врачева́ніє, і іни́м іна́я мно́гая пресла́вная благодія́нія дарова́л єси́: си́це ізба́ви і нас от неду́гов душе́вних і тіле́сних і от вся́кия ско́рби і печа́лі, і вся блага́я к настоя́щему житію́ на́шему і к ві́чному спасе́нію благопотре́бная нам от Го́спода іспроси́, да та́ко твої́м предста́тельством і моли́твами стяжа́вше вся нам поле́зная, а́ще і недосто́йнії, благода́рні восхваля́юще тя, просла́вим Бо́га, ди́внаго во святи́х Свої́х, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва блаженному Августину, єпископу Іппонійському","e":"Prayer to Blessed Augustine, Bishop of Hippo","secs":[{"h":"Тропар, глас 4","ps":["Се́рдцем всім Христу́ послі́дуя, святи́телю Августи́не, / сло́вом і ді́лом і́стину запечатлі́л єси́ / і єресе́й злочести́вих яви́лся єси́ нелі́ностний іскорени́тель, / моли́ся ви́ну ко святі́й Тро́йці, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Непоколеби́ме сто́лпе Це́ркві Вселе́нськия / на недви́жимім ка́мені ві́ри основа́нний, / догма́ть правосла́вія неле́стний учи́телю / і покая́нія велегла́сний пропові́дниче, / запечатли́телю і́стини, / прехва́льне Августи́не, // святи́телю Христо́в."]},{"h":"Молитва","ps":["О, пресла́вний Христо́в святи́телю, Вселе́нськия Це́ркві похвало́ і учи́телю богому́дрий, правосла́вія наста́вниче і покая́нія пропові́дниче, блаже́нне Августи́не! При́зри с го́рних висо́т на нас недосто́йних, і́щущих твоє́й по́мощі і милосе́рдія: умоли́ Влади́ку вся́чеських, Єму́же на землі́ всім житіє́м твої́м служи́л єси́, да да́руєть нам неукло́нноє хране́ніє неповрежде́нния пра́вия ві́ри, ю́же от Го́спода чрез ученико́в Єго́ прия́ли єсьми́, да помо́жеть запечатлева́ти ю ді́ли любві́ і милосе́рдія, і да споспі́шествуєть нам во благи́х на́ших начина́ніях; защити́ ни от зло́бних наві́т вра́жиїх і помози́ всім нам твої́м хода́тайством улучи́ти Ца́рствіє Небе́сноє, іді́же ти ни́ні в незаходи́мій сія́єши сла́ві пред лице́м Всемилосе́рднаго Бо́га в Тро́йці покланя́ємаго і сла́вимаго во вся ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святій мучениці Юлії Карфагенській","e":"Prayer to the Holy Martyr Julia of Carthage","secs":[{"ps":["О свята́я ді́во і му́ченице Іу́ліє, і́стинная неві́сто Христо́ва! К тебі́, я́ко благонаде́жней пред Го́сподем предста́тельнице на́шей усе́рдно прибіга́єм і во умиле́нії серде́ць на́ших мо́лимся: предстоя́щи у Престо́ла Пресвяти́я Тро́йці і наслажда́ющися неізрече́ннаго блаже́нства Небе́снаго, при́зри у́бо ми́лостивно на нас, принося́щих ті хвале́бноє пі́ніє сіє́, і іспроси́ у Преблага́го Го́спода дарова́ти нам душе́вноє і тіле́сноє здра́віє, во благоче́стії христия́нстім преуспі́яніє, к житію́ вре́менному ну́жная і дово́льная і вся я́же ко спасе́нію потре́бная, да ми́рно і благоче́стно пожи́вше, сподо́бимся благу́ю кончи́ну христия́нськую улучи́ти і Ца́рствіє Небе́сноє наслі́довати, сла́в'яще ди́внаго во святи́х Свої́х Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Євгенію Боткіну, страстотерпцю","e":"Prayer to the Righteous Passion-Bearer Eugene Botkin","secs":[{"h":"Молитва","ps":["Святи́й сла́вний іспові́дниче і страстоте́рпче Євге́ніє! Ві́руєм і упова́єм, я́ко страда́ньми і богоуго́дною жи́знію твоє́ю стяжа́вий ве́лію ми́лость і дерзнове́ніє у Го́спода Бо́га, не заби́л єси́ достоя́нія твоєго́ земна́го, оте́чества на́шего, в не́мже обурева́ємі єсьми́, почита́теліє твої́, мно́гими напа́стьми вра́жіїми і страстьми́ жите́йськими. Ті́мже про́сим тя: моли́твами і предста́тельством твої́м умоли́ Го́спода на́шего Ісу́са Христа́, да ізба́вить нас от вся́ких бід і злих обстоя́ній, от вся́ких неду́гов і болі́зней і от всіх враго́в, ви́димих і неви́димих. О вели́кий уго́дниче Бо́жий! Воздохни́ о нас, грі́шних, ко Влади́ці вся́чеських, да прости́ть нам вся согріше́нія на́ша і низпосле́ть на ни благода́ть Всесвята́го Ду́ха, да преста́вше вся́каго скверноді́йства, про́чеє вре́м'я живота́ на́шего во вся́ком благоче́стії і чистоті́ поживе́м і, та́ко благоугоди́вше Го́споду, сподо́бимся жи́зні вечноблаженния, пою́ще і воспіва́юще превели́коє милосе́рдіє Бо́жиє і твоє́ ми́лостивоє предста́тельство за нас у Престо́ла Бо́жия во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, пресла́вний страстоте́рпче Євге́ніє, вели́кий уго́дниче Бо́жий, принеси́ на́шу сле́зную моли́тву Го́споду Бо́гу на́шему, уми́лостиви Єго́ к нам, грі́шним, да отиметь гнів свой пра́ведний і умири́ть страну́ на́шу многострада́льную; да утверди́ть благоде́нствіє і тишину́, да низпосле́ть нам ізоби́ліє плодо́в земни́х і да возбрани́ть враго́м на́шим оби́ду твори́ти си́рим і безпомо́щним. Ті́мже, припа́дающе к іко́ні твоє́й, воспомина́єм с ві́рою страда́нія твоя́, за Христа́ претерпі́нная, і мо́лим тя: не оста́ви нас і іспроси́ нам у Го́спода блага́я вре́менная і ві́чная, да сла́вим просла́вльшаго тя Бо́га во ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["О, всесла́вний страстоте́рпче, достохва́льний уго́дниче Христо́в, Це́ркві Правосла́вния побо́рниче, новому́чениче і ціли́телю святи́й Євге́ніє! Прекло́ньше колі́на мо́лим тя: при́зри на ни, грі́шния, к заступле́нію твоєму́ прибегающия, усли́ши сіє́ ма́лоє моле́ніє на́ше і те́плим твої́м предста́тельством умоли́ Всемилосердного Бо́га, Єму́ же ни́ні предстої́ши со А́нгели і всі́ми святи́ми, да сохрани́ть нас в єдине́нії Правосла́вния Це́ркві і утверди́ть в сердця́х на́ших живи́й дух пра́вия ві́ри і благоче́стія, і ізба́вить нас от всякого іскуше́нія і пре́лести бісо́вськия. По вели́цій любві́ твоє́й, є́юже бли́жнія твоя́ возлюби́л єси́, іспроси́ у всещедрого Бо́га Оте́честву Твоєму́ (і на́шему ку́пно), мир і благоустроє́ніє; всім же нам, недосто́йним, усе́рдно к тебі́ прибегающим, богоуго́дноє і безм'яте́жноє житіє́ і до́брую христия́нськую кончи́ну, тайн Бо́жиїх причастною. О, святи́й засту́пниче наш не оста́ви нас, сла́бих і безпомо́щних, мо́лимся за ни ко Го́споду і Спа́су На́шему Ісу́су Христу́, да да́руєть Он, Всеще́дрий і Премилосердний Госпо́дь наш, вся, я́же к по́льзі вре́менній і ві́чній поле́зная і потре́бная; да не возда́сть нам по ді́лом на́шим, но по неізрече́нному человіколю́бію своєму́ прости́ть нам гріхи́ і согріше́нія на́ша, да ізба́в'ять ни от вся́кия ну́жди і печа́лі, ско́рби і болі́зні; да ниспо́шлеть нам благо́є намі́реніє і си́лу подвиза́тися во ісправле́нії житія́ на́шего, і в бу́дущем ві́ці да сподо́бит нас вни́ти в Ца́рствіє Небе́сноє і сла́вити ку́пно с тобо́ю Всесвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Саві, ігумену Сторожевському, Звенигородському","e":"Prayer to St Sabbas, Abbot of Storozhi, Zvenigorod","secs":[{"h":"Тропар, глас 8","ps":["Пусти́ні яви́лся єси́ до́броє прозябе́ніє, преподо́бне: / от ю́ности бо ізво́лил єси́ чи́стоє житіє́, / духо́вному твоєму́ учи́телю послі́дуя, / і Того́ уче́нієм ум к Небе́сним впери́в, / і ста́ду твоєму́ прему́др наста́вник показа́лся єси́; / тім і Христо́с, я́ко пресві́тла тя світи́льника, чудеси́ обогати́. // Са́вво о́тче наш, моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 8","ps":["От ю́ности боже́ственною распаля́єм ре́вностію, возлюби́л єси́ чи́стоє житіє́, презрі́в ми́ра сего́ кра́сная і су́єтная, послі́довал єси́ твоєму́ Богому́дрому учи́телю, преблаже́нному Се́ргію, в труді́ і бді́нії, в пості́ і по́двизі: на Сторо́жи я́влься безмо́лвія ра́ди і стра́жи духо́вния, недре́мленним на Боже́ственній стра́жі предстоя́нієм стяжа́л єси́ ум, зряй к Бо́гу, і де́монськия ко́зні і обстоя́нія прозира́яй: озаре́ніє Пресвята́го Ду́ха в себі́ восприє́м, я́ко звізда́ пресві́тлая возсія́л єси́ ві́рним. Ті́мже і прему́др і світоза́рен предстоя́тель і па́стир ста́ду твоєму́ яви́лся єси́, сві́том твої́м просвіща́яй і всіх, приходя́щих тебі́ ві́рою, о́тче наш Са́вво, і моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Госпо́днім жела́нієм распали́вся, / стра́сті плотські́я воздержа́нієм оттря́с, / Боже́ственнаго сві́та незаходи́моє світи́ло яви́лся єси́, / чуде́с луча́ми всіх просвіща́єши / притека́ющих к моще́м твої́м, // Са́вво, преподо́бне о́тче наш."]},{"h":"Молитва","ps":["О пречестна́я і свяще́нная главо́! Небе́снаго Ієрусали́ма граждани́не, Пресвяти́я Тро́йці обита́лище, преподо́бне о́тче Са́вво! Ве́ліє імі́я дерзнове́ніє ко Всеми́лостивому Влади́ці, моли́ся о ста́ді огра́ди твоєя́ і о всіх по ду́ху ча́діх твої́х. Не премолчи́ за ни ко Го́споду і не пре́зри ві́рою і любо́вію чту́щих тя. Іспроси́ предста́тельством твої́м у Царя́ ца́рствующих мир Це́ркві, под зна́менієм креста́ во́їнствующей, архієре́ом святи́тельства благолі́піє, мона́шествующим до́броє в по́двизіх тече́ніє; святі́й оби́телі сей, гра́ду сему́ і всім градо́м і стра́нам охране́ніє; ми́ру безм'яте́жіє і мир, гла́да і па́губи ізбавле́ніє; ста́рим і немощни́м утіше́ніє і подкріпле́ніє, ю́ним і младе́нцям благо́є во ві́рі возраста́ніє, в Єва́нгельськом уче́нії тве́рдоє обуче́ніє, і в чистоті́ і цілому́дрії пребива́ніє; вдови́цям і сирота́м ми́лость і заступле́ніє, пліне́нним отра́ду і возвраще́ніє, боля́щим ісціле́ніє, малоду́шним успокоє́ніє, заблу́ждшим ісправле́ніє, согреша́ющим дух сокруше́нія, бе́дствующим благовре́менну по́мощ. Не посрами́ нас, к тебі́ с ві́рою притека́ющих, споспі́шествуй, я́ко чадолюби́вий оте́ць ча́дам, і нам понести́ і́го Христо́во во благоду́шії і терпі́нії, і всіх упра́ви в ми́рі і покая́нії сконча́ти живо́т свой непости́дно і пресели́тися со упова́нієм во оби́телі Небе́сния. Іді́же ти, по труді́х і по́двизіх, ни́ні водворя́єшися со А́нгели і Святи́ми, зря і прославля́я Бо́га, в Тро́йці сла́вимаго, Отця́, і Си́на, і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Йоні (у схимі Петру) Київському","e":"Prayer to St Jonah (in the schema Peter) of Kyiv","secs":[{"h":"Тропар, глас 4","ps":["Я́ко лучеза́рноє со́лнце / от коне́ць землі́ возсія́вшеє, / яви́лся єси́ напослі́док дній, / тезоімени́тому проро́ку подо́б'яся во є́же воздви́гнути лю́ди к покая́нію. / Ті́мже і Сама́ Пречи́стая с со́нмом святи́х тебі́ мно́гажди яви́шася, / Єя́же повелі́нієм создана́ бисть оби́тель во і́м'я Живонача́льния Тро́йці. / К Не́йже імі́я дерзнове́ніє, / моли́, преподо́бне о́тче наш Іо́но, // пода́ти нам ми́лость і оставле́ніє гріхо́во в день су́дний."]},{"h":"Тропар, глас 4 (на перенесення мощей)","ps":["Днесь пресві́тло красу́ється сто́льний град Ки́єв, / я́ко світолу́чними заря́ми, мо́лніями чуде́с твої́х осія́єм, / всю вселе́нную созива́єть похвали́ти тя, Богому́дре Іо́но; / пречестна́я же сла́вная оби́тель твоя́, / ю́же во І́м'я Святи́я Тро́йці мно́гими труди́ твої́ми созда́л єси́, о́тче, / іму́щи в себі́ ста́да учени́к твої́х, весе́лія і ра́дости ісполня́ється. / Ми же, пра́зднующе пресла́вноє обрі́теніє честни́х моще́й твої́х, / в землі́ сокрове́нних, я́ко цвіт благоуха́нен і кади́ло благово́нно, / любе́зно я лобиза́юще, разли́чная ісціле́нія приє́млем / і твої́ми моли́твами гріхо́в проще́нія сподобля́ємся, / о́тче преподо́бне Іо́но, // моли́ Святу́ю Тро́йцю спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Чистото́ю душе́вною боже́ственно вооружи́вся, / і непреста́нния моли́тви я́ко копіє́ вручи́в крі́пко, / пробо́л єси́ бісо́вськая ополче́нія Іо́но о́тче наш. // Моли́ непреста́нно о всіх нас."]},{"h":"Кондак, глас 8 (на перенесення мощей)","ps":["Наслі́дник отце́в бил єси́, преподо́бне, / тіх послі́дуя житію́ і уче́нію, оби́чаю і воздержа́нію, / моли́тві же і предстоя́нію. / С ни́миже, імі́я дерзнове́ніє ко Го́споду, / проще́ніє согріше́ній і спасе́ніє іспроси́ // вопію́щим ті: ра́дуйся, о́тче Іо́но."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Іо́но!","Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу.","Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя.","Помина́й нас, недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со А́нгельськими во́їнстви, со Безпло́тними ли́ки, с Небе́сними си́лами у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться.","Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас всеси́льному Бо́гу о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми Пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Митрофану, єпископу Воронезькому","e":"Prayer to St Mitrophan, Bishop of Voronezh","secs":[{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / сло́вом і житіє́м, па́стві твоє́й, о́тче смиренному́дре Митрофа́не, бил єси́. / Ті́мже і во сві́тлостіх святи́х, / со́лнця світлі́йше возсія́л єси́, / вінце́м нетлі́нія і сла́ви украша́єм, / моли́ Христа́ Бо́га, // страні́ на́шей і гра́ду твоєму́ в ми́рі спасти́ся."]},{"h":"Кондак, глас 8","ps":["Воздержа́нієм ті́ло ду́ху порабо́тив, / ду́шу же равноа́нгельну сотвори́в, / святи́тельською оді́ялся єси́ оде́ждою, я́ко віне́ць свяще́нства, / і ни́ні, всіх Влади́ці предстоя́, // моли́, всеблаже́нне Митрофа́не, умири́ти і спасти́ ду́ші на́ша."]},{"h":"Молитва перша","ps":["О святи́телю о́тче Митрофа́не, се ми грі́шнії, нетлі́нієм честни́х моще́й твої́х і мно́гими благодія́ньми, чуде́сно соді́янними і содіва́ємими тобо́ю, уві́рившеся, іспові́дуєм, я́ко і́маши ве́лію благода́ть у Го́спода Бо́га на́шего, і всесмире́нно ко твоєму́ благосе́рдію припа́дающе, тебі́ мо́лимся си́це: моли́ о нас Христа́ Бо́га на́шего, да низпосле́ть всім чту́щим святу́ю па́м'ять твою́ і усе́рдно к тебі́ прибега́ющим бога́тия ми́лости Своя́; да утверди́ть во святі́й Своє́й Правосла́вной Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, дух ві́дінія і любве́, дух ми́ра і ра́дости о Ду́сі Свя́те, да вся ча́да єя́, чи́ста су́ща от мирськи́х іскуше́ній і плотськи́х по́хотей і зла́го ді́йствія злих духо́в, ду́хом і і́стиною покланя́ються Єму́, і усе́рдно о соблюде́нії за́повідей Єго́ ко спасе́нію душ свої́х да потща́ться. Па́стирем єя́ да дасть Госпо́дь святу́ю ре́вность попече́нія о спасе́нії люде́й, во є́же неві́рующія просвіти́ти, неве́дущия наста́вити, сомня́щіяся вразуми́ти, отпа́дшия от Правосла́вния Це́ркве к ней возврати́ти, ве́рующия во ві́рі соблюсти́, грі́шния на покая́ніє подви́гнути, ка́ющіяся уті́шити і во ісправле́нії жи́зні утверди́ти, і та́ко вся лю́ди ко угото́ванному ві́чному Ца́рству святи́х Єго́ привести́. Умоли́ Го́спода, уго́дниче Христо́в: ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболе́зенний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш. Всім же в держа́ві лю́дем да да́руєть благи́й Бог наш мир, тишину́, безм'яте́жіє і ізоби́ліє плодо́в земни́х, па́че же ко ісполне́нію за́повідей Єго́ тща́ніє нелі́ностноє; і да ізба́вить ца́рствующия гра́ди, град сей і вся іни́я гра́ди і ве́сі, от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних, междоусо́бния бра́ні, смертоно́сния я́зви і от вся́каго зла. Єй, святи́телю Бо́жий, да устро́їши моли́твами твої́ми вся блага́я душа́м і тілесе́м на́шим; да і ми просла́вим в душа́х і тілесі́х на́ших Го́спода і Бо́га на́шего, Ісу́са Христа́, Єму́же со Отце́м і Святи́м Ду́хом сла́ва і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́телю о́тче Митрофа́не! Прийми́ сіє́ ма́лоє моле́ніє от нас, грі́шних раб Бо́жиїх (імена́), к тебі́ прибіга́ющих, і те́плим твої́м предста́тельством умоли́ Го́спода і Бо́га на́шего, Ісу́са Христа́, я́ко да пода́сть нам согріше́ній на́ших проще́ніє і ізба́вить нас от бід, печа́лей, ско́рби і болі́зней душе́вних і тіле́сних, обдержа́щих нас; да пода́сть вся на по́льзу настоя́щаго житія́ на́шего потре́бная; да да́руєть нам сконча́ти житіє́ сіє́ привре́менноє в покая́нії і да сподо́бит нас, грі́шних і недосто́йних, Небе́снаго Ца́рствія Своєго́, во є́же со всі́ми святи́ми сла́вити Єго́ безконе́чноє милосе́рдіє, со Безнача́льним Єго́ Отце́м і Святи́м і Животворя́щим Єго́ Ду́хом, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва блаженній Валентині Мінській","e":"Prayer to Blessed Valentina of Minsk","secs":[{"ps":["О блаже́нная ма́ти на́ша Валентино! Я́коже і во дні земни́я жи́зні твоєя́, с любо́вію принимала єси́ всіх стра́ждущих і немощству́ющих, всіх в ско́рбіх і болі́зніх су́щих, і моли́твами твої́ми целила неду́ги їх. Та́кожде і ни́ні всім, с ві́рою і умиле́нієм приходящим к тебі́, у Го́спода ісціле́нія іспроси́, найпа́че же от паде́ній гріхо́вних сохрани́ і на путь спасе́нія наста́ви. Усли́ши нас недосто́йних, блаже́нная Валентино, і принеси́ на́ша моле́нія ко Престо́лу Всеви́шняго, да с ра́достію восхва́лим Пресвяту́ю Тро́йцю: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірному великому князю Андрію Боголюбському","e":"Prayer to the Right-believing Grand Prince Andrei Bogolyubsky","secs":[{"h":"Тропар, глас 8","ps":["Я́ко благове́рен і пра́веден, / за любо́в Христа́ Бо́га от свої́х смерть прия́л єси́, / кров свою́ пролія́в, / я́коже пре́жде сро́дниці твої́ і страстоте́рпці Бори́с і Гліб, / ї́хже кро́вем совопіє́ть і твоя́ кров, свя́те, к Бо́гу, / я́коже А́веля і Заха́рії пра́ведних, / благові́рний страстоте́рпче, вели́кий кня́же Андре́є, / с ни́миже Христа́ Бо́га моли́ о страні́ на́шей, є́же Богоуго́дній би́ти // і синово́м українським спасти́ся."]},{"h":"Інший тропар, глас 3","ps":["Є́же во пло́ті житію́ твоєму́ удиви́шася а́нгельстії чи́ни: / ка́ко с ті́лом к неви́димим сплете́нієм ізше́л єси́, пресла́вне, / і уязви́л єси́ де́монськия полки́. / Отону́дуже, Андре́є, Христо́с тебі́ воздаде́ бога́тими дарова́ньми: // сего́ ра́ди, о́тче, моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["В ми́рі сем благоче́стно і пра́ведно пожи́в, / моли́твою, ми́лостинею і благострада́нієм Бо́гу угоди́л єси́, / сего́ ра́ди і Бог по убіє́нії твоє́м просла́ви тя нетлі́нієм і чудеси́, / Єго́же, свя́те Андре́є, моли́ сохрани́ти оте́чество твоє́ // і всіх люде́й, благоче́стно тебі́ почита́ющих."]},{"h":"Інший кондак, глас 8","ps":["Родочисленний Ца́рства Українськаго наслі́дниче, от благочести́ваго корня кня́зя Ю́рія плодитель первоначальствующих Українських Самоде́ржцев, Боголю́бче кня́же Андре́є, му́жество і ум в себі́ нося́щий, в пра́вді і і́стині пред Бо́гом ходя́щий, о, ве́лій єдинодержавний основа́телю госуда́рства но́ваго, моли́ся, да Бі́лая Русь многолюдством правосла́внаго ро́да умно́житься, і сві́том Христо́вим всему́ ми́ру ди́вно яви́ться, і сла́вою Бо́жієй возвели́читься."]},{"h":"Молитва","ps":["О, святи́й благові́рний вели́кий кня́же Боголю́бський Андре́є! Ра́бе Бо́жий ві́рний і Богославний, христия́нине істовий і Богоревнивий, му́же доброді́тельний і Богому́дрий, во́їне всечестни́й і воєво́до доброхва́льний, прави́телю держа́вний і дерзнове́нний! Україну Святую на уде́ли і кня́жества разобщенную, Бо́жиїм хоті́нієм хотя́щий во єди́ноє Українськоє Ца́рствіє собра́ти і єдинодержавно Є́ю пра́вити, да непреобори́ма пребу́деть от всіх враг ви́димих і неви́димих, возстаю́щих на правосла́вния христия́ни. Да не тще́тни бу́дуть твої́ святі́ї дія́нія во сла́ву і честь Бо́га Христия́нськаго, іді́же твоє́ Богосві́тлоє строє́ніє Бо́гом люби́маго Ца́рства Правосла́внаго на Українськой Земле́ зрим і велича́єм, єгда́ сто́льний град Влади́мир і Боголюби́вую оби́тель Пресвяті́й Богоро́дице воздви́гнувий, іді́же ти в ней посреди́ но́щі неповинне злочестивими і клятвопреступними свої́ми слуга́ми взя́тий і от рук їх беззако́нно і жесточа́йшими меча́ми убіє́нний, і честно́ю кро́вію своє́ю істекаємий, тве́рдоє основа́ніє Єдинодержавію Правосла́вной Русі́ та́ко положи́вий. І ни́ні ми, грешниє раби́ Бо́жії (імена́), в Богомощноі небе́сноє предста́тельство твоє́ ві́руєм, і́бо му́ченичеським вінце́м житіє́ твоє́ запечатлевшеє, мо́лим тя, да ізба́вить нас Госпо́дь от крамоли́ слуг антихристових і от кровавих жертвоприношеній і жидо́вських оби́чаєв, і да спасе́ться Земля́ Українськая от і́га сатани́нськаго, і́бо імі́єм тя, вели́каго уго́дника Бо́жия, неустрашимаго ра́тника Христо́ва, єгда́ на поля́х земно́й бра́ні со мно́гими врага́ми за Ві́ру святу́ю і Оте́чество сражавийся, і столь ди́вную сла́ву Бо́жиїх побі́д всей Українськой Земле́ показу́ющий. І ти, я́ко держа́вний воєво́до і святи́й му́ченик, і всегда́ дерзнове́нний о нас моли́твенник, Боголюби́вий і неуста́нний созидателю Свято́й Русі́, во святи́х мощах ди́вно просла́вленний, і в по́мощ і в заступле́ніє нам оста́вленний, возста́ни за нас проти́ву іноплеме́нних, чужеземних і зловрі́дних супоста́ть, і противоста́ни їм со мнозими святими князьями-воїнами, і пе́рвіє со святим равноапо́стольним вели́ким князе́м Влади́миром і свято́й равноапостольной вели́кой княгиней Ольгой, і с вели́кими благові́рними князьями первомучениками-страстотерпцями Бори́сом і Глі́бом, і со святи́м во́їном преподобному́чеником Ігорем Черни́говським, і святи́м благові́рним вели́ким князе́м Георгиєм Всеволодовичем Владимирським, вку́пі же і с Богосві́тлими сина́ми твої́ми князьями-му́чениками Глі́бом Владимирським і храбрим Ізяславом, да їх по́мощію не позиблем пребу́деть Дом Пресвяти́я Богоро́диці, всей Русі́ Держа́вной Влади́чиці, і да просла́виться і просія́єть тобо́ю, кня́же Андре́є, во вся ві́ки Земля́ Українськая і напо́лниться благочести́вим христия́нським ро́дом по благослове́нію Богоро́диці, і Благода́тію Єя́ многочудотворних іко́н Влади́мирськой і Боголю́бськой, і па́ки угобзиться і укріпи́ться сла́ва Русі́ Правосла́вной, і просія́єть Невеще́ственним і Животво́рним сві́том Бо́га Отця́, Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий святи́й кня́же Андре́є, великому́чениче і страстоте́рпче, ти па́че мно́гих іни́х соплеменников ро́да твоєго́ за благоче́стіє і Богопочита́ніє твоє́ возлю́блен бисть Богоро́дицею, і пред Ней непреста́нно хода́тайствуєши о вели́чії і сла́ві Свято́й Русі́. Моли́ся крі́пці о нас грі́шних раба́х Бо́жиїх (імена́), і о всіх правосла́вних ча́дах Землі́ Українськой, і я́коже Богому́дрий оте́ць і Держа́вний воєво́до прему́дро возрасти́вший в стра́сі Бо́жиєм і ві́рі Христо́вій синовей свої́х, соді́лав їх храбрими воїнами проти́ву супоста́тов, іді́же увенчанниє злати́ми му́ченичеськими вінця́ми на небесі́х сві́тло Престо́лу Бо́га Жи́зні вку́пі с тобо́ю ни́ні предстоя́ть, поуча́яй та́кожде і нас. Помога́я нам би́ти досто́йними воїнами христо́вими, і а́біє собери́ нас разрозненних воєди́но, я́коже собира́л єси́ вірнопо́дданних свої́х і лю́б'ящих тя во єди́ноє Христо́во ста́до, і́же тя в земно́м житії́ твоє́м всі я́коже отця́ своєго́ Держа́внаго почита́ху, та́ко і ми, чтим тя, я́ко небе́снаго на́шего покрови́теля і Боголюби́ваго кня́зя, і всегда́ прославля́єм і велича́єм тя. Помоли́ся ко Пресвяті́й Тро́йце і к Ма́тері Бо́жієй, да сотвори́ть Госпо́дь нас нелицемерними, а Бо́гу преданними ча́дами Свято́й Русі́, да і ми в правосла́вній ві́рі сохрани́м вели́коє наслі́діє Боголюбимой оби́телі Пресвято́й Богоро́диці, Єя́ же, я́ко ве́лій дар нам Бог оста́ви. І я́коже ти, мно́зі хра́ми Бо́гу Христу́ воздви́гнувий, в них же мно́житься си́ла і сла́ва Ца́рства Божего, та́ко воздви́гни і нас от грехолюбія к благочести́вому боголюби́вому житію́. Ми же моля́щієся грі́шнії раби́ Бо́жії (імена́), смире́нно про́сим твоєго́ предста́тельства і небе́сния по́мощі: ві́ри правосла́вния укрепле́нія, люби́ к Бо́гу і бли́жнім соверше́ннаго достиже́нія. Іспроси́ нам та́кожде, святи́й вели́кий кня́же, от Го́спода Вседержи́теля, да пошлеть Спаси́тель Госпо́дь пребогатиє земниє і небесниє щедро́ти і ми́лости всім обездоленним і во греха́х погиба́ющим душа́м і всему́ Оте́честву вели́каго Ца́рства Українськаго, да возсія́єть повсю́ду ві́ра Бо́жия правосла́вная, да пода́сть Госпо́дь всім заблудшим лю́дем: ві́ри Христо́вой приобще́ніє, душа́м прозрі́ніє, покая́ніє і отпуще́ніє мно́гих і тя́жких гріхо́в: клятвопреступле́нія, преда́тельства, человікоуби́йства, царененавистничества, братоубийства і вся́каго ро́да злоді́йства, іді́же пребива́єть в наро́ді Русі́ не просвященной Бо́гом Христо́м. Да істо́ргнеть Госпо́дь Іскупи́тель гріхи́ на́ші українськії із всей на́шей жи́зні, я́ко зло́є зе́ліє, а нас всіх чту́щих тя і лю́б'ящих Бо́га і Богоро́дицю і всіх українських царе́й, да спасе́ть Человіколюби́вий Госпо́дь Ісу́с Христо́с із рук враго́в на́ших, і посе́м возста́вить нам Богому́драго прави́теля Госуда́ря Самоде́ржця, пома́заннаго Ду́хом Святи́м по му́жеству і добро́ті тебі́ подо́бнаго, і́же возмо́гл би в ду́хі пра́вом, в чистоті́ і свя́тості ві́ру Христо́ву в лю́діх возроди́ти, умно́жити і удержа́ти, і упрочити Бо́гом возлю́бленноє Оте́чество Українськоє, і к Небе́сному Оте́честву нас провожда́ти всіх, я́ко свої́х вірнопо́дданних, велегла́сно прославля́ющих тя, кня́же Андре́є, во сла́ві Невече́рняго Огнезра́чнаго Сві́та, Предстоя́щаго і сла́в'ящаго в со́нмі святи́х Бо́га Отця́, Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, святи́й благові́рний вели́кий кня́же Андре́є! Страстоте́рпче і му́чениче! Слуго́ Бо́жий ві́рний і Богославний, христия́нине істовий і Богоревнивий, му́же любодобродетельний і Богому́дрий, во́їне всечестни́й і воєво́до доброхва́льний, монарше Богоізбра́нний і Боголюбимий, прави́телю держа́вний і дерзнове́нний! Україну Святую, на уде́ли і кня́жества разобщенную, хоті́вий во єди́но ца́рствіє собра́ти і єдинодержавно є́ю пра́вити, да непреобори́ма от враг і́стиннаго христия́нства пребу́деть; за сі́ї дія́нія во сла́ву і честь Бо́га Християнського убіє́нний і кро́вію своє́ю основа́ніє Русі́ Свято́й с про́чими кня́зі-му́ченики укрепивший, да во вік нези́блема пребу́деть; даровавший Русі́ многочудния іко́ни Богома́тері і То́ю па́че мно́гих іни́х за Благоче́стіє і Богопочита́ніє возлю́бленний. Синовей возрасти́вший, і́же тя, отця́ земна́го своєго́, житіє́м свої́м і Отця́ Небе́снаго кончи́ною своє́ю просла́виша. Оби́тель Боголюби́вую основа́вий і мно́зі хра́ми воздви́гнувий, в них же досе́лі моля́щеся ми, грі́шнії, про́сим твоєго́ предста́тельства і Небе́сния по́мощі; іспроси́, свя́те Андре́є, у Го́спода Вседержи́теля ми́лости бога́тия обездоленному ца́рствію українському і отпуще́нія мно́гих і тя́жких гріхо́в народам христия́нським, да да́руєть Спаси́тель нам прави́теля тебі́ подо́бнаго, і́же возмо́гл би возроди́ти Оте́чествіє на́ше земно́є і ко Оте́чествію Небе́сному привести́ нас, іді́же ти ни́ні, кня́же, во сла́ві Невече́рняго Сві́та предстоя́ со всі́ми святи́ми, восхвалявши в Тро́йці сла́вимаго Бо́га Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["О, вели́кий Український кня́же, Боголю́бський Андре́є! За ві́ру Бо́жию і сла́ву Оте́чества Правосла́внаго Українськаго оклеветанний і пре́данний слуга́ми лука́вими і людьми́ вражими, но Христо́м Бо́гом просла́вленний і христия́нами правосла́вними вельми́ почита́ємий, не оста́ви предста́тельствовати за нас пред Богоро́дицею і Спа́сом Ми́ра, не преста́ни заступа́ти за наро́д христия́нський і Зе́млю Українськую, возревну́й і защити́ і спаси́ от поруга́ній і расхищеній святи́ні хра́мов Бо́жиїх і огради́ от наві́тов вра́жиїх і от люде́й злих святу́ю оби́тель іко́ни Боголюби́вой, вступись за Україну Святую і Дом Пресвяти́я Богоро́диці, погуби́ путь беззако́нних і́щущих разделе́ній і неправедной ку́пли і прода́жи Землі́ Українськой. Моли́ся спасти́ся нам во ві́рі Христо́вой, і іспроси́ нам от Бо́га воєво́ди Небе́снаго, да пода́сть нам духовниє си́ли і му́дрость противоста́ти дия́волу і ко́знем єго́, да укріпи́ть нас би́ти безстрашними іспові́дниками і́мені христия́нськаго: я́ко пред си́льними ми́ра сего́, та́ко і пред всі́ми нечести́вими, і пред лице́м анти́христа, і пред всім ца́рством інове́рним. Сподо́би нам би́ти не то́кмо досто́йними христия́нами, но і би́ти досто́йними наслі́дниками Богоспасаємой Держа́ви Українськой. Но па́че подвиза́й би́ти нам ві́рними і благослове́нними дітьми́ Бо́жиїми.","Іспроси́ нам от Го́спода: люби́ Бо́жієй, си́ли Свято́й і му́дрості і крі́пости духо́вной, да неуста́нно бу́дем ревнова́ти о умноженії Сла́ви Оте́чества Українськаго, і да нави́кнем іску́сно владі́ти мече́м духо́вним, моли́тви святи́є непрестанниє в се́рдці своє́м нося́, і помога́й нам та́кожде на вся́кий час бдити і храни́ти вві́ренноє нам і Бо́гом да́нноє ору́жіє проти́во враго́в Бо́жиїх і всіх ізвергов ро́да челові́ча. І́бо ми земнородниє, ча́сто бива́єм маломощни і неразу́мни, но тобо́ю водимиє, мудриє і сильниє, єгда́ ча́єм с по́мощію твоє́ю ско́ро дости́гнути Ца́рства Божего в Українськой Земле́ і посе́м со дерзнове́нієм прейти́ в Ца́рствіє Небе́сноє і ві́чноє, при́сно с тобо́ю велегла́сно воспіва́я Бо́га Отця́, Бо́га Си́на і Бо́га Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Павлу Препростому","e":"Prayer to St Paul the Simple","secs":[{"h":"Тропар, глас 8","ps":["В тебі́, о́тче, ізві́стно спасе́ся, є́же по о́бразу: / приї́м бо Крест, послі́довал єси́ Христу́, / і ді́я учи́л єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́, ве́щі безсме́ртній. // Ті́мже і со А́нгели сра́дується, преподо́бне Па́вле, дух твой."]},{"h":"Молитва","ps":["О, свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Па́вле! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х і благоприя́тних моли́твах к Бо́гу: пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя: помина́й нас недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши, не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с Небе́сними си́лами, у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться, ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва священномученику Іоанну (Поммеру), архієпископу Ризькому","e":"Prayer to the Hieromartyr John (Pommer), Archbishop of Riga","secs":[{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д, / сего́ ра́ди сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Іоа́нне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Во святи́теліх благоче́стно пожи́в, / і муче́нія путь проше́д, / і́дольськия угаси́л єси́ же́ртви, / і побо́рник бив твоєму́ ста́ду Богому́дре. / Ті́мже тя почита́юще та́йно вопіє́м ті: / от бід ізба́ви ни при́сно твої́ми моли́твами, // о́тче наш Іоа́нне."]},{"h":"Молитва","ps":["О, всеблаже́нне святи́й священному́чениче святи́телю о́тче наш Іоа́нне, пра́вди Бо́жия побо́рниче і святи́я правосла́вния ві́ри Христо́вой защи́тниче, хули́телей Святи́я Це́ркве обличи́телю, враго́в прогони́телю, оби́димим покрови́телю і всіх ві́рних христия́н те́плий предста́телю. Ти все́ю душе́ю от ю́ности за́повіді Христо́ви возлюби́л єси́. І во дні гоне́нія лю́таго на ві́ру Правосла́вную, я́ко і́стинний па́стир яви́лся єси́, кре́стний путь проше́д: поруга́ніє, заточе́ніє, оклевета́ніє претерпі́вий і та́ко му́ченичеський віне́ць восприя́л єси́, обрі́тши благода́ть Го́споду моли́тися за ни. Ві́ми, я́ко ти, предстоя́ Престо́лу Вседержи́теля, і́маши ве́ліє дерзнове́ніє в моли́твах пред Го́сподем. І ни́ні смире́нно припа́даєм і усе́рдно мо́лимся: о, ско́рий засту́пниче наш, святи́телю священному́чениче о́тче Іоа́нне, усли́ши нас грі́шних і недосто́йних чад твої́х: умоли́ Всеми́лостиваго Го́спода і Пречи́стую Єго́ Ма́тер Пресвяту́ю Богоро́дицю ві́ру правосла́вную соблюсти́, Святу́ю на́шу Це́рков укріпи́ти в єди́нстві ми́ра і любві́, отпа́дшия от Святи́я Це́ркве па́ки возврати́ти, страну́ на́шу Латві́йськую в ми́рі, христия́нських доброді́теліх і благоде́нствії сохрани́ти. Помози́ нам і ра́зум наш пита́ти не су́єтною му́дростію челові́чеською, но смире́нним позна́нієм во́лі Бо́жия. О, святи́й уго́дниче Бо́жий, не пре́зри нас моля́щихся тебі́: не то́кмо от бід і скорбе́й ізбавле́нія про́сим, но си́ли і тве́рдости, великоду́шія і любве́, даби́ претерпі́ти о́ния напа́сти возстаю́щия на ни. Іспроси́ нам неосла́бноє терпі́ніє до конця́ житія́ на́шего, мир с Го́сподем і гріхо́в на́ших проще́ніє. Єй, святи́й священному́чениче, моли́ Го́спода Бо́га і Спа́са на́шего Ісу́са Христа́ Си́на Бо́жия ізба́витися нам от вся́каго зла і сохрани́ти храм сей, і град, і страну́ на́шу, і лю́ди благоче́стно чту́щия тя от вся́кия напа́сти, от болі́зней, гла́да, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от клевети́ і вся́каго зла́го обстоя́нія. Моли́твами твої́ми святи́ми разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния вразуми́, младе́нці воспита́й і всіх нас с любо́вію почита́ющих тя утверди́, да пребу́дем в любве́ друг ко дру́гу, єдиноми́сленно іспові́дуя Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, і та́ко да сподо́бимся Небе́снаго Ца́рствія, іді́же сла́виться Пречестно́є і Великолі́поє І́м'я Пресвято́й і Живонача́льной і Неразді́льній Тро́йці. Амі́нь."]}],"notes":[]},{"u":"Молитва великомучениці Парасковії, нареченій П’ятниця","e":"Prayer to the Great Martyr Paraskeva, called Friday","secs":[{"h":"Тропар, глас 4","ps":["Прему́драя і всехва́льная Христо́ва му́чениця Параске́ва, / му́жеськую крі́пость приї́мши, / же́нськую же не́мощ отве́ргши, / дия́вола побіди́ і мучи́теля посрами́, / вопію́щи і глаго́лющи: / прийді́те, ті́ло моє́ мече́м ссіци́те і огне́м сожги́те, / аз бо, ра́дующися, іду́ ко Христу́, Жениху́ моєму́. / Тоя́ моли́твами, Христе́ Бо́же, // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 8","ps":["І́же ві́руя і му́жеством душе́вним, тезоімени́тне, / дия́вола посрами́ла єси́ / і мучи́тельськоє преще́ніє і ра́ни до́блественне побіди́ла єси́, / му́ченице Параске́во, вопія́: / мече́м сосеця́йте і огне́м сожиза́йте ті́ло моє́, / я́ко да, ра́дуюся, прийду́ Жениху́ моєму́ Христу́ Бо́гу. // Єго́же моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Всесвято́є і непоро́чноє муче́ніє прине́сши, / я́ко ві́но пречестно́є, безсме́ртному Жениху́ Христу́, / А́нгельськоє ликостоя́ніє возвесели́ла єси́ / і побіди́ла єси́ де́монськия ко́зні. / Сего́ ра́ди тя че́стно ві́рою чтим, // му́ченице Параске́во многострада́льная."]},{"h":"Молитва перша","ps":["О свята́я і преблаже́нная му́ченице Христо́ва Параске́во, красото́ діви́чеськая, му́чеников похвало́, чистоти́ о́бразе, великоду́шних зерца́ло, прему́дрих удивле́ніє, ві́ри христия́нськия храни́тельнице, і́дольськия льсти обличи́тельнице, Єва́нгелія Боже́ственнаго побо́рнице, за́повідей Госпо́дніх ревни́тельнице, сподо́бльшаяся прийти́ ко приста́нищу ві́чнаго поко́я і в черто́зі Жениха́ твоєго́ Христа́ Бо́га сві́тло веселя́щаяся, сугу́бим вінце́м ді́вства і му́ченичества украше́нная! Мо́лим тя, свята́я му́ченице, бу́ди о нас печа́льниця ко Христу́ Бо́гу, Єго́же преблаже́ннійшим зрі́нієм при́сно весели́тися; моли́ Всеми́лостиваго, і́же сло́вом о́чі сліпи́м отве́рзе, да ізба́вить нас от болі́зні оче́с на́ших, тіле́сних вку́пі і душе́вних; разжени́ твої́ми святи́ми моли́твами те́мний мрак приби́вший от гріхо́в на́ших, іспроси́ у Отця́ Сві́та світ благода́ті душе́вним і тіле́сним очесе́м на́шим; просвіти́ нас, омраче́нних гріхми́, сві́том Бо́жия благода́ті, да твої́х ра́ди святи́х моли́тв да́сться безоче́сним сла́дкоє зрі́ніє. О вели́кая уго́дниця Бо́жия! О му́жественнійшая ді́во! О крі́пкая му́ченице свята́я Параске́во! Святи́ми твої́ми моли́твами бу́ди нам грі́шним помо́щниця, хода́тайствуй і моли́ся о окая́нних і зіло́ неради́вих грі́шниціх, ускори́ на по́мощ нам, і́бо зіло́ немощни́ єсьми́. Моли́ Го́спода, чи́стая діви́це, моли́ Милосе́рдаго, свята́я му́ченице, моли́ Жениха́ твоєго́, непоро́чная Христо́ва неві́сто, да твої́ми моли́твами посо́бствоваші, мра́ка же гріхо́внаго ізби́вше, во сві́ті і́стинния ві́ри і дія́ній Боже́ственних вни́дем во світ ві́чний дне невече́рняго, во град весе́лія при́снаго, в не́мже ти ни́ні сві́тло блиста́єши сла́вою і весе́лієм безконе́чним, славосло́в'ящи і воспіва́ющи со всі́ми Небе́сними Си́лами Трисвяти́тельноє Єди́ноє Божество́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Свята́я неві́сто Христо́ва, многострада́льная му́ченице Параске́во! Ві́ми, я́ко от ю́ности твоєя́ ти все́ю душе́ю твоє́ю і всім се́рдцем твої́м возлюби́ла єси́ Царя́ сла́ви, Христа́ Спаси́теля і Єму́ єди́ному уневі́стилася єси́, разда́вши імі́нія твоя́ неіму́щим і бі́дним. Ти си́лою благоче́стія твоєго́, твої́м цілому́дрієм і пра́ведностію, я́ко луча́ми со́лнечними, просія́ла єси́, жи́вши свя́то среди́ неві́рних і безбоя́зненно пропові́давши їм Христа́ Бо́га. Ти, от дній ю́ности твоєя́, науче́нная твої́ми роди́телями, всегда́ благогові́йно че́ствовала дні іскупи́тельних страсте́й Го́спода на́шего Ісу́са Христа́, Єго́же ра́ди і сама́ доброво́льно пострада́ла єси́. Ти, десни́цею А́нгела Бо́жия от неісці́льних ран ди́вно ісцеле́нная і восприя́вшая неізрече́нную сві́тлость, ізуми́ла єси́ неві́рних мучи́телей. Ти, і́менем Го́спода на́шего Ісу́са Христа́ і си́лою моли́тви твоє́ю в ка́пищі язи́чеськом всіх і́долов до́лу пове́ргши, в прах сокруши́ла єси́ я. Ти, опаля́ємая свіща́ми, єди́ною моли́твою твоє́ю ко всеси́льному Го́споду угаси́ла єси́ огнь єсте́ственний, і тім же пла́менем, чуде́сне возжже́нним чрез А́нгела Бо́жия, попали́вши неі́стових беззако́нников, мног наро́д привела́ єси́ к позна́нію і́стиннаго Бо́га. Ти, во сла́ву Го́спода прия́вши ме́чноє глави́ твоєя́ усіче́ніє от мучи́телей, до́блественно сконча́ла єси́ страда́льчеський твой по́двиг, возше́дши душе́ю твоє́ю на Небеса́, в черто́г вожделі́ннаго твоєго́ Жениха́ Христа́ Царя́ Сла́ви, ра́достно сре́тшаго тя сим небе́сним гла́сом: “Ра́дуйтеся, пра́веднії, я́ко му́чениця Параске́ва увінча́ся!” Ті́мже і ми днесь приве́тствуєм тя, многострада́льная, і, взира́юще на святу́ю твою́ іко́ну, с умиле́нієм вопіє́м ті: всечестна́я Параске́во! Ві́ми, я́ко ве́ліє і́маши дерзнове́ніє ко Го́споду: умоли́ у́бо Єго́ Человіколю́бця і о нас с предстоя́щих і моля́щихся ті, да пода́сть Он і нам, я́коже тебі́, терпі́ніє і благоду́шіє в біда́х і ско́рбних обстоя́ніях; да да́руєть Он, хода́тайством твої́м і заступле́нієм, ра́достноє, благоде́нственноє і ми́рноє житіє́, здра́віє же і спасе́ніє, і во всем благо́є поспіше́ніє возлю́бленному на́шему оте́честву, да ниспосле́ть свято́є Своє́ благослове́ніє і мир, і всім правосла́вним христия́нам да пода́сть твої́ми святи́ми моли́твами утвержде́ніє во ві́рі, благоче́стії і свя́тості, преспі́яніє же в христия́нськой любві́ і вся́кой доброді́телі: да очи́стить нас грі́шних от вся́кой скве́рни і поро́ка, да огради́ть нас святи́ми Свої́ми А́нгелами, да засту́пить, сохрани́ть і поми́луєть всіх свято́ю Своє́ю благода́тію і соді́лаєть наслі́дниками і прича́стниками Небе́снаго Своєго́ Ца́рствія. І та́ко улучи́вше спасе́нія твої́ми святи́ми моли́твами, предста́тельством і заступле́нієм, всесла́вная неві́сто Христо́ва Параске́во, просла́вим все пречи́стоє і великолі́поє і́м'я ди́внаго во святи́х Свої́х і́стиннаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Антонію Димському","e":"Prayer to St Anthony of Dymsk","secs":[{"h":"Тропар, глас 4","ps":["Доброді́телей ревни́телю, / пусти́нний жи́тель, / подви́жник ві́ри Христа́ Бо́га на́шего, / поще́нієм і труди́ умертви́вий плотська́я вожделі́нія, / тезоімені́те Вели́кому Анто́нію, / єго́же житію́ поревнова́л єси́ / і во єго́же і́м'я Боже́ственний храм воздви́гл єси́, / ку́пно с ним, преподо́бне Анто́ніє, моли́ Спаси́теля всіх, / да і нас сотвори́ть побіди́телі плотськи́х по́хотей / і хра́ми Ду́ха Свята́го, / по вели́цій Єго́ ми́лості."]},{"h":"Кондак, глас 6","ps":["Све́рстник і подража́тель преподо́бному Варлаа́му, / послуша́ніє к нему́ і́стинноє стяжа́в, / досто́їн яви́лся єму́ преє́мник, / упа́сши до вре́мене ста́до єго́, / доброді́телем же єго́ поревнова́в, / в ту́южде мі́ру во́зраста дости́гл єси́, / безмо́лвіє пусти́нноє возлюби́в, / і уго́ден Го́сподеві показа́лся єси́, / первонача́льний бив пусти́ні при є́зері Ди́мськом, / тім ті вопіє́м: / с преподо́бним Варлаа́мом, о́тче Анто́ніє, моли́ о нас Бо́га, / да дасть нам та́кожде угоди́ти Єму́, я́коже і ти, / о́бразе послуша́нія і безмо́лвія ти́хий рачи́телю."]},{"h":"Молитва","ps":["О, па́стирю до́брий, учи́телю і наста́вниче наш, і святи́я оби́телі Ди́мськия нача́льниче, преподо́бний о́тче Анто́ніє! Мо́лим тя усе́рдно. Ти, я́ко імі́я дерзнове́ніє ко Влади́ці Христу́ і ко Пречи́стій Єго́ Ма́тері, бу́ди о нас недосто́йних, і́же с ві́рою притека́ющих к тебі́, хода́тай і моли́твенник те́плий, заступа́я нас от вся́ких бід і напа́стей, да твої́ми моли́твами і предста́тельством пребу́дем невреди́ми от враго́в на́ших ви́димих і неви́димих. Моли́ милосе́рдіє Єго́, є́же спасти́ нас от прегріше́ній на́ших, і́миже вість судьба́ми. Моли́ бла́гость Єго́, є́же ми́лостив подава́ти нам і всему́ ми́ру потре́бная. Моли́ся Даю́щему всім мир: ниспосла́ти мир Це́рквам, собира́я расточе́нния во єди́но, сохрани́ти страну́ на́шу в ми́рі і тишині́ і вся́кому ві́рному в до́мі і на путі́ і повсю́ду дні бла́гі і безм'яте́жни дарова́ти, умири́ти жизнь на́шу, поми́ловати нас, предстоя́щих зді і за благосло́вною вино́ю отше́дших оте́ць і бра́тій на́ших, і весь мир, і спасти́ ду́ші на́ша, да ви́ну сла́вим, хва́лим, поє́м і велича́єм пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Кукші Одеському","e":"Prayer to St Kuksha of Odesa","secs":[{"h":"Тропар, глас 4","ps":["От ю́ности мир суєму́дренний і лука́вий оста́вил єси́, / Боже́ственною сви́ше просвіти́вся благода́тію, преподо́бне, / мно́гим терпі́нієм во вре́менній жи́зні по́двиг соверши́л єси́, / ті́мже істоча́єши чуде́с благода́ть всім с ві́рою приходя́щим к ра́ці моще́й твої́х, // Ку́кшо, преблаже́нне о́тче наш."]},{"h":"Кондак, глас 8","ps":["Подви́жника благоче́стія іску́сна, / но́ваго іспові́дника ві́ри оте́чеськия / преподо́бнаго Ку́кшу ві́рно всі ублажи́м, / я́ко па́стиря і́стиннаго, / ста́рця бла́гостнаго, і́ноков наста́вника, / уті́шителя малоду́шних, ціли́теля неду́жних, / і по кончи́ні показу́ющаго сві́тлость житія́ своєго́. / І днесь в па́м'ять єго́ прите́кше, ра́достно возопіє́м: / я́ко імі́я дерзнове́ніє к Бо́гу, / многообра́зних нас ізба́ви обстоя́ній, да зове́м ті: // ра́дуйся, утвержде́ніє лю́дем правосла́вним."]},{"h":"Молитва","ps":["О, преподо́бне і богоно́сне о́тче наш Ку́кшо, оби́телі Успе́нія Бо́жієй Ма́тері похвало́, богоспаса́ємаго гра́да Оде́сси неув'яда́ємий цві́те, кро́ткий па́стирю Христо́в і вели́кий за нас моли́твенниче. Усе́рдно к тебі́ прибіга́єм і с сокруше́нним се́рдцем про́сим: не отими́ покро́в твой от оби́телі на́шей, в не́йже по́двигом до́брим подвиза́лся єси́. Бу́ди помо́щник благи́й всім благоче́стно живу́щим і до́брі тружда́ющимся в ней. О, до́брий наш па́стирю і богому́дрий наста́вниче, преподо́бне о́тче Ку́кшо, при́зри ми́лостивно на предстоя́щия лю́ди, умиле́нно моля́щіяся і прося́щия от тебе́ по́мощі і заступле́нія. Пом'яни́ всіх, ві́ру і любо́в к тебі́ іму́щих, і́м'я твоє́ моли́твенно призива́ющих і на поклоне́ніє моще́м твої́м святи́м приходя́щих, і вся во благи́х проше́нія їх ми́лостивно іспо́лни, осіня́я їх святооте́чеським твої́м благослове́нієм. Ізба́ви, святи́й о́тче, от вся́каго наві́та вра́жия Це́рков на́шу святу́ю, град сей,' оби́тель і зе́млю на́шу, і не оста́ви заступле́нієм твої́м нас немощни́х, гріха́ми і скорб'я́ми мно́гими обремене́нних. Озари́, преблаже́нне, ум наш сві́том лиця́ Бо́жия, укріпи́ благода́тію Госпо́дней жизнь на́шу, да в зако́ні Христо́ві утверди́вшеся, нелі́ностно по путі́ за́повідей святи́х потеце́м. Осіни́ твої́м благослове́нієм нас, і всіх в ско́рбіх су́щих, болі́зньми душе́вними і тіле́сними одержи́мих, ісціле́ніє, утіше́ніє і ізбавле́ніє да́руя. Над всі́ми же си́ми іспроси́ нам сви́ше дух кро́тости і смиренному́дрія, дух терпі́нія і покая́нія, отступи́вшим от правосла́вния ві́ри і поги́бельними єресьми́ і раско́лами ослепле́нним вразумле́ніє, во тьмі неві́рія блужда́ющим сві́том і́стиннаго богопозна́нія просвіще́ніє, раздо́ров і нестроє́ній утоле́ніє. Умоли́ Го́спода Бо́га і Пресвяту́ю Богоро́дицю дарова́ти нам ти́хоє і безгрі́шноє житіє́. Помина́й нас недосто́йних у престо́ла Вседержи́теля, і іспроси́ ми́рную христия́нськую кончи́ну, і сподо́би нас по́мощію твоє́ю спасе́ніє ві́чноє улучи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим ве́лія щедро́ти і неізрече́нния ми́лости Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, і твоє́ оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомученику Феодору Тирону","e":"Prayer to the Great Martyr Theodore the Recruit","secs":[{"h":"Тропар, глас 2","ps":["Ве́лія ві́ри ісправле́нія, / во істо́чниці пла́мене, я́ко на воді́ упокоє́нія, / святи́й му́ченик Фео́дор ра́довашеся; / огне́м бо всесожже́гся, / я́ко хліб сла́дкий Тро́йце принесе́ся. / Того́ моли́твами, Христе́ Бо́же, // спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Ві́ру Христо́ву, я́ко щит, внутр приї́м в се́рдці твоє́м, / проти́вния си́ли попра́л єси́ многострада́льче, / і вінце́м Небе́сним вінча́лся єси́ ві́чно, // Фео́доре, я́ко непобіди́мий."]},{"h":"Молитва","ps":["О, пресла́вні, великому́чениче Фео́доре Ти́роне. Усли́ши моле́ніє нас ві́рних, велича́ющих тя і в смире́нії своє́м взива́ющих к тебі́ от всея́ душі́. От ю́ности показа́вий пла́менную ві́ру во Христа́ Го́спода і ра́ди нея́ жизнь свою́ положи́вий, пода́ждь і нам моля́щимся тебі́ душе́вния си́ли, во є́же блюсти́ во вся дні чистоту́ пра́вия ві́ри. Запечатлі́вий му́ченичеством іспові́даніє ві́ри в пещі́ о́гненній, бу́ди нам о́бразом в ре́вности пропове́диванія І́стини Христо́вой. Огради́вий ві́рних от гріха́ язи́чества і отсту́пничества, соблюди́ і нас чи́стими от єрети́чеських ко́зней і вся́каго дия́вольськаго навожде́нія. О, Преблаже́нне, великому́чениче Фео́доре, свої́м предста́тельством у Престо́ла Всеви́шняго умоли́ Го́спода Бо́га, да пода́сть нам благода́тния си́ли, во є́же напра́вити путі́ жи́зні на́шея по Сло́ву Бо́жию во спасе́ніє душ на́ших. Я́ко да твої́ми моли́твами получи́вше благода́ть і ми́лость, просла́вим всіх благи́х Істо́чника і Даропода́теля Бо́га, Єди́наго, в Тро́йці Святі́й Сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобній Єфросинії, ігуменії Полоцькій","e":"Prayer to St Euphrosyne, Abbess of Polotsk","secs":[{"h":"Тропар, глас 4","ps":["Подража́ющи дванадесятолі́тна дванадесятолі́тну Христу́, / учи́вшему во святи́лищі Бо́жию сло́ву, / послі́довала єси́, Євфроси́ніє. / Сла́ву вре́менную і земна́го обру́чника оста́вльши / і вся мирська́я презрі́вши / красні́йшему па́че всіх Христу́ себі́ уневі́стила єси́, / крест взе́мши, путе́м а́нгельськаго житія́ ше́ствующи / і мно́гія к Нему́ наставля́ющи, / во благоуха́нії ми́ра, в Небе́сний Черто́г востекла́ єси́, / іді́же моли́, Єго́же возлюби́ла єси́, // о чту́щих благоче́стно па́м'ять твою́."]},{"h":"Інший тропар, глас 4","ps":["Бога́тство своє́ ни́щим расточи́вши / і сла́ву кня́жеськую ні во что же вміни́вши, / обру́чника вре́меннаго, кра́сная ді́во, возгнуша́лася єси́ / і, уневі́стившися Жениху́ Христу́, / Тому́, я́коже ві́но, чистоту́ душе́вную і тіле́сную принесла́ єси́, Євфроси́ніє. / Єму́же ни́ні во весе́лії предстоя́, // помина́й нас, чту́щих па́м'ять твою́."]},{"h":"Кондак, глас 8","ps":["Ізбра́нній Бо́гом от самаго́ рожде́нія / і призва́нній на служе́ніє Єму́, / в чи́ні а́нгельстім Го́сподеві послужи́вшей свя́то, / і преподо́бно пожи́вшей, / і ни́ні с Небе́сними си́лами Го́спода восхваля́ющей, / о нас же, грі́шних, пред Го́сподем хода́тайствующей, / с ра́достію і любо́вію воззове́м: // ра́дуйся, Євфроси́ніє, неві́сто Христо́ва всечестна́я."]},{"h":"Інший кондак, глас 8","ps":["Чи́стоє своє́ ді́вство і честно́є / ми́лостинею, я́ко світи́льник єле́єм, украси́вшую / і с му́дрими ді́вами в пресві́тлий черто́г Христо́во вше́дшую, / Євфроси́нію сла́вную ублажи́м / і, припа́дше к честни́м єя́ моще́м, наслади́мся єя́ благоуха́нія / і уми́льні к ней возопіє́м: / я́ко імі́я дерзнове́ніє ко Христу́ Бо́гу // моли́ ізба́витися злово́нія страсте́й і спасти́ся душа́м на́шим."]},{"h":"Інший кондак, глас 4","ps":["Превита́вши от землі́ По́лотськия, / оте́чество своє́, я́ко Авраа́м, наслі́довавши, Євфроси́ніє, / зе́млю висо́ку сообра́зну — Го́рній Сіо́н, / ті́мже ті́ло твоє́ душе́вним благому́жествієм, страда́нієм по́стним / я́ко же́ртву приноси́ла єси́ // милосе́рдієм Свої́м, Да́вшему Себе́ за челові́ки Же́ртву благоприя́тну."]},{"h":"Молитва","ps":["О, преподо́бная і приснопа́м'ятная, всехва́льная ма́ти Євфроси́ніє, А́нгеле во пло́ті, Богоізбра́нний сосу́де Свята́го Ду́ха, Це́ркве Христо́ви похвало́ і украше́ніє, мона́шествующих сла́во і утвержде́ніє, оте́честву, оби́телі твоє́й і всей страні́ по́моще, покро́ве і защи́тнице! Ти єси́, я́ко дре́во, насажде́нноє при ісхо́дищих вод, плоди́ доброді́телей твої́х і благода́тними дарова́нії Свята́го Ду́ха укра́шенная, наста́внице ді́лом і сло́вом, ізбра́нная, непоро́чная і до́брая. Усли́ши ни, моля́щіяся тебі́ і призива́ющия і́м'я твоє́, і́маши бо дерзнове́ніє у Го́спода. Іспроси́ нам преспі́яніє в жи́зні доброді́тельній, огради́ сердця́ на́ша ві́рою, наде́ждою і любо́вію і стра́хом Бо́жиїм. Пода́й нам по́мощ в труді́х і ско́рбіх на́ших і, я́коже попече́ніє імі́ла єси́ в житії́ твоє́м о оби́телі твоє́й і і́ночествующих, та́ко і ни́ні потщи́ся о нас, благопоспіши́ти нам во всем: і оби́тель твою́ огради́ ми́ром і защити́ от враг ви́димих і неви́димих, да преуспіва́єть і процвіта́єть в доброді́теліх. Ізми́ ни от вся́кия ну́жди і тісноти́, от лю́тих болі́зней і от неча́янния сме́рти і приведи́ ни ко і́стинному покая́нію при ісхо́ді із жи́зні сея́; іспроси́ нам у Го́спода Бо́га кончи́ну ми́рну, безболі́зненну, непости́дну, святи́х Та́їн прича́стну і преведи́ ни чрез мита́рства возду́шная, да не похи́тять нас істяза́теліє гро́знії по гріхо́м на́шим, но да твої́м заступле́нієм і по́мощію возмо́жем безбі́дно проіти́ істяза́ніє возду́шноє, і ми́лость получи́ти, і предста́ти неосужде́нно стра́шному Престо́лу, і на Стра́шнім Суди́щі сподо́битися одесну́ю ста́ти Пра́веднаго Судії́, і наслі́довати пра́ведних часть. Єй, госпоже́, всечестна́я ма́ти, преподо́бная Євфроси́ніє, помози́ нам моли́твами твої́ми, огради́ нас і заступи́ от вся́ких ко́зней вра́жиїх, да сподо́бимся прейти́ вре́м'я жи́зні сея́ непреткнове́нно і спасе́ніє получи́ти моли́твами твої́ми у Христа́ Го́спода, Єго́же і сподо́бимся пі́ти і славосло́вити со Безнача́льним Отце́м і со Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Феофілу Київському","e":"Prayer to St Theophilus of Kyiv","secs":[{"h":"Тропар, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, блаже́нне Фео́филе, / і Тому́ єди́ному рабо́тати пла́менні возжелі́л, / непреста́нною моли́твою і юро́дством в пусти́ні Кита́євой подвиза́лся єси́, / уго́дником пече́рським подража́я. / Сего́ ра́ди вопіє́м ті: / спаса́й нас моли́твами твої́ми, // преподо́бне о́тче наш."]},{"h":"Кондак, глас 8","ps":["От ми́ра су́єтнаго ізше́л єси́ / і в де́бріх Кита́єва всели́лся єси́, / преподо́бне о́тче наш Фео́филе. / Непреста́нним псалмопі́нієм і юро́дством свої́м / мно́гих на путь спасе́нія наста́вил єси́. / Сего́ ра́ди вопіє́м ті: // моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Молитва","ps":["О, преди́вний уго́дниче Христо́в, крі́пкий моли́твенниче і засту́пниче, о́тче наш Фео́филе! Ти от чре́ва ма́тері ізбра́нний Бо́гом на служе́ніє єму́ і ди́вно їм храни́мий от вся́каго зла. За твоя́ по́двиги юро́дства Госпо́дь дарова́ тебі́ дар проро́чества і чудотворе́ній. По за́повіді пастиренача́льника Христа́ ти ду́шу свою́ полага́вий за о́вці ста́да Христо́ва. Ти грі́шников та́йних і я́вних гро́зно облича́вий і свої́ми му́дрими словеси́ к покая́нію і ісправле́нію їх приводи́вий. Ти приходя́щих к тебі́ больни́х і ско́рбних не отверга́л єси́. Ти бил всім я́ко оте́ць чадолюби́вий і па́стир до́брий. І ни́ні усли́ши нас, с ві́рою призива́ющих тя і усе́рдно припа́дающих к ра́ці моще́й твої́х, о́тче наш Фео́филе. Іспроси́ у Всеми́лостиваго Бо́га мир Це́ркві на́шей правосла́вній во оте́чествії твоє́м. Вразуми́ і обрати́ єретико́в і раско́льников в ло́но Ма́тері Це́ркві. Па́стирям на́шим ре́вность о спасе́нії люде́й, лю́дем же послуша́ніє Святі́й Це́ркві і ре́вность защища́ти ві́ру правосла́вную іспроси́. Умоли́ Небе́снаго Отця́ всім нам пода́ти коєму́ждо по проше́нію єго́: ю́ним в правосла́вній ві́рі возраста́ніє, ста́рим і немощни́м подкріпле́ніє і утіше́ніє, боля́щим ісціле́ніє, сирота́м і безпомо́щним заступле́ніє і неча́янную ра́дость, заблу́ждшим і согреша́ющим ісправле́ніє. І всім нам іспроси́ тіле́сноє здра́віє і душе́вноє спасе́ніє. Согрі́й огне́м Боже́ственной любві́ охладевшия сердця́ на́ша. Помози́ нам іспра́вити жизнь на́шу гріхо́вную, даби́ безбі́дно прейти́ мита́рства де́монов лю́тих і водвори́тися во оби́теліх Отця́ Небе́снаго, даби́ вку́пі с тобо́ю і со всі́ми святи́ми воспіва́ти всесвято́є і великолі́поє і́м'я Пресвяти́я Тро́йці: Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іоанну, митрополиту Тобольському","e":"Prayer to St John, Metropolitan of Tobolsk","secs":[{"h":"Тропар, глас 8","ps":["Наста́вниче благоче́стія, / сиро́тствующих пита́телю, / скорб'я́щих уті́шителю, неду́гующих врачу́ безме́здний, / душе́ю стра́ждущих ско́рий помо́щниче, / те́плий моли́твенниче о всіх ко Го́споду, / святи́телю о́тче Іоа́нне, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Яви́лся єси́ во тьмі неві́дінія пребива́ющим просвіти́тель, / вдов і сиро́т уті́шитель, / ди́вний врач немощству́ющих, / младе́нцев і отроко́в наста́вник, / роди́телем же пресві́тлоє ра́дованіє, / святи́телю о́тче Іоа́нне, / моли́ Христа́ Бо́га пода́ти страні́ на́шей во ві́рі утвержде́ніє, / во́їнству на́шему на враги́ побі́ду і одолі́ніє, // лю́дем же свої́м ве́лію ми́лость."]},{"h":"Молитва","ps":["О святи́телю Христо́в Іоа́нне, Бо́жию Престо́лу со святи́ми предстоя́й! Ти єси́ оте́ць наш любвеоби́льний і моли́твенник наш те́плий. Умоли́ Го́спода Бо́га, да пода́сть нам коєго́ждо потре́бно поле́зная: скорб'я́щим утіше́ніє, немощни́м здра́віє, заблу́ждшия да наста́вить і обрати́ть на путь покая́нія, ра́спри і раздо́ри умири́ть, неве́дущия Христа́ лю́ди на путь спасе́нія да обрати́ть і всіх нас єдине́нієм ду́ха і любве́ в Єди́ній Святі́й Своє́й Це́ркві соєдини́ть, да сохрани́ть нас от гла́да, гра́да, тру́са, пото́па, огня́, меча́, междоусо́бния бра́ні і напра́сния сме́рті, найпа́че же от іскуше́ній, облежа́щих нас в жи́зні сей, да да́руєть нам ми́рноє пожи́ти зді житіє́ і ві́ру свою́ Правосла́вную невреди́му соблюсти́. О святи́й уго́дниче Христо́в, архіпа́стирю, предо́брий, моли́твенниче наш неуси́пний! От ю́ности всего́ себе́ Бо́гу посвяти́в, равноа́нгельноє житіє́ стяжа́л єси́, іспо́лнен бі ра́дости духо́вния, я́же озаря́ше сві́тлость ли́ка твоєго́ і сердця́ ві́рних утіша́ше, поі́стині бі світи́льник горя́й і світя́й, святолі́пно пожи́в, от Го́спода сподо́блен бі да́ра прозрі́нія, вре́м'я кончи́ни своєя́ предуве́да, моля́ся пред о́бразом Пречи́стия Богоро́диці, коленопреклоне́нне преста́вися; ни́ні проси́ Ю о нас, да бу́деть нам Покрови́тельниця в сей многотру́дній жи́зні і в час кончи́ни на́шея да умо́лить Всеблага́го Го́спода сподо́битися нам в ли́ці благоугоди́вших предста́ти Престо́лу Єго́ і восхвали́ти в Тро́йці сла́вимаго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученику Андрію Стратилату","e":"Prayer to the Martyr Andrew Stratelates","secs":[{"h":"Тропар, глас 5","ps":["Земна́го са́на сла́ву оста́вив, / Небе́сноє Ца́рство наслі́довал єси́, / кро́вними ка́плями, я́ко пречу́дним ка́менієм, / нетлі́нния вінці́ украси́л єси́ / і ко Христу́ приве́л єси́ собо́р страстоте́рпець. / С ли́ки а́нгельськими в невече́рнім сві́те / незаходи́маго Со́лнця Христа́ обрі́л єси́, / свя́те Андре́є Стратила́те, / Єго́же моли́ с пострада́вшими с тобо́ю при́сно, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["В моли́твах Го́сподеві предстоя́, / я́коже звізда́ со́лнцю предтеки́й, / і жела́ємоє сокро́вище Ца́рствія узрі́л єси́, / ра́дости неізрече́нния ісполня́яся. / Безсме́ртному Царю́ в бесконе́чния ві́ки, / от А́нгел безпреста́ни хвали́мому, поє́ши, Андре́є Стратила́те. // С ни́миже моли́ся непреста́нно о всіх нас."]},{"h":"Молитва","ps":["Святи́й му́чениче Андре́є Стратила́те, при́зри с Небе́снаго черто́га на тре́бующих твоєя́ по́мощі і не отве́ргни проше́ній на́ших, но, я́ко при́сний благоді́тель і хода́тай наш, моли́ Христа́ Бо́га, да, человіколюби́в і многоми́лостив Сий, сохрани́ть нас от вся́каго лю́таго обстоя́нія: от тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні. Да не осу́дить нас, грі́шних, по беззако́ніям на́шим, і да не во зло обрати́м блага́я, дару́ємая нам от Всеще́драго Бо́га, но во сла́ву свята́го і́мене Єго́ і в прославле́ніє крі́пкаго твоєго́ заступле́нія. Да моли́твами твої́ми дасть нам Госпо́дь мир по́мислов, воздержа́ніє от па́губних страсте́й і от вся́кия скве́рни, і да укріпи́ть во всем ми́рі Свою́ Єди́ную Святу́ю Собо́рную і Апо́стольськую Це́рков, ю́же стяжа́л єсть Честно́ю Своє́ю Кро́вію. Моли́ся прилі́жно, святи́й му́чениче, да благослови́ть Христо́с Бог держа́ву на́шу, да утверди́ть во Святі́й Своє́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да всі чле́ни єя́, чи́стії от суєму́дрія і суєві́рія, ду́хом і і́стиною покланя́ються Єму́ і усе́рдно пеку́ться о соблюде́нії Єго́ за́повідей, да ми всі в ми́рі і благоче́стії поживе́м в настоя́щем ві́ці і дости́гнем блаже́нния ві́чния жи́зні на Небесі́ благода́тію Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва со Отце́м і Святи́м Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва священномученику Клименту, папі Римському","e":"Prayer to the Hieromartyr Clement, Pope of Rome","secs":[{"h":"Тропар, глас 4","ps":["І́же от Бо́га чудоді́йстви / пресла́вно удивля́я вселе́нния конці́ ми́ра, / свяще́нний страда́льче, / па́че єстества́ мо́рю, соста́ви вода́м содіва́єши разділе́ніє / в честні́й па́м'яті твоє́й / всегда́ притека́ющим усе́рдно в Богозда́нную ті це́рков, / чуде́сним твої́м моще́м, / і по всенаро́дном хожде́нії / мо́ре во єди́но тече́ніє чудоді́тельні твори́ши, / Кли́менте преди́вний, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Боже́ственнаго виногра́да священнооді́янна / всім лоза́ яви́ся, / ка́плющи сла́дость прему́дрости, / моли́твами твої́ми, всече́стне, / да тебі́ істка́ну я́ко багряни́цю, / піснь ми́сленную принесе́м, / Кли́менте свя́те: // спаси́ раби́ твоя́."]},{"h":"Молитва","ps":["О, всечестни́й учениче́ верхо́внаго апо́стола Петра́, но́вий Пе́тре ві́ри Христо́вой, втори́й Моїсе́ю, священному́чениче Кли́менте, просвіще́нний уче́нієм вели́каго апо́стола, вінча́нний вінце́м му́ченичества! Іспроси́ нам моли́твами твої́ми благода́ть Свята́го Ду́ха сохраня́ти ві́ру Христо́ву і церко́вния спаси́тельния оби́чаї, да расточи́ться безбо́жіє. Умоли́, уго́дниче Бо́жий, Милосе́рдаго Творця́, да ізліє́ться на нас благода́ть Свята́го Ду́ха, просвіща́ющая на́ші ду́ші, да попали́ть Госпо́дь Бог страсте́й на́ших огнепа́льная стремле́нія, да сохрани́ть нас от вся́кия зло́би, да спасе́ть от напа́стей, бід і скорбе́й, і да пребу́дем ві́рними христия́нами до конця́ жи́зні на́шея, сохраня́я в сердця́х на́ших па́м'ятованіє печа́лей, болі́зней і трудо́в твої́х, во сла́ву Бо́га Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва","ps":["О вели́кий чудотво́рче, священному́чениче Кли́менте! Приклони́ся ни́ні к на́шим воздиха́нієм серде́чним і помози́ нам во вре́менном житії́ сем твори́ти вся в зако́ні Бо́жії предло́женная, вся́каго же гріха́ отмета́тися. Ти, вели́кий подви́жниче, от ю́ности твоєя́ клевети́ претерпі́вий, мно́гія же болі́зні душе́вния і труди́ понеси́й, помоли́ся ко Го́споду Бо́гу о нас, грі́шних і недосто́йних раб Бо́жиїх (імена́), да твої́м предста́тельством і заступле́нієм пода́сть Всеблаги́й і нам, грі́шним, си́лу і крі́пость во благоду́шії претерпіва́ти клевети́ челові́чеськія і я́же на землі́ ско́рби і сохрани́ти за́повіді Єго́, да просла́вим пречестно́є і великолі́поє і́м'я Го́спода Бо́га і Єго́ благода́ть, да́нную тебі́, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірному великому князю Святославу","e":"Prayer to the Right-believing Grand Prince Sviatoslav","secs":[{"h":"Молитва","ps":["О, святи́й уго́дниче Христо́в, благові́рний кня́же Святославе! Ві́ми тя, я́ко печа́льника землі́ Українськия, кро́тостію своє́ю в междоусо́бних распріх бра́тій умиротворявшего. Стра́нен і пришле́ць на землі́ яви́лся єси́, мно́гажди бо гони́м с престо́ла княже́нія своєго́, чужд вражди́ і не́нависті показа́лся єси́. Благоро́дствіє, бога́тство, честь і сла́ву я́коже су́єтная презрі́в, к Бо́гу єди́ному все́ю душе́ю приліпи́лся єси́, і бла́го і́го Христо́во на ся взем, миролюбієм го́рняго Сіо́на дости́гл єси́. Не ві́ми тя ме́ртва би́ти, но і по сме́рті ві́дуще тя жива́ су́ща, предстоя́ще пред цільбоно́сною ра́кою моще́й твої́х, сія́ се́рдцем і усти́ лобиза́єм і тебі́ зове́м:","При́зри на лю́ті страждащеє оте́чество на́ше, в не́мже крамоли́ і нестроє́нія зіло́ умно́жишася, і умоли́ Го́спода Сла́ви да поми́луєть зе́млю Українськую. Пробуди́ со́вість на́шу, су́єтними мудрова́ніями і страстьми́ па́губними усипле́нную. Просвіти́ се́рдця на́ша, горди́нею і злопам'ятством омраченниє. Потщи́ся, уго́дниче Бо́жий, не оста́ви нас во гріхо́внім пліну́ би́ти, да не бу́дем посмія́ніє дия́волу і не у́мрем в лука́вих дія́ніях на́ших, да́руй нам покая́ніє люботру́дноє. Умири́ вражду́ на нас іму́щих, да не поги́бнуть ра́ди на́шего окая́нства. Бу́ди усе́рдний попечитель о домі́х на́ших, при́зри на сле́зи отце́в і ма́терей о ча́діх свої́х заблудших. Посіти́ в темни́цях су́щих, вдови́ць і си́рих не оста́ви к по́льзі душе́вній і тіле́сній потре́бная у Го́спода іспроси́, во є́же ізба́витися нам всім в день су́дний от стра́шних шу́їя ча́сти, ста́ти же одесну́ю со ізбра́нними Єго́ і наслі́діє Ца́рствія Небесного сла́вити ку́пно с тобо́ю всіх благи́х Пода́теля єдиного в Тро́йці славимого Бо́га, Отця́ і Си́на і Свята́го Ду́ха ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Сла́ву земна́го княже́нія, / богому́дре Святославе, / ороси́л єси́ незло́бієм і кро́тостію, / тім же і Бог тя просла́ви, / чудеси́ во утіше́ніє скорб'я́щих, / ціли́ши бо с ві́рою притека́ющих к ра́ці моще́й твої́х. / Сего́ ра́ди мо́лим тя: / проси́ у Христа́ Го́спода / от вся́ких бід ізбавле́ніє / і стяжа́ніє нам Ца́рствія Небе́снаго."]},{"h":"Кондак, глас 3","ps":["Гра́да Юрева теплі́йший засту́пниче, / землі́ Володимирськия покро́ве, / благові́рний кня́же Святославе, / ізба́ви нас душетлі́нних страсте́й, / і спаси́ твої́ми моли́твами."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й благові́рний кня́же Святославе, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас / Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва праведному Йосифу Обручнику","e":"Prayer to the Righteous Joseph the Betrothed","secs":[{"ps":["О, святи́й пра́ведний Іо́сифе! Ти, єще́ на землі́ сий, ве́ліє імі́л єси́ дерзнове́ніє к Си́ну Бо́жию, І́же благоізво́ли іменова́ти тя отця́ Своєго́, я́ко Обру́ченика Своєя́ Ма́тере, і послу́шати тя. Ві́руєм, я́ко ни́ні, с ли́ки пра́ведних во оби́теліх Небе́сних водворя́яся, усли́шан бу́деши во вся́ком твоє́м проше́нії к Бо́гу і Спаси́телю на́шему. Ті́мже, ко твоєму́ покро́ву і заступле́нію прибіга́юще, смире́нно мо́лим тя: я́коже сам от бу́рі сомни́тельних помишле́ній ізба́влен бил єси́, си́це ізба́ви і нас, волна́ми смуще́ній і страсте́й обурева́ємих; я́коже огражда́л єси́ Всенепоро́чную Ді́ву от клевети́ челові́чеськія, огради́ і нас та́кожде от вся́кия клевети́ напра́сния; я́коже храни́л єси́ от вся́каго вре́да і озлобле́нія воплоти́вшагося Го́спода, си́це сохраня́й твої́м заступле́нієм Це́рков Єго́ Правосла́вную і всіх нас от вся́каго озлобле́нія і вре́да. Ві́си, свя́тче Бо́жий, я́ко і Син Бо́жий во днех пло́ті Своєя́ в тіле́сних потре́бах ну́жду імі́яше, і ти послужи́л єси́ їм: того́ ра́ди мо́лим тя, і на́шим вре́менним ну́ждам благопоспіши́ твої́м хода́тайством, подая́ нам вся блага́я, в житії́ сем потре́бная. Ізря́дніє же про́сим тя, ісхода́тайствуй нам оставле́ніє гріхо́в прия́ти от нарече́ннаго ті Си́на, Єдиноро́днаго же Си́на Бо́жия, Го́спода на́шего Ісу́са Христа́, і досто́йни би́ти наслі́дія Ца́рства Небе́снаго нас предста́тельством твої́м сотвори́, да і ми, в го́рніх селе́ніїх с тобо́ю водворя́ющеся, просла́вим Єди́наго Триіпоста́снаго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному цареві Давиду, псалмоспівцю","e":"Prayer to the Righteous King David the Psalmist","secs":[{"h":"Тропар, глас 2","ps":["Благовіству́й, Іо́сифе, Дави́ду чудеса́ Богоотцю́: Ді́ву ви́діл єси́ ро́ждшую, с па́стирі славосло́вил єси́, с волхви́ поклони́лся єси́, А́нгелом вість приє́м. Моли́ Христа́ Бо́га спасти́ душі́ на́ша."]},{"h":"Інший тропар, глас 2","ps":["Проро́ка Твоєго́ Дави́да, Го́споди, па́м'ять пра́зднующе, тім Тя мо́лим: спаси́ душі́ на́ша."]},{"h":"Кондак, глас 3","ps":["Весе́лія днесь Дави́д ісполня́ється Боже́ственний, Іо́сиф же хвале́ніє со Іа́ковом прино́сить: віне́ць бо сродство́м Христо́вим приє́мше, ра́дуються, і неізрече́нно на землі́ Ро́ждшагося воспіва́ють, і вопію́ть: Ще́дре, спаса́й Тебі́ чтущия."]},{"h":"Інший кондак, глас 4","ps":["Просвіти́вшеєся Ду́хом чи́стоє твоє́ се́рдце, проро́чества бисть світлі́йшаго прия́телище: зри́ши бо я́ко настоя́щая дале́че су́щая: сего́ ра́ди тя почита́єм, проро́че блаже́нне, Дави́де сла́вне."]},{"h":"Молитва","ps":["О, прехва́льний і пречу́дний проро́че Бо́жий Дави́де! Усли́ши нас, грі́шних і непотре́бних, в час сей предстоя́щих пред свято́ю твоє́ю іко́ною і усе́рдно прибіга́ющих ко хода́тайству твоєму́. Моли́ о нас Человіколю́бця Бо́га, да пода́сть нам дух покая́нія і сокруше́нія о грісі́х на́ших і всеси́льною Своє́ю благода́тію да помо́жеть нам оста́вити путі́ нече́стія, приспевати же во вся́ком ді́лі бла́зі, да укріпи́ть нас в борбі́ со страстьми́ і похотьми́ на́шими; да всади́ть в се́рдці на́ше дух смире́нія і кро́тости, дух братолю́бія і незло́бія, дух терпі́нія і цілому́дрія, дух ре́вности к сла́ві Бо́жієй і спасе́нію бли́жніх. Упраздни́ моли́твами твої́ми, проро́че, зли́я оби́чаї ми́ра, па́че же поги́бельний і тлетво́рний дух ві́ка сего́, заражающий христия́нський род неуваженієм к Боже́ственній Правосла́вній ві́рі, к уставам святи́я Це́ркві і к за́повідем Госпо́днім, непочтенієм к роди́телем і власте́м предержащим, і низвергающий люде́й в бе́здну нече́стія, развраще́нія і поги́белі. Отврати́ от нас, пречу́дне проро́че, предста́тельством твої́м пра́ведний гнів Бо́жий, і ізба́ви вся гра́ди і ве́сі ца́рства на́шего от бездо́ждія і гла́да, от стра́шних бур і землетрясе́ній, от смертоно́сних язв і болі́зней, от наше́ствія враго́в і междоусо́бния бра́ні. Укріпи́ твої́ми моли́твами правосла́вних люде́й, благопоспі́шествуй їм во всіх благи́х дія́ніїх і начина́ніях к водворенію ми́ра і пра́вди в держа́ві їх. Посо́бствуй Всеукраїнському Христолюби́вому во́їнству во бра́ніх со врага́ми на́шими. Іспроси́, проро́че Бо́жий, от Го́спода па́стирем на́шим святу́ю ре́вность по Бо́зі, серде́чноє попече́ніє о спасе́нії пасо́мих, му́дрость в уче́нії і управле́нії, благоче́стіє і крі́пость во іскуше́ніїх, судія́м іспроси́ нелицеприя́тіє і безкори́стіє, правоту́ і сострада́ніє к оби́димим, всім нача́льствующим попече́ніє о подчине́нних, ми́лость і правосу́діє, подчине́нним же поко́рность і послуша́ніє ко власте́м і усе́рдноє ісполне́ніє свої́х об'язанностей; да, та́ко в ми́рі і благоче́стії пожи́вше в сем ві́ці, сподо́бимся прича́стія ві́чних благ в Ца́рствії Го́спода і Спа́са на́шего Ісу́са Христа́, Єму́же подоба́єть честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Симеону Богоприїмцю","e":"Prayer to the Righteous Simeon the God-Receiver","secs":[{"h":"Тропар, глас 4","ps":["Симео́н ста́рець днесь весели́ться, / восприя́т на руку́ свою́ Младе́нця Преві́чнаго Бо́га, / от уз пло́ті разріши́тися прося́ / і вопія́: / ви́діста о́чі мої́ // спасе́ніє Твоє́ ми́рові."]},{"h":"Кондак, глас 4","ps":["Ста́рець днесь отріши́тися от юз, моля́шеся, / се́го житія́ тлі́ннаго, / Христа́ восприя́т на ру́ки, // Зижди́теля і Го́спода."]},{"h":"Молитва","ps":["О, вели́кий уго́дниче Бо́жий і Богоприї́мче Симео́не! При́зри на м'я грі́шнаго, ко святі́й іко́ні твоє́й припа́дающа і прося́ща твоєго́ заступле́нія і по́мощі: скорб бо обдержи́ть м'я от обстоя́щих м'я ни́ні бід і зол, і утіше́нія не і́мам многоболі́зненній душі́ моє́й. Іска́х по́мощі от челові́к, і не обрі́теся. Возопія́х ко Го́споду, і не усли́ша м'я, аз прогні́вах пречи́стую бла́гость Єго́ беззако́ньми мої́ми, і мно́жеством мно́гих гріхо́в мої́х преогорчи́х человіколю́бную утро́бу Єго́. І кто мі ни́ні по́мощ яви́ть; кто мі скорб утоли́ть; кто дасть отра́ду і успокоє́ніє многом'яте́жній душе́ моє́й? К тебі́, вели́кий уго́дниче Бо́жий, прибіга́ю грі́шний і недосто́йний аз, ві́дий, я́ко ве́ліє дерзнове́ніє і́маши ко Христу́ Бо́гу і многомо́щен предста́тель єси́ о всіх, с ві́рою к тебі́ прибіга́ющих, і твоєго́ заступле́нія і по́мощі тре́бующих. Моли́ у́бо Человіколю́бця Го́спода, я́ко да прости́в мі безчи́сленная моя́ прегріше́нія, не отврати́ть ми́лость Свою́ от мене́, но я́ко благ і сострада́телен, яви́ть і мні безконе́чноє Своє́ милосе́рдіє, і в лю́тім напа́стей і бід мої́х озлобле́нії пода́сть мі всеси́льную по́мощ Свою́, і преогорче́нной душе́ моє́й осла́бу, мир, укріпле́ніє, утіше́ніє і успокоє́ніє да́руєть. Єй, вели́кий уго́дниче Бо́жий, вознеси́ Богоно́сния ру́ці твоя́ ко і́же во об'я́тіїх твої́х носи́тися ізво́лившему Христу́ Бо́гу на́шему і моли́ бла́гость Єго́, да не отри́неть моле́нія се́рдця моєго́ недосто́їнства ра́ди моєго́, но яви́ть мні благовре́менні ми́лость Свою́, во сла́ву безконе́чних щедро́т Свої́х і многомо́щнаго предста́тельства твоєго́, о не́мже подоба́єть Єму́ вся́кая сла́ва і благодаре́ніє ку́пно со Отце́м і Пресвяти́м Єго́ Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, вели́кий уго́дниче Бо́жий Богоприї́мче Симео́не! Предстоя́ Престо́лу Вели́каго Царя́ і Бо́га на́шего Ісу́са Христа́, ве́ліє дерзнове́ніє і́маши к Нему́, во об'я́тіїх твої́х на́шего ра́ди спасе́нія носи́тися ізво́лившему. К тебі́ у́бо, я́ко многомо́щному предста́телю і крі́пкому о нас моли́твеннику, прибіга́єм ми, грі́шнії і недосто́йнії. Моли́ Бла́гость Єго́, я́ко да отврати́ть от нас гнів Свой, пра́ведно по діло́м на́шим на ни дви́жимий, і, презрі́в безчи́сленная прегріше́нія на́ша, обрати́ть нас на путь покая́нія і на стезі́ за́повідей Свої́х утверди́ть нас. Огради́ моли́твами твої́ми в ми́рі живо́т наш, і во всем благо́м благо́є поспіше́ніє іспроси́, вся я́же к животу́ і благоче́стію потре́бная нам да́руя. Я́коже дре́вле Вели́кий Но́воград явле́нієм чудотво́рния іко́ни твоєя́ от губи́тельства сме́ртнаго ізба́вил єси́, та́ко і ни́ні нас і вся гра́ди і ве́сі страни́ на́шея от вся́ких напа́стей і бід і напра́сния сме́рті предста́тельством твої́м ізба́ви, і от всіх враг ви́димих і неви́димих покро́вом твої́м защити́. Я́ко да ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́ і, та́ко в ми́рі вре́менноє сіє́ житіє́ преше́дше, во ві́чний дости́гнем поко́й, іді́же сподо́бимся Небе́снаго Ца́рствія Христа́ Бо́га на́шего. Єму́же вся́кая сла́ва подоба́єть со Отце́м і Пресвяти́м Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірному князю Роману Рязанському","e":"Prayer to the Right-believing Prince Roman of Ryazan","secs":[{"h":"Тропар, глас 1","ps":["Муче́ньми странноужа́сними / і до́блестію терпі́нія / всіх преудиви́л єси́, кня́же Рома́не: / честни́х бо чле́нов твої́х по соста́вом ре́заніє / і всего́ тілесе́ твоєго́ раздробле́ніє / претерпі́л єси́ за ві́ру Христо́ву. / Ті́мже і возше́л єси́ к Престо́лу Царя́ Христа́ Бо́га / і яви́лся єси́ но́вий предста́тель Це́ркве Ряза́нськия. / Моли́ся у́бо ко Го́споду, / да мир і благоде́нствіє да́руєть гра́ду на́шему, / і іспроси́ у Него́ ми́лость і спасе́ніє // чту́щим свяще́нную па́м'ять твою́, многострада́льне."]},{"h":"Кондак, глас 2","ps":["Оклеве́танний пред ха́ном в хуле́нії злові́рія єго́, / дерзнове́нно предста́л єси́ суди́щу нечести́вому; / убоя́вся же Стра́шнаго Суда́ Христо́ва, / ха́нськоє повелі́ніє і страх поплева́л єси́, святи́й Рома́не. / Ті́лом, я́ко розга́, ре́жемий, / в страда́ніїх уподо́бился єси́ Іа́кову Пе́рсянину / і яви́лся єси́ великому́ченик ізря́дний, / столп і утвержде́ніє Це́ркві Ряза́нстей, // засту́пник і воєво́да Український пресла́вний."]},{"h":"Молитва перша","ps":["Святи́й сла́вний великому́чениче, благові́рний кня́же Рома́не, покрови́телю і засту́пниче о́бласти Ряза́нськия! Ві́руєм і упова́єм, я́ко страда́нії і богоуго́дною жи́знію твоє́ю стяжа́л єси́ ве́лію ми́лость і дерзнове́ніє у Го́спода Бо́га і не заби́л єси́ достоя́нія твоєго́ земна́го, оте́чества на́шего, в не́мже обурева́єми ми, раби́ твої́, мно́гими напа́стьми вра́жіїми і страстьми́ жите́йськими. Ті́мже мо́лим тя: моли́твами і предста́тельством твої́м умоли́ Го́спода Бо́га, да ізба́вить нас от вся́ких бід і от всіх враго́в, ви́димих і неви́димих. О вели́кий уго́дниче Бо́жий! Вздохни́ о нас грі́шних ко Го́споду Бо́гу, да прости́ть нам вся согріше́нія на́ша, да ниспосле́ть нам благода́ть Всесвята́го Ду́ха, да преста́нем от вся́каго скверноді́йства і про́чеє вре́м'я живота́ на́шего во вся́ком благоче́стії і чистоті́ поживе́м і, та́ко благоугоди́вше Го́споду, сподо́бимся жи́зні вечноблаже́нния, пою́ще і воспіва́юще превели́коє милосе́рдіє Бо́жиє і твоє́ ми́лостивоє предстата́льство за нас у Престо́ла Бо́жия во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О пресла́вний страстоте́рпче, вели́кий уго́дниче Бо́жий, принеси́ на́шу сле́зную моли́тву Го́споду Бо́гу на́шему, уми́лостиви Єго́ к нам, грі́шним, да оти́меть от нас гнів свой пра́ведний і умири́ть страну́ на́шу многострада́льную; да утверди́ть благоде́нствіє і тишину́, да низпосле́ть нам ізоби́ліє плодо́в земни́х і да возбрани́ть враго́м на́шим оби́ду твори́ти си́рим і безпо́мощним. Припа́дающе к іко́ні твоє́й, воспомина́єм с ві́рою страда́нія твоя́, за Христа́ претерпі́нная, і мо́лим тя: не оста́ви нас і іспроси́ нам у Го́спода блага́я вре́менная і ві́чная, да сла́вим просла́вившаго тебе́ Бо́га во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Димитрію, ігумену Прилуцькому, Вологодському","e":"Prayer to St Demetrius, Abbot of Pryluky, of Vologda","secs":[{"h":"Тропар, глас 1","ps":["Сви́ше от Бо́га, преподо́бне, / благода́ть прия́л єси́ духо́вную, / і от Него́ у́бо позна́лся єси́, блаже́нне, / Того́ ра́ди і ти ду́хом позна́л єси́ лу́чшая Єго́, / бу́дущаго ві́ка пребива́ніє, / і по́стничеськи іспита́вся во свої́х оби́теліх. / І ни́ні со а́нгели ликовству́я, / Спа́су всіх за ни моли́ся, свя́те Дими́тріє, да всі вопіє́м: / Сла́ва Да́вшему ті крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Інший тропар, глас 1","ps":["Сви́ше от Бо́га, преподо́бне, / благода́ть прия́л єси́, Дими́тріє пресла́вне, / і Того́ си́лою укріпля́єм, / Єва́нгельськи ходи́ти ізво́лил єси́, / отону́ду же і от Христа́ возме́здіє трудо́в обрі́те, всеблаже́нне, / Єго́же моли́ // спасти́ся душа́м на́шим."]},{"h":"Інший тропар на стрітення образу, глас 4","ps":["Возсія́ днесь, я́ко со́лнце, / пречестни́й о́браз священнолі́пнаго твоєго́ подо́бія, / па́че со́лнця луча́ми чуде́с твої́х всіх озаря́я, / тьму бісо́вськую без ві́сти творя́, / єго́же ра́достно сріта́ху, / духо́вния ли́ки соста́вльше, / непреста́нно вопіє́м ті: / Дими́тріє, о́тче наш, моли́ Спа́са всіх / сохрани́ти град твой і страну́ на́шу, / ста́ду твоєму́ спасе́ніє подава́я // і ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["От ю́ности, преподо́бне, крест твой взем, Христу́ послі́довал єси́, / в моли́твах і поще́ніїх, во бді́ніїх же і злострада́ніїх плоть твою́ ізнуря́я. / Ті́мже і Всеви́дящеє О́ко твоя́ труди́ ви́дів, / чудеси́ тя прославля́єть, і всіх зва́ти тебі́ науча́єть: // ра́дуйся, преподо́бне о́тче Дими́тріє, по́стников удобре́ніє."]},{"h":"Інший кондак, глас 3","ps":["Жезло́м, свя́те Дими́тріє, от Бо́га да́нним ті, / лю́ди своя́ упасе́ на па́житіх зако́на живоно́сна, / зві́ря же неви́димаго шата́ніє сокруши́ под но́зі тебе́ пою́щих, // я́ко да в біда́х тя те́пла предста́теля і́мами."]},{"h":"Інший кондак на стрітення образу, глас 8","ps":["Христа́ єди́наго в жи́зні сей во слід ідти́ возжела́л єси́ / і, Того́ любо́вію земна́я отри́нув, премину́в Небе́сними, / с ли́ки А́нгел водворя́яся, неотсту́пно предстої́ши Бо́гові, / тім і ни́ні пресвято́му твоєму́ о́бразу срі́тенія пра́здник ра́достно сотворя́юще, / от неду́г ісціле́ніє приє́млем, благода́рно вопію́ще: // ра́дуйся, преподо́бне о́тче Дими́тріє, по́стников удобре́ніє."]},{"h":"Молитва","ps":["О свяще́нная главо́, преди́вний чудотво́рче, богоно́сне о́тче наш Дими́тріє! Усе́рдно припа́дающе к тебі́, мо́лимся: яви́, нам, смире́нним і грі́шним, многомо́щноє твоє́ заступле́ніє. Се бо гріх ра́ди на́ших, не і́мами дерзнове́нія ко Го́споду проси́ти Єго́ даро́в, нам благопотре́бних, но тебі́, моли́твенника к Нему́ благоприя́тного, предлага́єм і про́сим: іспроси́ нам у бла́гости Єго́ вся я́же на по́льзу душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду несумне́нну, любо́в нелицемі́рну, во іскуше́ніїх му́жество, в злострада́ніях терпі́ніє, в моли́твах постоя́нство, в благоче́стії преуспі́яніє, вожделі́нноє здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, дожди́ благовре́менни, жите́йських потре́б дово́льство, мир во днех на́ших і благослове́ніє сви́ше на вся́кая блага́я діла́ на́ша. Не забу́ди, чудотво́рче святи́й, ми́лостиво посіща́ти оби́тель свою́, гра́ди і ве́сі страни́ на́шея правосла́вния, сохраня́я і соблюда́я їх моли́твами твої́ми от вся́кого зла. Пом'яни́ всіх, ві́ру і любо́в к тебі́ іму́щих і і́м'я твоє́ моли́твенно призива́ющих, і во благи́х проше́нія їх ми́лостиво іспо́лни, осіня́я їх сви́ше святооте́чеським твої́м благослове́нієм. Єй свя́тче Бо́жий, не лиши́ і нас грі́шних твоєго́ многомо́щнаго заступле́нія, но сподо́би нас кончи́ну житія́ благу́ю улучи́ти і Ца́рствіє Небе́сноє унаслі́довати. Да воспоє́м і просла́вим ди́внаго во святи́х свої́х Бо́га на́шего, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученику Вонифатію Тарсійському","e":"Prayer to the Martyr Boniface of Tarsus","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди Вонифа́тій, / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́ Бо́га на́шего / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости / того́ моли́твами // спаси́ ду́ші на́ші."]},{"h":"Інший тропар, глас 4","ps":["К сосло́вію по́слан му́чеников, / му́ченик бил єси́ і́стинен, / пострада́в за Христа́ кріпча́йше, всехва́льне, / мощми́ же возврати́лся єси́ ві́рою посла́вшей тя, / Вонифа́тіє блаже́нне, / моли́ Христа́ Бо́га // прия́ти нам гріхо́в проще́ніє."]},{"h":"Кондак, глас 4","ps":["Свяще́ніє непоро́чноє самово́льне Тебі́ приве́л єси́, / І́же от Ді́ви тебе́ ра́ди роди́тися Хотя́щему, // свя́те вінчено́сче, прему́дре Вонифа́тіє."]},{"h":"Інший кондак, глас 6","ps":["Звізда́ сві́тлая яви́лся єси́ непреле́стная ми́рові, Со́лнця Христа́ возвіща́ющи заря́ми твої́ми, страстоте́рпче Вонифа́тіє, і пре́лесть погаси́л єси́ всю, нам же пода́вши світ, моли́ся непреста́нно о всіх нас."]},{"h":"Інший кондак, глас 4","ps":["Ізи́де к прия́тію страстоте́рпчеських моще́й і стра́ждущих зако́нні ві́ри ра́ди зря, / показа́л єси́ му́жеськи крі́пость свою́, / устреми́вся на стра́сті іспові́данієм во Христа́, / І́же приє́м по́честь побі́ди твоєго́ страда́нія, // Вонифа́тіє, при́сно моли́ за ни."]},{"h":"Молитва перша","ps":["О многострада́льний і всехва́льний му́чениче Вонифа́тіє! Ко твоєму́ заступле́нію ни́ні прибіга́єм, моле́ній нас, пою́щих тебі́, не отве́ржи, но ми́лостиво усли́ши нас. Виждь бра́тію і се́стри на́ша, тя́жким неду́гом пія́нства одержи́мия, виждь того́ ра́ди от ма́тере своєя́, Це́ркве Христо́вой і ві́чнаго спасе́нія отпа́дающия. О святи́й му́чениче Вонифа́тіє, косни́ся се́рдцю їх да́нной ті от Бо́га благода́тію, ско́ро возста́ви от паде́ній гріхо́вних і ко спаси́тельному воздержа́нію приведи́ їх. Умоли́ Го́спода Бо́га, Єго́ же ра́ди страда́л єси́, да прости́в нам согріше́нія на́ша, не отврати́ть ми́лости Своєя́ от сино́в Свої́х, но да укріпи́ть в нас трезві́ніє і целому́дріє, да помо́жеть Своє́ю десни́цею трезвя́щимся спаси́тельний обі́т свой до конця́ сохрани́ти во дні і нощі́, о нем бо́дрствующе і о нем до́брий отві́т на Стра́шнім Суди́лище да́ти. Прийми́, уго́дниче Бо́жий, моли́тви ма́терей, о ча́діх свої́х сле́зи пролива́ющих; жен честни́х, о мужеіх свої́х рида́ющих, чад си́рих і убо́гих, от пія́ниць оста́вленних, всіх нас, іко́ні твоє́й припа́дающих, і да при́йдеть сей вопль наш моли́твами твої́ми ко престо́лу Всеви́шняго дарова́ти всім по моли́твам їх здра́віє і спасе́ніє душ і тіле́с, найпа́че же Ца́рство Небе́сноє. Покри́й і соблюди́ нас от лука́ваго ловле́нія і всіх ко́зней вра́жиїх, в стра́шний час ісхо́да на́шего помози́ прейти́ непреткнове́нно возду́шниє мита́рства і моли́твами твої́ми ізба́ви ві́чнаго осужде́нія. Умоли́ же Го́спода дарова́ти нам к Оте́честву на́шему любо́в нелицемі́рную і непоколеби́мую, пред врага́ми Це́ркве святи́я ви́димими і неви́димими си́лу непобіди́мую, да покри́єть нас ми́лость Бо́жия в несконча́ємия ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́й страстоте́рпче Христо́в, во́їне Царя́ Небе́снаго, земна́я сладостра́стія презрі́вий і ко го́рнему Ієрусали́му страда́нієм возше́дий, му́чениче Вонифа́тіє! Усли́ши м'я грі́шнаго, принося́щаго от се́рдця моле́бная пі́нія, і умоли́ Го́спода на́шего Ісу́са Христа́ прости́ти вся моя́ согріше́нія, во ві́дінії і в неві́дінії мно́ю соді́янная. Єй, му́чениче Христо́в, о́браз покая́нія собо́ю показа́вий грі́шним! Бу́ди мі на зла́го сопроти́вника дия́вола твої́ми моли́твами к Бо́гу помо́щник і засту́пник; мно́го бо порива́хся ізбі́гнути сіте́й єго́ лука́вих, но у́дицею гріхо́вною уловле́н і крі́пко влачи́м от него́, не мог ізба́витися, а́ще не ти предста́неши мі, во обстоя́ніїх го́ркая терп'я́щему, і коли́ко покуша́хся пока́ятися, но лож пред Бо́гом бих. Сего́ ра́ди к тебі́ прибіга́ю і молю́ся: спаси́ м'я, свя́тче Бо́жий, от всіх зол твої́м предста́тельством, благода́тію же Всеси́льнаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Йосифу, ігумену Волоцькому","e":"Prayer to St Joseph, Abbot of Volokolamsk","secs":[{"h":"Тропар, глас 5","ps":["Я́ко по́стников удобре́ніє і отце́в красоту́, / ми́лости пода́теля, разсужде́нія світи́льника, / всі ві́рнії соше́дшеся восхва́лим, / кро́тости учи́теля, і єресе́й посрами́теля, / прему́драго Іо́сифа, Українськую звізду́, / моля́щася Го́споду, // поми́ловатися душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Житія́ треволне́нія і м'яте́ж мирськи́й, / і стра́стная взигра́нія в нічто́же вміни́в, / пусти́нний граждани́н показа́лся єси́, / мно́гих бив наста́вник, Іо́сифе преподо́бне, / мона́хов собра́тель, і моле́бник ві́рен, / чистоти́ рачи́тель. // Моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Молитва перша","ps":["О вели́кий наста́вниче, ревни́телю і учи́телю Правосла́вния ві́ри, свя́те прему́дре Іо́сифе! Прийми́ моле́ніє нас, грі́шних, тебі́ приноси́моє, і те́плим предста́тельством умоли́ в Тро́йці сла́вимаго Бо́га, да ниспосле́ть бога́тия Своя́ ми́лости нам, грі́шним, да утверди́ть во Свято́й Своє́й Правосла́вній Це́ркві пра́вую ві́ру і благоче́стіє: па́стирем єя́ да пода́сть святу́ю ре́вность о спасе́нії слове́снаго ста́да, я́ко да ві́рующих соблюду́ть, неві́рующих же і отпа́дших от і́стинния ві́ри вразум'я́ть і обратя́ть. Нам же всім іспроси́ вся благопотре́бная во вре́меннім сем житії́ і поле́зная к ві́чному спасе́нію на́шему. Пом'яни́ ста́до твоє́, є́же собра́л єси́, не забу́ди посіща́ти чад твої́х і, я́ко чадолюби́вий оте́ць, не пре́зри, ніже́ отри́ни моле́нія на́ша, но воздіжи́ ру́ці твої́ моли́твеннеї ко Го́споду Бо́гу, да отложи́ть пра́ведний гнів Свой, дви́жимий на ни, і ізба́вить нас от враг ви́димих і неви́димих, от гла́да, пото́па, меча́, смертоно́сния я́зви, наше́ствія іноплеме́нних і междоусо́бния бра́ні. Єй, премилосе́рдий засту́пниче наш, пресла́вний чудотво́рче, всіх нас упра́ви в ми́рі і покая́нії сконча́ти живо́т наш і пресели́тися со упова́нієм в блаже́нная селе́нія ра́йськая, іді́же непреста́нно славосло́виться всепі́тоє і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["О преблаже́нне і присносла́вне о́тче наш Іо́сифе! Ві́дуще твоє́ ве́ліє к Бо́гу дерзнове́ніє і к твоєму́ тве́рдому заступле́нію прибіга́юще, в сокруше́нії се́рдця мо́лим тя: озари́ нас сві́том дарова́нния тебі́ благода́ті і моли́твами твої́ми помози́ нам бу́рноє мо́ре житія́ сего́ прейти́ безм'яте́жно і приста́нища спасе́нія небла́зненно дости́гнути: порабоще́ни бо су́ще су́єтними, і гріхолюби́ви, і не́мощни є́же от обише́дших нас зол возни́кнути, ко кому́ прибі́гнем, а́ще не к тебі́, яви́вшему неоскудіва́ємоє бога́тство ми́лости в земні́м житії́ твоє́м? Ві́руєм же, я́ко і по отше́ствії твоє́м мно́жайшеє стяжа́л єси́ дарова́ніє милосе́рдовати бе́дствующим. Ті́мже у́бо, припа́дающе ни́ні к цільбоно́сній іко́ні твоє́й, умиле́нно про́сим тя, свя́тче Бо́жий: сам іскуше́н бив, помози́ і нам, іскуша́ємим; посто́м і бді́нієм попра́вий си́лу де́монськую, і нас от нападе́ній вра́жиїх защити́; препита́вий гла́дом погиба́ющих, і нам іспроси́ у Го́спода ізоби́ліє плодо́в земни́х і вся я́же ко спасе́нію потре́бная; посрами́вий єрети́чеськая мудрова́нія, Це́рков Святу́ю от єресе́й і раско́лов, і смуще́ній моли́твами твої́ми огради́: да то́жде му́дрствуєм всі, єди́нім се́рдцем сла́в'яще Святу́ю, Єдиносу́щную, Животворя́щую і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во вся ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["О вели́кий Правосла́вния ві́ри ревни́телю і учи́телю, свя́те прему́дре Іо́сифе! Прийми́ моле́ніє, от нас, грі́шних, тебі́ приноси́моє, і те́плим предста́тельством умоли́ в Тро́йці сла́вимаго Бо́га, да низпосле́ть Он бога́тия Своя́ ми́лости нам, грі́шним, і раба́м Бо́жиїм (імена́), да отложи́ть пра́ведний гнів Свой, дви́жимий на ни, да ізба́вить нас і зді помина́ємих от враг ви́димих і неви́димих. Єй, премилосе́рдий засту́пниче наш, іспроси́ моли́твами твої́ми нам проще́ніє гріхо́в, ісправле́ніє житія́ на́шего, от болі́зней і вся́ких неду́гов ісціле́ніє, от наві́тов і ко́зней дия́вольських ізбавле́ніє, па́че же спасе́ніє душа́м на́шим пода́ждь і Небе́сних благ восприя́тіє сподо́би, благода́тію і человіколю́бієм Живонача́льния Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Іоанну Рильському","e":"Prayer to St John of Rila","secs":[{"h":"Тропар, глас 4","ps":["Твої́х моще́й возвраще́нієм / оби́тель твоя́ обогати́ся, / це́рков же твоя́, приє́мши я, просвіти́ся / і, крася́щися, ві́рних созива́єть с весе́лієм / світоно́сний твой сві́тло пра́здновати день, / гряді́те, глаго́лющи, // і приймі́те благода́тей дарова́нія."]},{"h":"Інший тропар, глас 4","ps":["Ті́ло смири́в поще́нієм, / ду́шу же возви́сив пі́нієм, / сосу́д яви́ся ізбра́н Свято́му Ду́ху, / Іоа́нне, о́тче наш, / в чистоті́ се́рдця твоєго́, преподо́бне, пожи́в. / Тім, дерзнове́ніє імі́я ко Го́споду, // моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 1","ps":["Покая́нія основа́ніє, прописа́ніє умиле́нія, / о́браз утіше́нія, духо́внаго соверше́нія, / равноа́нгельноє житіє́ твоє́ бисть, преподо́бне. / В моли́твах у́бо і поще́ніїх, і в слеза́х пребива́вий, / о́тче Іоа́нне, // моли́ Христа́ Бо́га о душа́х на́ших."]},{"h":"Кондак, глас 2","ps":["Тве́рдим умо́м і непреста́нними моли́твами / бори́теля врага́ си́лу всегуби́тельную до конця́ побори́в, / досто́йно от Христа́ просла́вился єси́, / Іоа́нне всеблаже́нне. / Тім твої́х днесь моще́й возвраще́нія / сві́тлий соверша́юще пра́здник во весе́лії, / согла́сно вопіє́м ті: / ста́ду і лю́дем твої́м ти єси́ с Бо́гом, о́тче преподо́бне, // похвала́ і утвержде́ніє."]},{"h":"Інший кондак, глас 6","ps":["Благода́тію Бо́жиєю нас обогати́л єси́ / і ді́ли благи́ми ізвісти́л єси́, / зва́нієм яви́ся, Іоа́нне, уго́дник Христа́ Бо́га. / В моли́твах і пості́х дарова́ній Бо́жия Ду́ха іспо́лнися / і бисть неду́гом прогони́тель // і засту́пник душа́м на́шим."]},{"h":"Інший кондак, глас 2","ps":["В моли́твах бо́дренно не усипа́я / і в пі́ніїх непреста́нних А́нгелом подо́б'яся, / в гроб вшел єси́, тлі́нную жизнь оста́вив, / і к Небесі́ преше́л єси́ / на нетлі́ніє, Іоа́нне о́тче, / от сме́рти бо к животу́ ві́чному // тя пресели́ Христо́с Бог, я́ко Своєго́ уго́дника."]},{"h":"Інший кондак, глас 2","ps":["Моля́щим тя теплі́йший засту́пниче / і прося́щим скорі́йший послу́шателю, / преподо́бне о́тче Іоа́нне, / прийми́ моле́ніє на́ше / і Христа́ умоли́ поми́ловати нас, // Єди́наго Преблага́го і Многоми́лостиваго."]},{"h":"Інший кондак, глас 8","ps":["А́нгельському житію́ поревнова́в, преподо́бне, / вся земна́я оста́вив, ко Христу́ прите́кл єси́, / і того́ за́повідьми огражда́яся, яви́лся єси́ столп непоколеби́м от вра́жиїх нападе́ній. Тім зове́м ті: // ра́дуйся, о́тче Іоа́нне, світи́ло пресві́тлоє."]},{"h":"Молитва перша","ps":["Земна́я звіздо́ чуде́сная, я́же от преді́л Сре́дця гра́да возсія́вшая, і сві́щниче живи́й, і́же всю зе́млю Бо́лгарськую сві́том пра́вди Бо́жия осіява́яй, преди́вний в по́стниціх уго́дниче Бо́жий, о́тче Іоа́нне, преподо́бних у́бо ра́дованіє, Це́ркве Бо́лгарськия украше́ніє, ві́ри Правосла́вния крі́пкоє утвержде́ніє, ско́рий помо́щниче к тебі́ с ві́рою і любо́вію притека́ющим і вели́кий пред Го́сподем о всіх нас предста́телю! Прийми́, преблаже́нне, моле́нія на́ша і умоли́ Христа́ Бо́га на́шего, я́ко да всі, тобо́ю неви́димо охраня́ємі і сою́зом бра́тськия любве́ связу́ємі, лю́діє слове́нстії в ми́рі пребива́ють і благоче́стії, і да ізба́вить їх Госпо́дь от враг ви́димих і неви́димих, от наше́ствія іноплеме́нник, от неду́га і гла́да, от вся́кия ско́рби і вся́каго зла. Предстоя́щим же зді і моля́щимся пред честно́ю ра́кою моще́й твої́х іспроси́, преподо́бне, у Го́спода на́шего Ісу́са Христа́ вся, я́же ко спасе́нію проше́нія, да всі с тобо́ю непреста́нно прославля́єм всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне о́тче Іоа́нне, уго́дниче Госпо́день преізря́дний, те́плий наш засту́пниче і везді́ в ско́рбіх ско́рий помо́щниче! Помози́ мні, грі́шному і уни́лому, в настоя́щем сем житії́ і умоли́ Го́спода Бо́га дарова́ти мі оставле́ніє всіх мої́х гріхо́в, єли́ко согріши́х от ю́ности моєя́ во всем житії́ моє́м ді́лом, сло́вом, помишле́нієм і всі́ми мої́ми чу́встви. І во ісхо́ді душі́ моєя́ помози́ мі, окая́нному, і умоли́ Го́спода Бо́га, всея́ тва́рі Соді́теля, ізба́вити м'я возду́шних мита́рств і ві́чнаго муче́нія, да всегда́ прославля́ю Отця́ і Си́на і Свята́го Ду́ха і твоє́ ми́лостивноє предста́тельство, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірному князю Владиславу Сербському","e":"Prayer to the Right-believing Prince Vladislav of Serbia","secs":[{"h":"Тропар, глас 4","ps":["І́же ко́рене честна́го о́трасль сла́вная, благові́рний кня́же Владисла́ве, в оте́честві твоє́м до́брі ца́рствовал єси́, і Ца́рствіє Небе́сноє получи́вий, владі́єши сла́вою і че́стію вели́кою. Ті́мже не забу́ди язи́ков слове́нських і правосла́вним лю́дем на сопроти́вния спобо́рствуй."]},{"h":"Кондак, глас 6","ps":["Царю́ Небе́сному подража́я, Уті́шителю і Пода́телю жи́зні, бога́тства твоя́ убо́гим расточа́ше, і бил єси́ прибі́жище вся́кому стра́ждущему, утіше́ніє і заступле́ніє оби́димому, крі́пость і огражде́ніє страні́ твоє́й, Владисла́ве богоблаже́нне."]},{"h":"Молитва","ps":["О, святи́й і сла́вний уго́дниче Христо́в, царю́ Владиславе! Ско́рий помо́щниче і те́плий засту́пниче с ві́рою притека́ющих к тебі́. Предстоя́ со дерзнове́нієм Небе́сному Царю́, іспроси́ у Него́ проще́ніє согріше́ній на́ших. І о є́же ізбавиться нам от всегуби́тельния я́зви, тру́са, пото́па, огня́, меча́, і ві́чния ка́зні. Моли́ Бла́гость Єго́, є́же уще́дрити вся́кую страну́ христия́нськую. Ісхода́тайствуй у Го́спода на враги́ побі́ду і одолі́ніє, всему́ же ми́ру тишину́, к Правосла́вію обраще́ніє, тве́рдость во ві́рі і преспі́яніє во благоче́стії. Нам же, чту́щим па́м'ять твою́, іспроси́ благода́тноє укріпле́ніє в моли́тві і ді́ліх благи́х, да благоуго́дноє Владике на́шему Христу́ Бо́гу зді творя́ще, сподо́бимся моли́твами твої́ми, блажене, наслі́довати Ца́рство Небе́сноє, для вечного прославле́нія Єго́ со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь!"]}],"notes":[]},{"u":"Молитва преподобному Ахілі, дияконові Печерському","e":"Prayer to St Achilles, Deacon of the Caves","secs":[{"h":"Тропар, глас 8","ps":["По́стничеськоє житіє́ облобиза́в / і мно́гими труди́ от млади́х ногте́й себі́ обложи́в, / на степе́нь дия́конства проізведе́н бив, всече́стне, / в ко́єм служи́л єси́ в це́ркві Бо́жия Ма́тере непоро́чне, / Є́йже моли́ся, // во є́же спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Ве́ліє імі́л єси́ воі́стину воздержа́ніє, сла́вне, / і мно́гоє показа́л єси́ поще́ніє, о Ахи́ло, / зане́ єдва́ єди́ною в седьми́ці, / і се єди́ну ма́лу просфору́ снеда́ше / і бді́нним стоя́нієм к Нему́ ви́ну друча́шеся, / тім тя, я́ко по́стника і преподо́бним соо́бщника // чту́ще, ублажа́єм."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Ахило! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х і благоприя́тних моли́твах к Бо́гу: пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя: помина́й нас недосто́йних у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши, не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами, у престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться, ві́дуще у́бо тя воі́стину і по сме́рті жива́ су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния муки́ да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святому мученику Уару Єгипетському","e":"Prayer to the Holy Martyr Uar of Egypt","secs":[{"h":"Тропар, глас 4","ps":["Во́їнством святи́х страстоте́рпець стра́ждущих зако́нні, / зря о́ніх, показа́л єси́ му́жеськи крі́пость свою́. / І устреми́вся на страсть во́лею, / і умре́ти вожделе́за Христа́, / І́же прия́л єси́ по́честь побі́ди твоєго́ страда́нія, Уа́ре, // моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Христу́ послі́дуя, му́чениче Уа́ре, / Того́ іспи́в ча́шу, / і муче́нія вінце́м ув'язе́ся, / і со А́нгели ликовству́єши: // моли́ непреста́нно за ду́ші на́ша."]},{"h":"Молитва","ps":["О, святи́й му́чениче Уа́ре досточу́дний, ре́вностію по Влади́ці Христу́ разжига́єм, Небе́снаго Царя́ пред мучи́телем іспові́дал єси́, і о Нем усе́рдно пострада́л єси́, і ни́ні Це́рков почита́єть тя, я́ко прославля́ємаго от Влади́ки Христа́ сла́вою Небе́сною, І́же дарова́ тебі́ благода́ть вели́каго к Нему́ дерзнове́нія, і ни́ні предстої́ши Єму́ со А́нгели, і во Ви́шніх лику́єши, і зри́ши я́сно Святу́ю Тро́йцю, і сві́том Безнача́льнаго Сія́нія наслажда́єшися, воспом'яни́ і на́ших сро́дников томле́ніє, уме́рших в нече́стії, прийми́ на́ше проше́ніє, і я́коже Клеопа́трин род неві́рний моли́твами твої́ми от ві́чних мук свободи́л єси́, та́ко воспом'яни́ єли́ці противобо́жні погребе́нния, уме́ршія некреще́нними, потщи́ся іспроси́ти о́ним от ві́чния тьми ізбавле́ніє, да всі єди́ними усти́ і єди́нім се́рдцем восхва́лим Премилосе́рднаго Творця́ во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва всім святим","e":"Prayer to All the Saints","secs":[{"h":"Тропар, глас 4","ps":["Бо́же оте́ць на́ших, творя́й при́сно с на́ми по Твоє́й кро́тости, не отста́ви ми́лость Твою́ от нас, но моли́твами їх в ми́рі упра́ви живо́т наш."]},{"h":"Інший тропар, глас 2","ps":["Апо́столи му́ченици і проро́ци, святи́теліє, преподо́бнії і пра́веднії, до́брі по́двиг соверши́вшії і ві́ру соблю́дшії, дерзнове́ніє іму́ще ко Спа́су, о нас Того́, я́ко бла́га, молі́те, мо́лимся, спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["І́же во всем ми́рі му́ченик Твої́х, я́ко багряни́цею і ви́ссом, кровми́ Це́рков Твоя́ украси́вшися, ті́ми вопіє́м Ті, Христе́ Бо́же: лю́дем Твої́м щедро́ти Твоя́ низпосли́, мир жи́тельству Твоєму́ да́руй і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 8","ps":["Апо́стол пропові́даніє, і оте́ць догма́ти, Це́ркві єди́ну ві́ру запечатлі́ша, я́же і ри́зу нося́щи і́стину, істка́нну от є́же сви́ше богосло́вія, ісправля́єть і сла́вить благоче́стія вели́коє та́їнство."]},{"h":"Інший кондак, глас 8","ps":["Я́ко нача́тки єстества́ Насади́телю тва́рі вселе́нная прино́сить Ті, Го́споди, Богоно́сния му́ченики; тіх моли́твами в ми́рі глубо́ці Це́рков Твою́, жи́тельство Твоє́ Богоро́дицею соблюди́, Многоми́лостиве."]},{"h":"Молитва перша","ps":["Бо́же святи́й і во святи́х почива́яй, трисвяти́м гла́сом на Небесі́ от А́нгел воспіва́ємий, на землі́ от челові́к во святи́х Свої́х хвали́мий, да́вий Святи́м Твої́м Ду́хом коєму́ждо благода́ть по мі́рі дарова́нія Христо́ва, і то́ю поста́вивий Це́ркві Твоє́й Святі́й о́ви апо́столи, о́ви проро́ки, о́ви же благові́стники, о́ви па́стирі і учи́тели, ї́хже сло́вом про́повіді, Тебі́ Самому́ ді́йствующему вся во всіх, мно́зі соверши́шася, святі́ї в коє́мждо ро́ді і ро́ді, разли́чними благоді́тельми благоугоди́вшії Тебі́, і к Тебі́, нам о́браз до́брих по́двигов свої́х оста́вивше, в ра́дості преше́дшії, гото́ві, в нем же са́мі іскуше́ни би́ша, і нам напа́ствуємим помога́ти. Сих святи́х всіх і (і́м'я святого) воспомина́я і їх богоуго́дноє похваля́я житіє́, Тебі́ Сама́го, в них ді́йствовавшаго, восхваля́ю, і о́ніх благотворе́нія Твоя́ дарова́нія би́ти ві́руя, прилі́жно молю́ Тя, Свя́те святи́х, даждь мі грі́шному послі́довати їх уче́нію, житію́, любві́, ві́рі, долготерпі́нію, і їх моли́твенною по́мощію, па́че же Твоє́ю вседі́йствующею благода́тію, Небе́сния с ни́ми сподо́битися сла́ви, хва́ляще Пресвято́є і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О преблаже́ннії уго́дниці Бо́жії, всі святі́ї, предстоя́щії Престо́лу Пресвяти́я Тро́йці і наслажда́ющіїся неізрече́ннаго блаже́нства! Се ни́ні, в день о́бщаго ва́шего торжества́, ми́лостивно при́зріте на нас, ме́ньших бра́тій ва́ших, принося́щих вам сіє́ хвале́бноє пі́ніє і хода́тайством ва́шим прося́щих ми́лості і отпуще́нія гріхо́в у Преблага́го Го́спода: ві́ми бо, воі́стину ві́ми, я́ко вся, єли́ка восхо́щете, іспроси́ти у Него́ мо́жете. Ті́мже у́бо смире́нно мо́лимся вам: молі́те ми́лостиваго Влади́ку, да пода́сть нам дух ва́шея ре́вности ко хране́нію святи́х Єго́ за́повідей, я́ко да те́кше по стопа́м ва́шим, возмо́жем земно́є по́прище в доброді́тельном житії́ без поро́ка прейти́ і в покая́нії дости́гнути пресла́вних селе́ній ра́йських, і та́мо ку́пно с ва́ми прославля́ти Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["К вам, о святі́ї всі і (і́м'я святого), я́ко путево́дним свети́льникам, дія́ньми свої́ми освети́вшим путь Небе́снаго восхо́да, аз многогрі́шний смире́нно колі́на се́рдця моєго́ преклоня́ю і із глубини́ душі́ взива́ю: умолі́те о мні Человіколю́бця Бо́га, да не попу́стить мі єще́ блужда́ти по распу́тіям гріха́, но да просвіти́ть мої́ ум і се́рдце сві́том благода́ті Своєя́, я́ко да то́ю озаря́єм і подкрепля́єм, возмогу́ про́чеє вре́м'я земна́го житія́ пра́вою стезе́ю непреткнове́нно прейти́ і хода́тайством ва́шим к Преблаго́му Го́споду сподо́блюся, поне́ вма́лі прича́стник би́ти духо́вния ва́шея трапе́зи в Небе́сном черто́зі Царя́ сла́ви. Єму́же со Безнача́льним Єго́ Отце́м і Пресвяти́м, Благи́м і Животворя́щим Ду́хом бу́ди сла́ва, честь і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["О, святи́й уго́дниче Бо́жий (ім’я), по́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єси́ Госпо́дь всім лю́б'ящим Єго́; ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всеми́лостивому Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і по́мощі нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, апо́столи, му́ченици, проро́ци і всі святі́ї, і чтим святу́ю па́м'ять ва́шу, ви бо мо́лите за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва святителю Павліну Милостивому","e":"Prayer to St Paulinus the Merciful","secs":[{"h":"Тропар, глас 4","ps":["Уго́дниче Бо́жий ми́лостивий, / святи́телю о́тче наш Павли́не, / воі́стину доброво́льно зрак раба́ приї́м / і тім Самому́ Христу́ послі́дуя, / положи́л єси́ ду́шу твою́ за лю́ди своя́, і от зла́го пліне́нія тіх ізба́вил єси́. / Свободи́ і нас моли́твами твої́ми / от пліне́нія страсте́й на́ших / научи́ нас ми́лостивни к бли́жнім свої́м би́ти, / да пребу́деть чрез то ми́лостив і к нам Госпо́дь, // спаса́яй ду́ші на́ша, я́ко благ і человіколю́бець."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, о́тче наш, святи́телю Павли́не! Смире́нно і ума́лено і́м'я твоє́, но ве́лія єсть во святи́х Бо́жиїх сла́ва твоя́, і ми грі́шнії вседушевно хо́щем, да і в нас, лю́діх твої́х, звенить она́ я́ко той са́мий кампа́н, єго́же ти пе́рвий устрої́тель бил єси́. Ка́ко не диві́мся вели́чію смиренного ду́ха твоєго́ і послуша́нію глаго́лу Христа́ Спа́са, ре́кшаго: а́ще кто хо́щеть по Мні іти́, да отве́ржеться себі́, во́зьметь крест свой, і по Мні гряде́ть? І́бо ти, свя́тче, не то́кмо імі́нія своя́ до послі́дняго хлі́ба насущнаго неімущим разда́л єси́, но і себі́ самаго́ во́лею в ра́бство пре́дал єси́, да свобо́дна от пліне́нія ва́рварськаго си́на вдови́ча соді́лаєши, сего́ ра́ди і даде́ ті Госпо́дь да́ри Своя́ оби́льния, і в них велича́йший дар прозрі́нія і проро́чества, я́ко зрел єси́ гряду́щая я́ко настоя́щая. Коли́ко ра́достна бисть душа́ твоя́ любвеоби́льная, єгда́ проше́нієм свої́м пред князе́м вандальським вся лю́ди гра́да і страни́ твоєя́ із плі́на їх, я́ко Моїсей ізра́їльтянин із Єги́пта, ізве́л єси́. Ві́ми же, я́ко і до днесь, у Бо́жия небе́снаго предстоя́ престо́ла, ти нас земни́х не забива́єши і проше́нія на́ша усе́рдная ско́ро ісполня́єши, заключе́нним, і у́зником, і пліне́нним свобо́ду моли́твами свої́ми да́руя і на вся́коє ді́ло милосе́рдія нас сло́вом і житіє́м свої́м наставля́я. От сих, ї́хже от зла́го обстоя́нія ти ми́лостивно ізба́вил єси́, прими́, дру́же Христо́в і подража́телю Єго́ ві́рний, нижа́йшеє поклоне́ніє і благодаре́ніє. О тіх же, єли́ці і дони́ні в ско́рбі і лише́нії драгоці́ннаго да́ра свобо́ди пребива́ють, не преста́ни умоля́ти милосе́рднаго Бо́га о осла́бі і свобо́ді, і ізведенії із темни́ці душ їх. Да всі вку́пі, чту́ще ни́ні святу́ю па́м'ять твою́, просла́вим і чрез тебі́ подаю́щаго нам блага́я Своя́ всіх благ Пода́теля Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]}];
export default D;
